/*global require: false, define: false, Class: false */
define('app/PlayerModel',
    [
        "jQuery",
        "Backbone",
        "jquery.browser"
    ],
    function (
        $,
        Backbone
    ) {
        

        return Backbone.Model.extend({
            /**
             * デフォルト値
             */
            defaults : {
                /**
                 * フッターに表示するプレイヤーの名前
                 */
                playerName : "Visionary College",
                /**
                 * サーバーから問題集を取得するためのキー
                 */
                au_token : 'au_token20140209105755',
                /**
                 * レッスン番号
                 *
                 */
                lesson_no : 9,
                /**
                 * サービス名
                 * cw
                 * ac2weeklydrill : AC2 週刊英語ドリル
                 * ac2trainingbank : AC2 トレーニングバンク
                 */
                visionary : 'cw',
                /**
                 * コースワークかどうか
                 */
                isCoursework : false,
                /**
                 * コースワークのナンバー
                 */
                course_no  : 0,
                /**
                 * 問題番号
                 */
                question_no  : 0,
                /**
                 * 複数問題の番号
                 * TODO ここに表示するのは変
                 */
                comprehension_no  : 0,
                /**
                 * アサイン番号
                 * TODO アサインした場合のみ使用する
                 * ここに初期値を設定するのは変、消すこと
                 * previewの場合は使用しない。
                 */
                assign_no  : 263,

                /**
                 * プレビューモードかどうか
                 */
                isPreview : false,

                /**
                 * プレビューモードの場合に必要
                 * combination  問題プレビュー（複合１問のみのプレビュー）
                 * single  問題プレビュー（単品１問のみのプレビュー）
                 * book  ブックプレビュー（ブックプレビューはドリルモードでプレビューする）
                 * assign  アサインプレビュー（アサイン時のテストタイプでプレビューする
                 * assign_vc　？　assign_vcが使用される場合を確認すること
                 */
                previewType : "assign_vc",

                /**
                 * bookType
                 *
                 * 1:テスト／ドリル（PC限定）
                 * 2:テスト／ドリル（PC、スマフォ）
                 * 3:アンケート
                 */
                bookType : 1,
                /**
                 * Coldfusionでサーバーからデータを取得するときに使用すするメソッド名
                 */
                cfc_method : 'bookXml',

                /**
                 * 回答を保存する URL
                 * TODO これは必ずはいるのか？
                 *
                 */
                save_answer_url : '../flash/data_manipulate.cfc',
                /**
                 * 継続かどうか？
                 */
                isContinue : false,
                /**
                 * bookカバーの詳細を隠すかどうか
                 */
                hideBookCoverOption: false,
                /**
                 * 言語設定
                 */
                culture : "",
                /**
                 * iscrollを使用するかどうか
                 * OK
                 */
                /**
                 *
                 */
                isUseIScroll : false,
                isMobile: false,
                /**
                 * 解説にiFrameを使うかどうか？
                 */
                isDescriptionIFrame: false,
                /**
                 * s:シングルカラム　w:ダブルカラム
                 */
                matchingQuestionLayout : "w",


                /**
                 * スタート画面のデザイン
                 *
                 * cover:　通常 , simple: 画像
                 */
                coverview: "cover",

                /**
                 * Footerにもメニューを出すかどうか
                 */
                isShowFooterMenu: false



            },
            initialize: function () {
                this.set("isMobile", this.isMobile());
            },
            isPC: function () {
                return !($.os.name === 'ipad' || $.os.name === 'iphone' || $.os.name === 'ipod' || ($.os.name === "linux" && $.browser.name === "safari"));
            },

            isMobile: function () {
                return ($.os.name === 'iphone' || $.os.name === 'ipod' || ($.os.name === "linux" && $.browser.name === "safari") || ($.os.name === "linux" && $.browser.name === "chrome"));
            },

            /**
             * Flash Playerがあるかどうか？
             * 使ってない？
             *
             * @returns {boolean}
             */
            haveFlashPlatyer: function () {

                var has = false,
                    _UA = navigator.userAgent;

                if (this.isPC()) {
                    has = true;
                } else if ($.os.name === 'iphone' || $.os.name === 'ipod') {
                    has = false;
                } else if (_UA.search('Android') > -1) {

                    has = _UA.search(/Android 4/) <= -1;

                } else {
                    has = true;
                }


                return has;

            },

            /**
             * スタートページを表示するかどうか
             *
             * @returns {boolean}
             */
            isViewStartPage: function () {
                if (this.get("bookType") === 3 || this.get("bookType") === 4) {
                    // アンケート、レポートの場合スタートページを表示しない
                    return false;
                }

                if (this.get("previewType") === "combination" || this.get("previewType") === "single") {
                    // プレビューで、複数問題、単体問題のみの場合は、スタートページを表示しない
                    return false;
                }

                return true;
            }

        });
    }
);

/*global $: false, require: false, define: false, Class: false */
define('app/CombinationQuestion',
    [
        "Backbone"
    ],
    function (
        Backbone
    ) {
        
        return Backbone.Model.extend({

            defaults: {

                /** 複合問題No */
                no: "",
                /** 複合問題タイプ */
                questionType: "",
                /** タイトル */
                title: null,
                /** 配点 */
                point: -1,
                /** 指示文 */
                direction: "",
                /** パッセージ */
                passage: "",
                /** 音声 */
                sound: "",
                /** 画像 */
                image: "",
                /** 問題 */
                questions: [],
                /** 日本語訳 */
                jp_script: "",
                /** 英文スクリプト */
                en_script: "",
                /** 英文スクリプト(英語か中国語か) */
                en_script_lang: "en",
                /** 再生回数 */
                sound_plays: 0,
                /** １語分のスピード（秒） */
                speed: 1,

                questionNumber: -1
            },
            /**
             * 入れ子のBackboneオブジェクトをJSONに変換
             *
             * @returns {*}
             */
            toDEEPJSON: function () {


                var deepJSON, childs;

                deepJSON =  this.toJSON();

                childs = [];
                $.each(this.get("questions"), function (i, val) {
                    childs.push(val.toJSON());
                });

                deepJSON.questions = childs;


                return deepJSON;
            },
            setQuestionNumber: function () {

                window.console.log("setQuestionNumber");


                var questionNumber,
                    questions,
                    s,
                    e;


                questionNumber = 0;

                questions = this.get("questions");


                s = questions[0].get("questionNumber");


                e = questions[questions.length - 1].get("questionNumber");

                if (s === e) {
                    //１問の場合

                    questionNumber = s;
                } else {
                    //複数問の場合

                    questionNumber = s + " - " + e;
                }


                this.set("questionNumber", questionNumber);

            }

        });


    }
);

