/**
 * Question
 */
/*global require: false, define: false, Class: false */
define('app/question/Question',
    [
        "jQuery",
        "Backbone",
        'text!app/templates/saveAnswerXML.html'
    ],
    function (
        $,
        Backbone,
        template
    ) {

        

        return Backbone.Model.extend({
            /**
             * 解答保存用テンプレート
             */
            template: template,
            /**
             * デフォルト値（このModelが管理する範囲）
             */
            defaults: {
                /*
                 * プロパティー
                 */
                /** 問題NO（サーバーでのID） */
                no : null,
                /** タイトル */
                title : null,
                /** 問題タイプ */
                questionType : null,
                /** スキルタイプ */
                skillType : "",
                /** 配点 */
                point : -1,
                /**　解答が変化したかどうか */
                _chengeAnswer : false,
                /** 入力した答え */
                yourAnswer : "",
                /** 問題番号(1から始まる) */
                questionNumber : -1,
                /** 複合問題ID */
                combinationId : -1,

                /**
                 * 正答
                 *
                 * TODO ここが配列なので、yourAnswerと===で比較すると、すべて不正解になる。
                 * 対応済:
                 * MultipleChoiceQuestion.js
                 * MultipleCorrectQuestion.js
                 * PopUpQuestion.js
                 * SortingAQuestion.js
                 * UnderLineChoiceQuestion.js
                 *
                 * @type {Array}
                 */
                answers : [],
                /** 音声のURL */
                sound : "",
                /** 画像のURL */
                image : "",
                /** 指示文 */
                direction : "",
                /** 問題文 */
                question : "",
                /** 解説*/
                description : "",
                /** 解答結果*/
                answered : null,
                /** 言語 */
                lang : "",

                /** レビュー */
                review : "",

                /**
                 * テストモードかどうか
                 * 音声の再生に利用する　テストモードは１回のみ再生する
                 */
                isTestMode : false,

                /**
                 * テストモードの音声を再生したかどうか？
                 */
                isTestModeSoundPlayed : false,

                /** 自動採点するかどうか？ **/
                isAutoScore : true

            },
            /**
             * 取得した問題データをパースする
             *
             * @param elm
             */
            parseQuestionData: function (elm) {


                window.console.log("parse()");

                this.set("no",           $(elm).attr("no"));
                this.set("title",        $(elm).find("title").text());
                this.set("questionType", $(elm).attr("type"));
                this.set("skillType",    $(elm).attr("skillType"));
                this.set("lang",         $(elm).attr("lang") || "ja");
                this.set("point",        Number($(elm).attr("point")));
                this.set("sound",        $(elm).find("sound").text());
                this.set("image",        $(elm).find("image").text());

                if ($(elm).find("yourAnswer").size()) {
                    this.set("yourAnswer", $(elm).find("yourAnswer").text());
                }

                if ($(elm).find("review").size()) {
                    this.set("review", $(elm).find("review").text());
                }


                this.set("direction", $(elm).find("direction").text());

                window.console.log(":1:" + this.get("direction"));

                this.set("direction",  this.get("direction").replace(/(lang=["'](.*)["'])/gm, function (word, $1, $2) {

                    //console.log(word);
                    //console.log($2);

                    return word + ' ' + 'class="lang-' + $2 + '"';
                }));



                window.console.log(":2:" +  this.get("direction"));


                this.set("description", $(elm).find("description").text());

                this.set("question", $.StringUtilPlugin.parseBr($.trim($(elm).find("questionText").text())));


                var answers = $(elm).find("answer").map(function () {
                    return $(this).text();
                }).get();

                this.set("answers", answers);

            },
            /**
             * 解答を保存する
             *
             * @param yourAnswer
             */
            setYourAnswer: function (yourAnswer) {

                console.log("setYourAnswer:" + yourAnswer);


                this.set("yourAnswer",  yourAnswer);
                this.set("_chengeAnswer", true);
            },

            /**
             * 解答を確認する
             */
            checkAnswer: function () {
                //サブクラスが実装する
                return null;
            },

            /**
             * サーバーに渡す解答情報XMLを作成する
             */
            _createServerSendResultXML: function (resultData) {

                var view, resultXML;

                view = {
                    'resultData': resultData
                };

                resultXML = "";

                if (this.isAnswerd()) {
                    resultXML = $.mustache(this.template, view);
                }


                return resultXML;
            },

            /**
             * 解答したかどうか
             */
            isAnswerd: function () {
                return this.get("yourAnswer") !== "";
            },


            /**
             * 複合問題かどうか
             */
            isCombinationQuestion: function () {
                console.log("isCombinationQuestion:::" + this.get("combinationId"));
                return this.get("combinationId") !== -1;
            }

        });

    }
);


/**
 * 択一問題
 */
/*global require: false, define: false, Class: false */
define('app/question/MultipleChoiceQuestion',
    [
        "Underscore",
        "jQuery",
        "app/question/Question"
    ],
    function (
        _,
        $,
        Question
    ) {
        

        var MultipleChoiceQuestion =  Question.extend({

            /**
             * @override
             */
            defaults:
                {
                    /** 選択肢 */
                    choices : [],
                    /** 選択肢をシャッフルするかどうか */
                    shuffleChoices : false,
                    /** ボタンを横に並べるかどうか */
                    isHBox : false,
                    /** 横にならべる最大の文字数 */
                    hBoxMaxSize : 21
                },


            /**
             * @override
             * @param elm
             */
            parseQuestionData: function (elm) {
                Question.prototype.parseQuestionData.apply(this, arguments);

                if ($(elm).attr("type") === "trueFalse") {
                    this.set("isHBox", true);
                }

                var scope = this;


                this.set("choices", $("choices choice", elm).map(function () {
                    return {
                        "index": $(this).attr("no"),
                        "text": $(this).text(),
                        "lang": scope.get("lang")
                    };
                }).get());



                if (this.getChoiceStringLength($("choices choice", elm)) <= this.get("hBoxMaxSize")) {
                    this.set("isHBox", true);
                }



                if ($(elm).find("choices").attr("shuffleChoices")) {
                    this.set("shuffleChoices", ($(elm).find("choices").attr("shuffleChoices") === "true") ? true : false);
                }

                if (this.get("shuffleChoices")) {
                    //設問をシャッフルする
                    this.set("choices", _.shuffle(this.get("choices")));
                }

            },
            /**
             * 選択肢の文字列の長さを返す
             *
             * ボタン間のマージンを3文字分追加した選択肢の文字数
             * @param $el
             * @returns {Number}
             */
            getChoiceStringLength: function ($el) {
                var choiceLength = $el.map(function () {
                    return $(this).text();
                }).get().join("   ").length;

                return choiceLength;
            },

            /**
             * @override
             * @returns {*}
             */
            checkAnswer: function () {

                if (this.get("_chengeAnswer") === false && this.get("answered") !== null) {
                    return this.get("answered");
                }

                this.set("_chengeAnswer", false);

                var answered = {
                    judges: false,
                    //正解フラグ　（0:不正解　1:正解　2:部分点　）　
                    correct_flag: 0,
                    answerPoint: 0,
                    resultData: [],
                    resultXML: ""
                };

                answered.judges = (this.get("answers").toString() === this.get("yourAnswer"));

                //正解の場合
                if (answered.judges) {
                    answered.answerPoint = this.get("point");
                    answered.correct_flag = 1;
                }

                answered.resultData = [
                    {
                        "judge": (this.get("answers").toString() === this.get("yourAnswer")),
                        "yourAnswer": this.get("yourAnswer")
                    }
                ];

                answered.resultXML = this._createServerSendResultXML(answered.resultData);

                this.set("answered", answered);
                return answered;

            }
        });

        /**
         * defaults変数をマージ
         */
        _.extend(MultipleChoiceQuestion.prototype.defaults, Question.prototype.defaults);

        return MultipleChoiceQuestion;
    }
);


/**
 * 下線問題
 */
/*global require: false, define: false, Class: false */
define('app/question/UnderLineChoiceQuestion',
    [
        "Underscore",
        "jQuery",
        "app/question/Question"
    ],
    function (
        _,
        $,
        Question
    ) {
        

        var UnderLineChoiceQuestion = Question.extend({
            /**
             * @override
             */
            defaults: {
                questionParsedString : ""
            },
            /**
             * @override
             * @param elm
             */
            parseQuestionData: function (elm) {
                Question.prototype.parseQuestionData.apply(this, arguments);


                //answerを作りだす（暫定版）
                var wordIndex, scope;


                wordIndex = 0;
                scope = this;

                this.get("question").replace(/\[([\s\S]+?)\]/gm, function (word, $1) {

                    if (word.match(/\[\*([\s\S]+?)\*\]/gm)) {

                        //正答は１から始まる
                        scope.set("answers", []);

                        scope.get("answers").push(wordIndex + 1);
                    }

                    wordIndex++;
                    return '';
                });


                //[**]を[]に変換する
                this.set("questionParsedString", this.get("question").replace(/\[\*([\s\S]+?)\*\]/gm, '[$1]'));

                this.set("questionParsedString", this.get("questionParsedString").replace(/\[([\s\S]+?)\]/gm, '<span class="underLinePoint"><span><div class="chackmarkicon"></div>$1</span></span>'));

            },
            /**
             * @override
             * @returns {*}
             */
            checkAnswer: function () {
                if (this.get("_chengeAnswer") === false && this.get("answered") !== null) {
                    return this.get("answered");
                }

                this.set("_chengeAnswer", false);


                var answered = {
                    judges: false,
                    //正解フラグ　（0:不正解　1:正解　2:部分点　）　
                    correct_flag: 0,
                    answerPoint: 0,
                    resultData: [],
                    resultXML: ""
                };

                answered.judges = (this.get("answers").toString() === this.get("yourAnswer"));


                //正解の場合
                if (answered.judges) {
                    answered.answerPoint = this.get("point");
                    answered.correct_flag = 1;
                }

                answered.resultData = [
                    {
                        "judge": (this.get("answers").toString() === this.get("yourAnswer")),
                        "yourAnswer": this.get("yourAnswer")
                    }
                ];

                answered.resultXML = this._createServerSendResultXML(answered.resultData);


                this.set("answered", answered);
                return answered;
            }
        });


        /**
         * defaults変数をマージ
         */
        _.extend(UnderLineChoiceQuestion.prototype.defaults, Question.prototype.defaults);

        return UnderLineChoiceQuestion;
    }
);


