/**
 * Clozeテスト
 *
 */
/*global require: false, define: false, Class: false */
define('app/question/ClozeTestQuestion',
    [
        "Underscore",
        "jQuery",
        "app/question/Question",
        'text!app/templates/saveAnswerXML2.html'
    ],
    function (
        _,
        $,
        Question,
        template

    ) {
        

        var ClozeTestQuestion = Question.extend({
            /**
             * @override
             */
            template: template,
            /**
             * @override
             */
            defaults: {
                /** 部分点 */
                partialPoint : false,

                /** パース後の問題文 */
                questionParsedString : false

            },
            /**
             * @override
             * @param elm
             */
            parseQuestionData: function (elm) {
                Question.prototype.parseQuestionData.apply(this, arguments);

                if ($(elm).attr("partialPoint")) {
                    this.set("partialPoint", ($(elm).attr("partialPoint") === "true") ? true : false);
                }


                var scope = this;


                //入力しない部分は<span>ではさむ
                this.set("question", this.get("question").replace(/(.*?)(\[([\s\S]+?)\]|$){1}/gm, function (word, $1, $2) {
                    return '<span>' + $1 + '</span>' + $2;
                }));


                this.set("questionParsedString", this.get("question").replace(/\[([\s\S]+?)\]/gm, function (word, $1) {
                    scope.get("answers").push($1);
                    return '(<input type="text" />)';
                }));


            },
            /**
             * @override
             * @returns {*}
             */
            checkAnswer: function () {

                var answered, rightCount, allCount, yourAnswers;

                if (this.get("_chengeAnswer") === false && this.get("answered") !== null) {
                    return this.get("answered");
                }

                this.set("_chengeAnswer", false);

                answered = {
                    judges: false,
                    //正解フラグ　（0:不正解　1:正解　2:部分点　）　
                    correct_flag: 0,
                    answerPoint: 0,
                    resultData: [],
                    resultXML: ""
                };


                rightCount = 0;

                allCount = this.get("answers").length;

                yourAnswers = this.get("yourAnswer").split("###");


                $(this.get("answers")).each(function (i, val) {


                    var result = {
                        "no": i,
                        "judge": false,
                        "yourAnswer": yourAnswers[i],
                        "rightAnswer": val
                    };

                    if (yourAnswers[i] !== undefined) {
                        /*
                         *　大文字小文字を区別しない
                         */



                        if (yourAnswers[i] !== "" && val.toUpperCase() === yourAnswers[i].toUpperCase()) {
                            rightCount++;
                            result.judge = true;
                        }
                    }


                    answered.resultData.push(result);
                });


                answered.judges = (rightCount === allCount);


                if (this.get("partialPoint")) {
                    //部分点有り
                    answered.answerPoint = Math.floor(this.get("point") * (rightCount / allCount));
                    if (answered.judges) {
                        answered.correct_flag = 1;
                    } else if (rightCount > 0) {
                        answered.correct_flag = 2;
                    }


                } else {
                    //無し

                    //正解の場合
                    if (answered.judges) {
                        answered.answerPoint = this.get("point");
                        answered.correct_flag = 1;
                    }
                }


                answered.resultXML = this._createServerSendResultXML(answered.resultData);


                this.set("answered", answered);
                return answered;
            },

            /**
             * サーバーに渡す解答情報XMLを作成する
             */
            _createServerSendResultXML: function (resultData) {


                var view, resultXML;

                view = {'resultData': resultData};
                resultXML = "";

                if (this.isAnswerd()) {

                    resultXML = $.mustache(this.template, view);
                }


                return resultXML;
            }
        });
        /**
         * defaults変数をマージ
         */
        _.extend(ClozeTestQuestion.prototype.defaults, Question.prototype.defaults);

        return ClozeTestQuestion;
    }
);






