                if ($(elm).attr("partialPoint")) {
                    this.set("partialPoint", ($(elm).attr("partialPoint") === "true") ? true : false);
                }

                var sortStringList = [],
                    noSortStringList = [],
                    answers = [],
                    //置換して、sortStringListに入れる
                    wordIndex = 0,
                    scope = this,
                    questionParsedString;


                questionParsedString = this.get("question").replace(/\[([\s\S]+?)\]/gm, function (word, $1) {
                    sortStringList.push({"index": wordIndex, "text": $1, "lang": scope.get("lang")});
                    noSortStringList.push($1);
                    answers.push(wordIndex);
                    wordIndex++;
                    return '<span class="insertionPosition" ref="">(　　　　　　　)</span>';
                });

                this.set("questionParsedString", questionParsedString);

                this.set("sortStringList", sortStringList);
                this.set("noSortStringList", noSortStringList);
                this.set("answers", answers);


