define('app/question/MatchingWordQuestion',
    [
        "Underscore",
        "jQuery",
        "app/question/Question"
    ],
    function (
        _,
        $,
        Question
    ) {
        

        var MatchingWordQuestion = Question.extend({
            /**
             * @override
             */
            defaults: {

                /** 部分点 */
                partialPoint : false,
                /** s */
                sortStringList : [],
                /** シャッフルしていない文リスト */
                noSortStringList : [],

                /** 入力するカラムの番号 */
                inputCelNum : 0,
                inputCelLang : "",

                /** カラムの数 */
                celLength : 0

            },
            /**
             * @override
             *
             * TODO ここおかしいかも？コード保管されなかった
             */
            parseQuestionData: function (elm) {
                Question.prototype.parseQuestionData.apply(this, arguments);

                if ($(elm).attr("partialPoint")) {
                    this.set("partialPoint", ($(elm).attr("partialPoint") === "true") ? true : false);
                }


                var sortStringList, noSortStringList, answers, wordIndex, csv, csv_header, i, csv_body, wordTable, j, word;


                sortStringList = [];
                noSortStringList = [];
                answers = [];

                //置換して、sortStringListに入れる
                wordIndex = 0;


                csv = $.csv("/", "<br />")($.trim(this.get("question")));

                csv_header = csv.shift();

                this.set("celLength", csv_header.length);

                for (i = 0; i < this.get("celLength"); i++) {
                    if (csv_header[i].indexOf("*") !== -1) {
                        this.set("inputCelNum", i);
                        this.set("inputCelLang =", csv_header[i].replace(/\*/g, ""));
                    }
                }


                csv_body = csv;

                wordTable = '<table class="matchingWordTable">';

                for (i = 0; i < csv_body.length; i++) {
                    wordTable += "<tr>";
                    wordTable += "<td>";
                    wordTable += i + 1;
                    wordTable += "</td>";
                    for (j = 0; j < this.get("celLength"); j++) {

                        word = csv_body[i][j];

                        wordTable += '<td class="words">';

                        if (this.get("inputCelNum") === j) {

                            sortStringList.push({"index": wordIndex, "text": word, "lang": this.get("lang")});
                            noSortStringList.push(word);
                            answers.push(wordIndex);
                            wordIndex++;
                            wordTable += $.mustache('<span class="insertionPosition lang-{{lang}} " lang="{{lang}}" ref="">(　　　　　　　)</span>', {lang: this.get("inputCelLang")});
                        } else {
                            wordTable += $.mustache('<span class="lang-{{lang}} " lang="{{lang}}">{{word}}</span>', {lang: csv_header[j], word: word});
                        }
                        wordTable += "</td>";
                    }
                    wordTable += "</tr>";
                }

                wordTable += "</table>";


                this.set("questionParsedString", wordTable);
                this.set("sortStringList", sortStringList);
                this.set("noSortStringList", noSortStringList);
                this.set("answers", answers);


                //設問をシャッフルする
                this.set("sortStringList", _.shuffle(this.get("sortStringList")));


            },
            /**
             * @override
             *
             * @returns {*}
             */
            checkAnswer: function () {


                if (this.get("_chengeAnswer") === false && this.get("answered") !== null) {
                    return this.get("answered");
                }

                this.set("_chengeAnswer", false);

                var answered, rightCount, allCount, yourAnswers;

                answered = {
                    judges: false,
                    //正解フラグ　（0:不正解　1:正解　2:部分点　）　
                    correct_flag: 0,
                    answerPoint: 0,
                    resultData: [],
                    resultXML: ""
                };


                rightCount = 0;
                allCount = this.get("answers").length;

                yourAnswers = this.get("yourAnswer").split(",");


                $(this.get("answers")).each(function (i, val) {

                    var result = {
                        "no": i,
                        "judge": false,
                        "yourAnswer": yourAnswers[i],
                        "rightAnswer": val
                    };


                    if (yourAnswers !== "") {

                        if (yourAnswers[i] !== "" && val === yourAnswers[i]) {
                            rightCount++;
                            result.judge = true;
                        }

                    }

                    answered.resultData.push(result);
                });


                answered.judges = (rightCount === allCount);

                if (this.get("partialPoint")) {
                    //部分点有り
                    answered.answerPoint = Math.floor(this.get("point") * (rightCount / allCount));
                    if (answered.judges) {
                        answered.correct_flag = 1;
                    } else if (rightCount > 0) {
                        answered.correct_flag = 2;
                    }
                } else {
                    //無し

                    //正解の場合
                    if (answered.judges) {
                        answered.answerPoint = this.get("point");
                        answered.correct_flag = 1;
                    }
                }


                answered.resultXML = this._createServerSendResultXML(answered.resultData);


                this.set("answered", answered);

                return answered;
            },

            /**
             * サーバーに渡す解答情報XMLを作成する
             */
            _createServerSendResultXML: function (resultData) {


                var view, resultXML, template;

                view = {
                    'resultData': resultData
                };

                resultXML = "";

                if (this.isAnswerd()) {
                    resultXML = $.mustache(template, view);
                }


                return resultXML;
            }
        });

        /**
         * defaults変数をマージ
         */
        _.extend(MatchingWordQuestion.prototype.defaults, Question.prototype.defaults);

        return MatchingWordQuestion;
    }
);


