/*global require: false, define: false, Class: false */
define('app/xmlparser/QuestionXMLParser',
    [
        "Underscore",
        "jQuery",
        "Backbone",
        "app/CombinationQuestion",


        "app/question/MultipleChoiceQuestion",
        "app/question/UnderLineChoiceQuestion",
        "app/question/PopUpQuestion",
        "app/question/AnaumeFilInQuestion",
        "app/question/SortingAQuestion",
        "app/question/MultipleCorrectQuestion",
        "app/question/ClozeTestQuestion",
        "app/question/InsertionQuestion",
        "app/question/TypingQuestion",
        "app/question/DictationTypingQuestion",
        "app/question/MatchingWordQuestion",
        "app/question/FreeAnswerQuestion",
        "app/question/WritingQuestion"

    ],
    function (
        _,
        $,
        Backbone,
        CombinationQuestion,


        MultipleChoiceQuestion,
        UnderLineChoiceQuestion,
        PopUpQuestion,
        AnaumeFilInQuestion,
        SortingAQuestion,
        MultipleCorrectQuestion,
        ClozeTestQuestion,
        InsertionQuestion,
        TypingQuestion,
        DictationTypingQuestion,
        MatchingWordQuestion,
        FreeAnswerQuestion,
        WritingQuestion




    ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },
            /**
             * 読み込んだxmlをパースする
             *
             * @param {Object} xml
             */
            parseXML: function (xml) {
                var questionModel = this.get("questionModel"),
                    parser = this,
                    temp_questions;

                $.logger.debug("QuestionModel.xmlParser()");

                if (
                    $(xml).find("question").length === 1
                        && $($(xml).find("question")[0]).attr("type") === "freeAnswer"
                ) {

                    if (window.playerModel.get("bookType") === 1
                            || window.playerModel.get("bookType") === 2) {

                        //TODO  Webで鍛えるビジネス文書100　コミュニケーション力12（PC・スマートフォン）　対応
                        // 問題数が１問で、typeがfreeAnswerで、ドリル、またはテストの場合は、自己採点
                        // bookTypeを5に設定する
                        window.playerModel.set("bookType", 5);

                    }


                }


                if (window.playerModel.get("previewType") !== "combination"
                        || window.playerModel.get("previewType") !== "single") {

                    questionModel.set("booktitle", $(xml).find("book").find("booktitle").text());
                    questionModel.set("explanation", $(xml).find("book").find("explanation").text());
                    questionModel.set("bookcoverImageURL", $(xml).find("book").find("bookcover").text());
                    questionModel.set("passComment", $(xml).find("book").find("pass_comment").text());
                    questionModel.set("failComment", $(xml).find("book").find("fail_comment").text());

                }

                if (window.playerModel.get("previewType") === "assign"
                        || window.playerModel.get("previewType") === "assign_vc") {

                    questionModel.set("mode", $(xml).find("book").attr("mode"));
                    questionModel.set("limitTime", Number($(xml).find("book").attr("limitTime")));
                    questionModel.set("mission", Number($(xml).find("book").attr("mission")));
                    questionModel.set("shuffleQuestions", ($(xml).find("book").attr("shuffleQuestions") === "true") ? true : false);

                }


                questionModel.set("explainDisplay", ($(xml).find("book").attr("explainDisplay") === "true") ? true : false);

                temp_questions = [];

                $("questions > *", xml).each(function (index, domEle) {
                    $.logger.debug("タグ：：：" + domEle.tagName);


                    var combinationQuestionsId,
                        combinationQuestion,
                        question;

                    switch (domEle.tagName) {
                    case "combinationQuestion":
                        combinationQuestionsId = questionModel.get("combinationQuestions").length;
                        combinationQuestion = parser.parseCombinationQuestion(domEle, temp_questions, combinationQuestionsId);
                        questionModel.get("bookIndex").push(combinationQuestion);
                        questionModel.get("combinationQuestions").push(combinationQuestion);

                        break;
                    case "question":
                        question = parser.parseQuestion(domEle);
                        temp_questions.push(question);

                        questionModel.get("bookIndex").push(question);
                        break;
                    default:
                    //何もしない

                    }

                });


                if (questionModel.get("shuffleQuestions")) {
                    /*
                     * 設問をシャッフルする
                     */
                    temp_questions = this.doShuffleQuestions(temp_questions);
                }

                //問題番号を振る
                $.each(temp_questions, function (index, val) {
                    val.set("questionNumber", index + 1);
                });

                $.each(questionModel.get("combinationQuestions"), function (index, val) {
                    val.setQuestionNumber();
                });


                questionModel.set("questions", temp_questions);
                console.log("------------------------------------- console.log(temp_questions);");
                console.log(temp_questions);

            },



            /**
             * 設問をシャッフルする
             *
             * @param temp_questions
             * @returns {Array}
             */
            doShuffleQuestions: function (temp_questions) {

                var questionModel = this.get("questionModel"),
                    newList = [];


                //設問をシャッフルする
                questionModel.set("bookIndex", _.shuffle(questionModel.get("bookIndex")));



                $.each(questionModel.get("bookIndex"), function (i, val) {

                    if (val instanceof CombinationQuestion) {
                        newList = newList.concat(val.get("questions"));
                    } else {
                        newList.push(val);
                    }

                });

                return newList;
            },




            /**
             *
             */
            parseQuestion: function (elm) {

                var questionType = $(elm).attr("type"),
                    question,
                    questionModel = this.get("questionModel");


                console.log("questionType:::::" + questionType);

                switch (questionType) {
                case "Insertion":
                case "matching":
                    question = new InsertionQuestion();
                    break;
                case "matchingWord":
                    question = new MatchingWordQuestion();
                    break;
                case "ClozeTest":
                    question = new ClozeTestQuestion();
                    break;
                case "sortingA":
                    question = new SortingAQuestion();
                    break;
                case "underLineChoice":
                    question = new UnderLineChoiceQuestion();
                    break;
                case "popup":
                    question = new PopUpQuestion();
                    break;
                case "typing":
                    question = new TypingQuestion();
                    break;

                case "dictationTyping":
                    question = new DictationTypingQuestion();
                    break;
                case "anaumeFilIn":
                    question = new AnaumeFilInQuestion();
                    break;
                case "multipleCorrect":
                    question = new MultipleCorrectQuestion();
                    break;
                case "multipleChoice":
                case "trueFalse":
                case "readIframe":
                    question = new MultipleChoiceQuestion();
                    break;

                case "freeAnswer":
                case "writing":

                    if (window.playerModel.get("bookType") === 5) {
                        question = new WritingQuestion();
                    } else {
                        question = new FreeAnswerQuestion();
                    }

                    break;
                default:
                    //TODO ここにエラー処理を
                    alert("サポートされていない問題形式です。");
                }


                question.parseQuestionData(elm);
                question.on('change:yourAnswer', function (model, yourAnswer) {
                    console.log("change:yourAnswer", yourAnswer);
                    questionModel.trigger('/Question/doAnswered');
                });

                if (questionModel.get("mode") === "test") {
                    question.set("isTestMode", true);
                }


                return question;
            },
            /**
             *
             */
            parseCombinationQuestion: function (domEle, temp_questions, combinationQuestionsId) {

                var questions = [],
                    parse = this,
                    combinationQuestion;

                $(domEle).find("question").each(function (index, domEle) {
                    var question = parse.parseQuestion(domEle);
                    question.set("combinationId", combinationQuestionsId);
                    temp_questions.push(question);

                    console.log("combinationQuestion!!!!!!!!! combinationId:" + combinationQuestionsId);

                    questions.push(question);
                });


                console.log("combinationQuestion");

                combinationQuestion = new CombinationQuestion(
                    {
                        no: $(domEle).attr("no"),
                        questionType: $(domEle).attr("type"),
                        title: $(domEle).children("title").text(),
                        direction: $(domEle).children("direction").text(),
                        passage: $(domEle).children("passage").text(),
                        sound: $(domEle).children("sound").text(),
                        image: $(domEle).children("image").text(),

                        jp_script: $(domEle).children("jp_script").text(),
                        speed: $(domEle).attr("speed"),
                        en_script: $(domEle).children("en_script").text(),
                        en_script_lang: $(domEle).children("en_script").attr("lang") || "en",
                        questions: questions

                    }

                );



                return combinationQuestion;

            }


        });

    }
);

define('text!app/templates/bookxml/bookXML.html',[],function () { return '<?xml version="1.0" encoding="UTF-8"?>\n<book\n        limitTime= "{{limitTime}}"\n        mission= "{{mission}}"\n        mode= "{{mode}}"\n        no= "{{no}}"\n        shuffleQuestions= "{{shuffleQuestions}}"\n        explainDisplay= "{{explainDisplay}}"\n>\n\n    <booktitle><![CDATA[{{booktitle}}]]></booktitle>\n    <explanation><![CDATA[{{explanation}}]]></explanation>\n\n    <pass_comment><![CDATA[{{pass_comment}}]]></pass_comment>\n    <fail_comment><![CDATA[{{fail_comment}}]]></fail_comment>\n\n\n    <bookcover>{{bookcover}}</bookcover>\n\n    <questions>\n        {{{questions}}}\n    </questions>\n\n</book>';});

define('text!app/templates/bookxml/MultipleChoiceQuestionXML.html',[],function () { return '<question no="{{no}}" point="{{point}}" skillType="{{skillType}}" type="{{type}}">\n    <title><![CDATA[{{title}}]]></title>\n\n    <direction><![CDATA[{{direction}}]]></direction>\n    <questionText><![CDATA[{{{questionText}}}]]></questionText>\n    <description><![CDATA[{{{description}}}]]></description>\n\n    <image>{{image}}</image>\n\n    <sound>{{sound}}</sound>\n    <answers><answer>{{answer}}</answer></answers>\n    <!-- 選択肢 -->\n    <choices shuffleChoices="{{shuffleChoices}}">\n        {{#choices}}\n        <choice no="{{no}}">{{label}}</choice>\n        {{/choices}}\n    </choices>\n</question>\n\n';});

define('text!app/templates/bookxml/SpeedReadingCombinationQuestionXML.html',[],function () { return '<combinationQuestion no="{{no}}" type="{{type}}" speed="{{speed}}">\n    <title><![CDATA[{{title}}]]></title>\n\n    <direction><![CDATA[{{direction}}]]></direction>\n\n    {{#passage}}\n    <passage><![CDATA[{{{passage}}}]]></passage>\n    {{/passage}}\n\n    {{{questions}}}\n</combinationQuestion>';});

/*global require: false, define: false, Class: false */
define('app/xmlparser/AC2WeeklyDrillQuestionXMLParser',
    [
        "Underscore",
        "jQuery",
        "Backbone",
        'text!app/templates/bookxml/bookXML.html',
        'text!app/templates/bookxml/MultipleChoiceQuestionXML.html',
        'text!app/templates/bookxml/SpeedReadingCombinationQuestionXML.html'
    ],
    function (
        _,
        $,
        Backbone,
        bookXML,
        MultipleChoiceQuestionXML,
        SpeedReadingCombinationQuestionXML
    ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },

            /**
             * 単語数をカウントして返す
             * TODO: ここは重複
             *
             * @param targetString  カウント対象の文字列
             * @returns {*}
             * @private
             */
            _getWordCount: function (targetString) {
                //単語数
                var returnNumber = 0;
                //文字が空の場合
                if (targetString === "") {
                    return returnNumber;
                }
                //単語数をカウントする
                returnNumber = targetString.split(" ").length;

                return returnNumber;
            },

            /**
             * 読み込んだxmlをパースする
             *
             * @param {Object} xml
             */
            parseXML: function (xml) {


                var multipleChoiceQuestion,
                    speedReadingCombinationQuestion,
                    questionsXML,
                    /* １問の得点 */
                    oneQeestionScore,
                    /** 最後の得点（割り切れない場合） */
                    lastQeestionScore,
                    /** 問題数 */
                    questionsLength,
                    doc,
                    formatedXML,
                    weeklyConfig,
                    limitTime;


                questionsXML = "";

                weeklyConfig = window.playerModel.get("weeklyConfig");


                questionsLength = $("question", xml).size();

                oneQeestionScore = Math.floor(100 / questionsLength);
                lastQeestionScore  = oneQeestionScore + (100 % questionsLength);



                $("question", xml).each(function (index, domEle) {


                    console.log(index);


                    var choices = [],
                        answerText,
                        answerNo,
                        labels = ["(A)", "(B)", "(C)", "(D)", "(E)", "(F)"];


                    answerText = $("answer", domEle).text();

                    $("choice", $("choices[lang = 'en']", domEle)).each(function (index2, domEle2) {

                        var choice = {
                            no: index2 + 1,
                            label: $(domEle2).text()
                        };


                        if (answerText === choice.label) {
                            answerNo = choice.no;
                        }


                        choice.label =  labels[index2] + " " + choice.label;

                        choices.push(choice);

                    });


                    multipleChoiceQuestion = {
                        no: index + 1,

                        skillType: weeklyConfig.skill_type,
                        type: "multipleChoice",

                        title: "択一問題",
                        direction: $("explanation", domEle).text(),
                        questionText: "",
                        description:  $("description", domEle).text(),

                        image: "",
                        sound: "",
                        answer: answerNo,
                        shuffleChoices: false,

                        choices: choices

                    };

                    if (multipleChoiceQuestion.description) {
                        multipleChoiceQuestion.description  = "<b>" + "【解説】" + "</b>" + "<br />" + multipleChoiceQuestion.description;
                    }



                    multipleChoiceQuestion.description = $.StringUtilPlugin.parseBr(multipleChoiceQuestion.description);



                    if (index >= questionsLength - 1) {
                        //最後の問題
                        multipleChoiceQuestion.point = lastQeestionScore;
                    } else {
                        multipleChoiceQuestion.point = oneQeestionScore;
                    }


                    if ($(xml).find("reading").size()) {
                        multipleChoiceQuestion.questionText = $("questionText[lang = 'jp']", domEle).text();



                    } else {

                        multipleChoiceQuestion.questionText = $("questionText[lang = 'en']", domEle).text();

                        if ($("questionText[lang = 'jp']", domEle).text()) {
                            multipleChoiceQuestion.description = "<b>" + "【問題（日本語訳）】" + "</b>" + "<br />" + $("questionText[lang = 'jp']", domEle).text() + "<br />" + "<br />" + multipleChoiceQuestion.description ;
                        }

                    }



                    if ($("choices[lang = 'jp']", domEle).size() > 0
                        && $("choices[lang = 'jp'] choice", domEle).size() > 0
                        && $("choices[lang = 'jp'] choice", domEle).eq(0).text() !== "") {

                        var sentakushi_yaku =  "<b>" + "【選択肢（日本語訳）】" + "</b>" + "<br />";
                        var sentakushi_en = $("choices[lang = 'en'] choice", domEle);
                        var sentakushi_jp = $("choices[lang = 'jp'] choice", domEle);

                        for(var j = 0 ; j < sentakushi_jp.size() ;j++){
                            console.log(sentakushi_jp);
                            console.log("AAAA::::" + sentakushi_en.eq(j).text() );
                            console.log("BBBB::::" + sentakushi_jp.eq(j).text() );
                            sentakushi_yaku += sentakushi_en.eq(j).text()  + "<br />"    + '<span style="color:#0000FF;">'  +  sentakushi_jp.eq(j).text()   + "</span>"  +  "<br />" + "<br />";
                        }

                        multipleChoiceQuestion.description = multipleChoiceQuestion.description + "<br />" + "<br />" + sentakushi_yaku

                    }




                    questionsXML = questionsXML + $.mustache(MultipleChoiceQuestionXML, multipleChoiceQuestion);

                });



                limitTime = Number($(xml).find("test").attr("limitTime"));


                if ($(xml).find("reading").size()) {

                    speedReadingCombinationQuestion = {
                        no: 1, /* 固定 */
                        type: "speedReadingCombination",
                        title: "Reading Comprehension 1",
                        direction: "次の英文を見て、問題に答えなさい。",
                        passage: $("readingText", xml).text(),
                        speed: $("speed", xml).text(),
                        questions: questionsXML
                    };

                    // 速読の場合は制限時間に速読の時間をたす
                    limitTime += Math.floor(this._getWordCount(speedReadingCombinationQuestion.passage) * speedReadingCombinationQuestion.speed);

                    questionsXML = $.mustache(SpeedReadingCombinationQuestionXML, speedReadingCombinationQuestion);
                }

                doc = {
                    limitTime : limitTime,
                    mission : 100, /* 固定 */
                    mode: "test", /* 固定 */
                    no: 1, /* 固定 */
                    shuffleQuestions: true, /* 固定 */
                    booktitle: weeklyConfig.title + " " + weeklyConfig.subTitle,
                    explanation: "",
                    pass_comment: "",
                    fail_comment: "",
                    bookcover: "",
                    questions: questionsXML,
                    explainDisplay: true
                };



                formatedXML = $.mustache(bookXML, doc);


                return $.parseXML(formatedXML);



            }



        });

    }
);

define('text!app/templates/bookxml/TypingQuestionXML.html',[],function () { return '<question no="{{no}}" point="{{point}}" skillType="{{skillType}}" type="{{type}}">\n    <title><![CDATA[{{title}}]]></title>\n    <direction><![CDATA[{{{direction}}}]]></direction>\n    <questionText><![CDATA[{{questionText}}]]></questionText>\n    <description><![CDATA[{{{description}}}]]></description>\n\n\n    <exercise>\n        {{#paragraphs}}\n        <paragraph>\n            <en>{{en}}</en>\n            <ja>{{ja}}</ja>\n            <sound>{{sound}}</sound>\n        </paragraph>\n        {{/paragraphs}}\n    </exercise>\n\n\n    <sound>{{sound}}</sound>\n    <answers><answer><![CDATA[{{answer}}]]></answer></answers>\n</question>\n';});

/*global require: false, define: false, Class: false */
define('app/xmlparser/AC2WeeklyDrillDictationQuestionXMLParserer',
    [
        "Underscore",
        "jQuery",
        "Backbone",
        'text!app/templates/bookxml/bookXML.html',
        'text!app/templates/bookxml/TypingQuestionXML.html'
    ],
    function (
        _,
        $,
        Backbone,
        bookXML,
        TypingQuestionXML
        ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },
            /**
             * 読み込んだxmlをパースする
             *
             * @param {Object} xml
             */
            parseXML: function (xml) {


                var typingQuestion,
                    questionsXML,
                    /* １問の得点 */
                    oneQeestionScore,
                    /** 最後の得点（割り切れない場合） */
                    lastQeestionScore,
                    /** 問題数 */
                    questionsLength,
                    doc,
                    formatedXML,
                    weeklyConfig;


                questionsXML = "";

                weeklyConfig = window.playerModel.get("weeklyConfig");


                questionsLength = $("question", xml).size();

                oneQeestionScore = Math.floor(100 / questionsLength);
                lastQeestionScore  = oneQeestionScore + (100 % questionsLength);



                $("question", xml).each(function (index, domEle) {


                    console.log(index);


                    var choices = [],
                        answerText;

                    answerText = $("answer", domEle).text();

                    $("choice", $("choices[lang = 'en']", domEle)).each(function (index2, domEle2) {

                        var choice = {
                            no: index2 + 1,
                            label: $(domEle2).text()
                        };


                        choices.push(choice);

                    });


                    typingQuestion = {

                        no: index + 1,

                        skillType: weeklyConfig.skill_type,
                        type: "dictationTyping",

                        title: "ディクテーション",
                        direction: "音声を聴いて、英文をタイピングしましょう。<br />音声を聴くときは音声ボタンをクリックしてください。",
                        questionText: "",
                        description:  "",


                        paragraphs: [],

                        image: "",
                        sound:  "",
                        answer: "",
                        shuffleChoices: true


                    };


                    typingQuestion.description = "<b>" + "【日本語訳】" + "</b>" + "<br />";

                    $("exercise paragraph", domEle).each(function(index3, el3){


                        var paragraph = {
                            "en": $("en", el3).text(),
                            "ja": $("ja", el3).text(),
                            "sound":  window.playerModel.get("weeklyConfig").q_sound  + $("sound", el3).attr("src")
                        };

                        typingQuestion.paragraphs.push(paragraph);

                        typingQuestion.description += paragraph.ja + "<br />";
                    });


                    if ($("exercise paragraph en", domEle).size() === 2) {
                       // typingQuestion.questionText = "[" + $("exercise paragraph en", domEle).eq(0).text()  + "\n" + $("exercise paragraph en", domEle).eq(1).text() + "]";
                        //typingQuestion.sound =  "demo_resource/dictation/q_sound/" + "m/" + $("exercise paragraph sound", domEle).attr("src").split("-")[0] + ".mp3";
                        //typingQuestion.answer =  $("exercise paragraph en", domEle).eq(0).text()  + "\n" + $("exercise paragraph en", domEle).eq(1).text();
                    }



                    if (index >= questionsLength - 1) {
                        //最後の問題
                        typingQuestion.point = lastQeestionScore;
                    } else {
                        typingQuestion.point = oneQeestionScore;
                    }





                    questionsXML = questionsXML + $.mustache(TypingQuestionXML, typingQuestion);

                });



                doc = {
                    limitTime : questionsLength * 60 * 2,
                    mission : 100, /* 固定 */
                    mode: "drill", /* 固定 */
                    no: 1, /* 固定 */
                    shuffleQuestions: true, /* 固定 */
                    booktitle: weeklyConfig.title + " " + weeklyConfig.subTitle,
                    explanation: "",
                    pass_comment: "",
                    fail_comment: "",
                    bookcover: "",
                    questions: questionsXML,
                    explainDisplay: true
                };



                formatedXML = $.mustache(bookXML, doc);



                return $.parseXML(formatedXML);



            }



        });

    }
);

/*global require: false, define: false, Class: false */
define('app/xmlloader/QuestionXMLLoader',
    [
        "Underscore",
        "jQuery",
        "Backbone"
    ],
    function (
        _,
        $,
        Backbone
    ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },
            loadXML: function () {


                var defultParam, loadQuestionParam, questionModel;


                questionModel = this.get("questionModel");

                defultParam = {
                    method: window.playerModel.get("cfc_method"),
                    mode: window.playerModel.get("previewType")
                };

                loadQuestionParam = this._getLoadQuestionParam(defultParam);

                $.ajax({
                    type: "GET",
                    url: questionModel.GET_XML_FILE_SERVER_URL,
                    data: loadQuestionParam,
                    dataType: "xml",
                    success: $.proxy(questionModel._onLoadXML, questionModel),
                    ajaxError: function () {
                        alert("Error");
                    }

                });

            },
            /**
             * 問題データ取得用をリクエストパラメートを作成する
             *
             * @param defultParam
             * @returns {*}
             * @private
             */
            _getLoadQuestionParam: function (defultParam) {
                var param = defultParam,
                    questionModel = this.get("questionModel");

                switch (window.playerModel.get("previewType")) {
                case "assign":

                    param.course_no = window.playerModel.get("course_no");
                    param.assign_no = window.playerModel.get("assign_no");

                    if (window.playerModel.get("isCoursework")) {
                        param.unit_contents_no = window.playerModel.get("unit_contents_no");
                    }

                    break;
                case "assign_vc":

                    param.course_no = window.playerModel.get("course_no");
                    param.assign_no = window.playerModel.get("assign_no");

                    param.visionary = window.playerModel.get("visionary");

                    if (window.playerModel.get("visionary") === "cw") {
                        param.lesson_no = window.playerModel.get("lesson_no");
                    }

                    break;
                case "book":
                    param.course_no = window.playerModel.get("course_no");
                    break;
                case "combination":
                    param.course_no = window.playerModel.get("course_no");
                    param.comprehension_no = window.playerModel.get("comprehension_no");
                    param.question_no = window.playerModel.get("question_no");
                    break;
                case "single":
                    param.question_no = window.playerModel.get("question_no");
                    break;

                }


                param.ran = new Date().getTime();


                if (window.playerModel.get("coursework_no")) {
                    param.coursework_no = window.playerModel.get("coursework_no");
                }

                if (window.playerModel.get("xml_name")) {
                    questionModel.GET_XML_FILE_SERVER_URL = window.playerModel.get("xml_name");
                }

                if (window.playerModel.get("save_answer_url")) {
                    questionModel.SAVE_ANSWER_SERVER_URL = window.playerModel.get("save_answer_url");
                }


                return param;


            }


        });

    }
);

