define('app/xmlloader/AC2WeeklyDrillDictationQuestionXMLLoader',
    [
        "Underscore",
        "jQuery",
        "Backbone"
    ],
    function (
        _,
        $,
        Backbone
    ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },
            loadXML: function () {


                var defultParam, loadQuestionParam, questionModel;


                questionModel = this.get("questionModel");

                defultParam = {};

                loadQuestionParam = this._getLoadQuestionParam(defultParam);

                $.ajax({
                    type: "GET",
                    url: questionModel.GET_XML_FILE_SERVER_URL,
                    data: loadQuestionParam,
                    dataType: "xml",
                    success: $.proxy(this._onLoadXML, this),
                    ajaxError: function () {
                        alert("Error");
                    }

                });

            },
            /**
             * 問題データ取得用をリクエストパラメートを作成する
             *
             * @param defultParam
             * @returns {*}
             * @private
             */
            _getLoadQuestionParam: function (defultParam) {
                var param = defultParam,
                    questionModel = this.get("questionModel");

                param.ran = new Date().getTime();

                if (window.playerModel.get("xml_name")) {
                    questionModel.GET_XML_FILE_SERVER_URL = window.playerModel.get("xml_name");
                }

                if (window.playerModel.get("save_answer_url")) {
                    questionModel.SAVE_ANSWER_SERVER_URL = window.playerModel.get("save_answer_url");
                }

                return param;


            },
            /**
             * 問題リストXML読み込み完了
             *
             * @param xml
             * @private
             */
            _onLoadXML: function (xml) {


                var scope = this;

                this.set("xmlSize",  $("question", xml).size());
                this.set("loadXMLCount", 0);
                this.set("allXML", $.parseXML("<book><questions></questions></book>"));

                $("question", xml).each(function (index, el) {
                    scope.loadQuestionXML( window.playerModel.get("weeklyConfig").xmlPath  +  $(el).attr("src"));
                });
                console.log(xml);


            },
            /**
             * 問題XMLを読み込む
             *
             * @param xmlFileName
             */
            loadQuestionXML: function (xmlFileName) {



                console.log(xmlFileName);




                $.ajax({
                    type: "GET",
                    url:xmlFileName,
                    dataType: "xml",
                    success: $.proxy(this._onLoadQuestionXML, this),
                    ajaxError: function () {
                        alert("Error");
                    }

                });

            },

            /**
             * 問題XML読み込み完了
             *
             * @param xml
             * @private
             */
            _onLoadQuestionXML: function (xml) {

                console.log(xml);

                var loadXMLCount, allXML;

                loadXMLCount = this.get("loadXMLCount") + 1;

                allXML = this.get("allXML");


                $("questions", allXML).append($(xml).find("question"));

                this.set("loadXMLCount", loadXMLCount);

                console.log("読み込み完了:" + loadXMLCount);
                if (loadXMLCount >= this.get("xmlSize")) {
                    this._onLoadQuestionXMLAll();
                }

            },
            /**
             * すべての問題XML読み込み完了
             *
             * @private
             */
            _onLoadQuestionXMLAll: function () {

                var allXML, questionModel;


                allXML = this.get("allXML");

                console.log(allXML);

                questionModel = this.get("questionModel");
                questionModel._onLoadXML(allXML);


            }

        });

    }
);

