define('app/sendanswer/QuestionSendAnswer',
    [
        "Underscore",
        "jQuery",
        "Backbone"
    ],
    function (
        _,
        $,
        Backbone

    ) {
        

        return Backbone.Model.extend({


            /**
             * コンストラクタ
             * @param questionModel
             */
            initialize: function (questionModel) {
                this.set("questionModel", questionModel);
            },


            /**
             * 解答をサーバーに送信する
             */
            sendAnswer: function (targetQuestion) {


                $.logger.debug("QuestionModel.sendAnswer()");


                var answers, param, questionModel;
                questionModel = this.get("questionModel");



                //時間計測ストップ
                questionModel.stopLearning();



                //すべての答え
                answers = questionModel.getAnswers();

                console.log(targetQuestion);


                /*
                 *　ページを遷移したときにおくる
                 */
                param = {

                    method: "write_answer_au",

                    au_token: window.playerModel.get("au_token"),

                    question_no: targetQuestion.get("no"),

                    //スキルタイプ（学習時間保存用）
                    skill_type: targetQuestion.get("skillType"),

                    //学習時間（秒）
                    learning_time: questionModel.get("learningTimeManager")._learningTime,

                    //解答（XML）
                    answer: targetQuestion.checkAnswer().resultXML,

                    //正解フラグ　（0:不正解　1:正解　2:部分点　）　
                    correct_flag: targetQuestion.checkAnswer().correct_flag,

                    //得点
                    score: targetQuestion.checkAnswer().answerPoint,

                    //現時点でのトータルスコア
                    totalscore: answers.score,

                    //保存種別　（0:通常　1:終了　2:タイムアウト　）　
                    save_type: questionModel.get("saveTypeFlag")

                };
                console.log(param);

                $.ajax({

                    type: "POST",
                    url: questionModel.SAVE_ANSWER_SERVER_URL,
                    data: param,
                    dataType: "json",
                    success: $.proxy(questionModel._onSaveAnswer, questionModel),
                    ajaxError: function () {
                        alert("Error");
                    }

                });


            }


        });

    }
);

