define('app/Timer',
    [
        "jQuery"
    ],
    function ($) {
        

        return Class.extend({

            /**
             * コンストラクタ
             *
             */
            init: function (delay, repeatCount) {

                /*
                 * プロパティ
                 */
                //デフォルト　0
                this.delay = delay;
                //デフォルト　1
                this.repeatCount = repeatCount;

                this.startTime = 0;
                this.intervalID = -1;

            },

            /**
             *
             */
            countDown: function () {
                $.publish('/Timer/TIMER_EVENT_TIMER', null);
            },
            /**
             *
             */
            start: function () {
                this.intervalID = setInterval($.proxy(this.countDown, this), 1000);
            },
            /**
             *
             */
            stop: function () {
                clearInterval(this.intervalID);
            }
        });
    }
);
