/*global require: false, define: false, Class: false */

define('app/LearningTimeManager',
    [
        "jQuery",
        "Backbone",
        "app/Timer"
    ],
    function (
        $,
        Backbone,
        Timer
    ) {
        

        return Backbone.View.extend({
            LEARNING_TIME_TYPE_L: "L",
            LEARNING_TIME_TYPE_G: "G",
            LEARNING_TIME_TYPE_R: "R",
            LEARNING_TIME_TYPE_V: "V",

            /**
             * コンストラクタ
             *
             */
            initialize: function (options) {


                /*
                 * プロパティ
                 */

                this._learningTime = 0;

                this._type = "A";

                this._data = {};

                //待ち時間
                this.waitTime = 0;

                //待ち時間の限界 (秒)
                this.waitTimeLimit = 60;

                //５分
                /** モデル */
                this._model = null;

                this.timer = new Timer(1000, 0);

                $.subscribe('/Timer/TIMER_EVENT_TIMER', $.proxy(this.timerAction, this));

                $("body").mousemove($.proxy(this.onMouseMove, this));

            },

            setType: function (type) {
                this._type = type;
                //初期化
                this._learningTime = 0;
            },

            getType: function () {
                return this._type;
            },

            start: function () {
                this.timer.start();
            },

            stop: function () {
                this.timer.stop();
            },

            timerAction: function (event) {

                if (!this.isLearning()) {
                    //学習中でない場合はカウントしない
                    return;
                }

                this.waitTime++;
                this._learningTime++;

                //ここで保存

                //console.log(this._learningTime);
                //trace(learningTime);
            },

            isLearning: function () {
                var ret =  this.waitTime <= this.waitTimeLimit;
                return ret;
            },

            onMouseMove: function (event) {
                //console.log("onMouseMove");
                this.waitTime = 0;
            }

        });
    }
);
/*global require: false, define: false, Class: false */
define('app/QuestionModel',
    [
        "Underscore",
        "jQuery",
        "Backbone",

        "app/xmlparser/QuestionXMLParser",
        "app/xmlparser/AC2WeeklyDrillQuestionXMLParser",
        "app/xmlparser/AC2WeeklyDrillDictationQuestionXMLParserer",

        "app/xmlloader/QuestionXMLLoader",
        "app/xmlloader/AC2WeeklyDrillDictationQuestionXMLLoader",

        "app/sendanswer/QuestionSendAnswer",
        "app/sendanswer/AC2WeeklyDrillQuestionSendAnswer",

        "app/LearningTimeManager"

    ],
    function (
        _,
        $,
        Backbone,

        QuestionXMLParser,
        AC2WeeklyDrillQuestionXMLParser,
        AC2WeeklyDrillDictationQuestionXMLParserer,


        QuestionXMLLoader,
        AC2WeeklyDrillDictationQuestionXMLLoader,

        QuestionSendAnswer,
        AC2WeeklyDrillQuestionSendAnswer,

        LearningTimeManager
    ) {
        

        return Backbone.Model.extend({

            GET_XML_FILE_SERVER_URL: "../player_data/authoring.cfc",
            SAVE_ANSWER_SERVER_URL: "../flash/data_manipulate.cfc",

            defaults : {
                /** 問題を開始したかどうか  */
                isStart: false,
                /** 終了したかどうか（保存した場合） */
                isEndDril: false,
                /** 現在の問題番号　0が１問目　*/
                currentQuestionNumber: -1,
                /** 目次 */
                bookIndex : [],
                /** 制限時間（秒） */
                limitTime : 0,
                /**
                 *  テストモード
                 *
                 *  drill           ドリルモード
                 *  review          レビューモード
                 *  test            テストモード
                 */
                mode : "",
                mission : 100,
                /** 合格コメント */
                passComment : "Done!",
                /**  不合格コメント */
                failComment : "Study More and Try Again",
                /** 問題をシャッフルするかどうか */
                shuffleQuestions : false,
                /** Bookタイトル */
                booktitle : "",
                /** Bookの説明 */
                explanation : "",
                /** BookカバーのURL */
                bookcoverImageURL : "",
                /** 複合問題データ */
                combinationQuestions : [],
                /** 問題データ */
                questions : [],
                /** 終了したかどうか */
                ended : false,
                /** 種別　（0:通常　1:終了　2:タイムアウト　）　 */
                saveTypeFlag : 0,
                /** タイムアウトしたかどうか */
                timeoutFlag : false,
                /** TODO これはプロパティじゃない */
                learningTimeManager : null,


                /**
                 * 回答解説を表示するかどうか？
                 * @type {boolean}
                 */
                explainDisplay : false



            },
            /**
             * 問題データを読み込む
             * @param {Object} xmlURL
             */
            loadQuestionData: function () {

                var questionXMLLoader;
                if (window.playerModel.get("visionary") === "ac2weeklydrill"
                        &&  window.playerModel.get("weeklyConfig").type === "dictation") {
                    questionXMLLoader = new AC2WeeklyDrillDictationQuestionXMLLoader(this);
                } else {
                    questionXMLLoader = new QuestionXMLLoader(this);
                }


                questionXMLLoader.loadXML();

            },

            /**
             * 読み込んだxmlをパースする
             *
             * @param {Object} xml
             */
            _onLoadXML: function (xml) {
                var parser;

                if (window.playerModel.get("visionary") === "ac2weeklydrill"
                        &&  window.playerModel.get("weeklyConfig").type === "dictation"
                        ) {

                    parser = new AC2WeeklyDrillDictationQuestionXMLParserer(this);
                    xml = parser.parseXML(xml);

                } else if (window.playerModel.get("visionary") === "ac2weeklydrill") {

                    parser = new AC2WeeklyDrillQuestionXMLParser(this);
                    xml = parser.parseXML(xml);
                }

                parser = new QuestionXMLParser(this);
                parser.parseXML(xml);

                this.trigger("/QuestionModel/load", null);
            },

            /**
             * 最後の問題かどうか
             */
            isLastQuestion: function () {
                return (this.get("currentQuestionNumber") >= this.get("questions").length - 1);
            },
            /**
             * 問題終了
             */
            endQuestion: function () {

                if (this.get("timeoutFlag")) {
                    //タイムアウトした場合
                    this.set("saveTypeFlag", 2);
                } else {
                    this.set("saveTypeFlag", 1);
                }

                var targetQuestion = this.get("questions")[this.get("currentQuestionNumber")];

                this.sendAnswer(targetQuestion);

            },

            /**
             * TODO ドリル解答後、閉じるボタンを押したときに呼ぶ
             * 解説を読んだ時間を保存する　かも
             */
            sendDrillModeLearningTime: function () {

                /*
                 * 今は何もしない
                 */

                /*
                 *　ドリル解答後、閉じるボタンを押したときに呼ぶ
                 * 解説を読んだ時間を保存する　かも
                 */
                var param = {

                    method: "write_learning_time_drill_end_au",
                    au_token: window.playerModel.get("au_token"),
                    //学習時間（秒）
                    learning_time_r: 0,
                    learning_time_l: 0,
                    learning_time_v: 0,
                    learning_time_g: 0

                };


            },
            /**
             * スタートを送信
             */
            sendStart: function () {
                $.logger.debug("QuestionModel.sendStart()");


                if (window.playerModel.get("visionary") === "ac2weeklydrill"){
                    // 週刊！英語ドリルの場合は送らない
                    this.trigger("/QuestionModel/sendStart", null);
                    return;
                }


                var param = {
                    method: "start_answer_au",
                    au_token: window.playerModel.get("au_token")
                };

                $.ajax({
                    type: "GET",
                    url: this.SAVE_ANSWER_SERVER_URL,
                    data: param,
                    dataType: "json",
                    success: $.proxy(this._onSendStart, this),
                    ajaxError: function () {
                        alert("Error");
                    }
                });

            },
            /**
             *
             * スタートを送信完了
             *
             */
            _onSendStart: function (jsonp) {

                if (!jsonp.success) {

                    if (jsonp.err_msg_no === "ERR565") {

                        /*
                         * ここにセッションタイムアウトの特別な処理を入れること
                         */


                        this.set("isStart", true);
                        this.set("isEndDril", true);


                        return;
                    }

                    var errorMessage = "問題をスタートできません。";
                    errorMessage += "\n";
                    errorMessage += jsonp.err_msg;
                    alert(errorMessage);
                    return;
                }


                $.logger.debug("QuestionModel._onSendStart()1");

                this.trigger("/QuestionModel/sendStart", null);
            },
            /**
             * 解答をサーバーに送信する
             */
            sendAnswer: function (targetQuestion) {


                if (window.playerModel.get("visionary") === "ac2weeklydrill") {
                    // 週刊！英語ドリルの場合は最後の一回のみ　
                    // すべて保存

                    new AC2WeeklyDrillQuestionSendAnswer(this).sendAnswer();
                } else {

                    new QuestionSendAnswer(this).sendAnswer(targetQuestion);
                }



            },
            /**
             *
             * 解答を
             *
             */
            _onSaveAnswer: function (jsonp) {

                $.logger.debug("QuestionModel._onSaveAnswer()");
                $.logger.debug(jsonp);

                if (!jsonp.success) {

                    if (jsonp.err_msg_no === "ERR565") {
                        /*
                         * ここにセッションタイムアウトの特別な処理を入れること
                         */

                        this.set("isStart", true);
                        this.set("isEndDril", true);


                        return;
                    }

                    var errorMessage = "解答を保存できませんでした。";
                    errorMessage += "\n";
                    errorMessage += jsonp.err_msg;
                    alert(errorMessage);
                    return;
                }


                switch (this.get("saveTypeFlag")) {
                case 0:
                    //通常時

                    //時間計測スタート
                    this.startLearning();

                    this.trigger("/QuestionModel/changeQuestion", null);
                    break;
                case 1:
                    //終了時

                    this.trigger("/QuestionModel/endQuestion", null);
                    break;
                case 2:
                    //タイムアウト時

                    this.trigger("/QuestionModel/endQuestion", null);
                    break;
                }


            },
            /**
             *
             */
            getAnswers: function () {

                var judges,
                    question,
                    score,
                    rightCount,
                    comment,
                    answers;


                judges = $.map(this.get("questions"), function (n, i) {

                    question = n;

                    var judge = {
                        no: question.get("no"),
                        title: question.get("title"),
                        number: question.get("questionNumber"),
                        sound: question.get("sound"),
                        judge: question.checkAnswer().correct_flag,
                        answerPoint: question.checkAnswer().answerPoint,
                        point: question.get("point"),
                        judgeMark: ""
                    };


                    if (judge.judge === 1) {
                        judge.judgeMark = '<span class="maru"><img src="images/maru_icon_s.png"/></span>';
                    } else if (judge.judge === 2) {
                        judge.judgeMark = '<span class="batu"><img src="images/sankaku_icon_s.png"/></span>';
                    } else {
                        judge.judgeMark = '<span class="batu"><img src="images/batu_icon_s.png"/></span>';
                    }


                    if (question.get("point") === 0) {
                        judge.pointText = '設定していません';
                    } else {
                        judge.pointText = judge.answerPoint + "/" + judge.point;
                    }


                    return judge;
                });


                score = 0;
                rightCount = 0;

                $(judges).each(function () {
                    score += this.answerPoint;
                    if (this.judge) {
                        rightCount++;
                    }
                });


                comment = "";


                if (score >= this.get("mission")) {
                    comment = this.get("passComment");
                } else {
                    comment = this.get("failComment");
                }


                answers = {
                    comment: comment,
                    score: score,
                    judges: judges
                };

                return answers;

            },
            /**
             * 複合問題かどうか
             * @param {Object} targetQuestion
             */
            isCombinationQuestion: function (targetQuestion) {

                return targetQuestion.get("combinationId") !== -1;

            },
            /**
             * 複合問題を取得する（Questionから）
             * @param {Object} targetQuestion
             */
            getCombinationQuestionDataForQuestion: function (targetQuestion) {
                return this.get("combinationQuestions")[targetQuestion.get("combinationId")];
            },
            /**
             *
             */
            nextQuestion: function () {



                if (!window.playerModel.get("isPreview")) {

                    if (this.get("currentQuestionNumber") === -1) {
                        /*
                         * 最初の問題
                         */
                        /*
                         * 最初の問題は保存しない
                         */
                        this.set("currentQuestionNumber", this.get("currentQuestionNumber") + 1);

                        //時間計測スタート
                        this.startLearning();


                        this.trigger("/QuestionModel/changeQuestion", null);

                    } else {

                        if (window.playerModel.get("visionary") === "ac2weeklydrill") {
                            // 週刊！英語ドリルの場合は送らない
                            this.set("currentQuestionNumber", this.get("currentQuestionNumber") + 1);
                            this.trigger("/QuestionModel/changeQuestion", null);
                        } else {

                            this.sendAnswer(this.get("questions")[this.get("currentQuestionNumber")]);
                            this.set("currentQuestionNumber", this.get("currentQuestionNumber") + 1);
                        }



                    }

                } else {

                    this.set("currentQuestionNumber", this.get("currentQuestionNumber") + 1);

                    this.trigger("/QuestionModel/changeQuestion", null);

                }
            },
            prevQuestion: function () {

                if (!window.playerModel.get("isPreview")) {

                    if (window.playerModel.get("visionary") === "ac2weeklydrill") {
                        // 週刊！英語ドリルの場合は送らない
                        this.set("currentQuestionNumber", this.get("currentQuestionNumber") - 1);
                        this.trigger("/QuestionModel/changeQuestion", null);
                    } else {


                        this.sendAnswer(this.get("questions")[this.get("currentQuestionNumber")]);
                        this.set("currentQuestionNumber", this.get("currentQuestionNumber") - 1);
                    }

                } else {
                    this.set("currentQuestionNumber", this.get("currentQuestionNumber") - 1);

                    this.trigger("/QuestionModel/changeQuestion", null);
                }

            },


            /**
             * 一時保存を行う
             */
            draftQuestion: function () {
                if (!window.playerModel.get("isPreview")) {
                    this.sendAnswer(this.get("questions")[this.get("currentQuestionNumber")]);
                } else {
                    this.trigger("/QuestionModel/changeQuestion", null);
                }
            },

            jampQuestion: function (index) {


                if (!window.playerModel.get("isPreview")) {

                    if (window.playerModel.get("visionary") === "ac2weeklydrill") {
                        // 週刊！英語ドリルの場合は送らない
                        this.set("currentQuestionNumber", index);
                        this.trigger("/QuestionModel/changeQuestion", null);
                    } else {
                        this.sendAnswer(this.get("questions")[this.get("currentQuestionNumber")]);
                        this.set("currentQuestionNumber", index);
                    }


                } else {
                    this.set("currentQuestionNumber", index);
                    this.trigger("/QuestionModel/changeQuestion", null);
                }

            },
            /**
             * 学習を開始した。学習時間のカウントスタート
             */
            startLearning: function () {

                if (this.get("learningTimeManager") === null) {
                    this.set("learningTimeManager", new LearningTimeManager());
                }

                var question = this.get("questions")[this.get("currentQuestionNumber")];
                this.get("learningTimeManager").setType(question.skillType);
                this.get("learningTimeManager").start();
            },
            /**
             * 学習を止める
             */
            stopLearning: function () {
                this.get("learningTimeManager").stop();
            },
            getCurrentQuestion: function () {

                return this.get("questions")[this.get("currentQuestionNumber")];

            },
            /**
             * 問題数を返す
             * @returns {*}
             */
            getQuestionLength: function () {
                return this.get("questions").length;
            },

            isBookTypeWriting: function () {
                var rep = false;

                return rep;
            }




        });

    }
);

