/*global require: false, define: false, Class: false */
define('app/view/BookIndexView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        "app/CombinationQuestion",
        'text!app/templates/view/BookIndexView.html',
        'text!app/templates/view/BookIndexListCombinationQuestion.html',
        'text!app/templates/view/BookIndexListQuestion.html'
    ],
    function (
        $,
        AbstractBackbornView,
        CombinationQuestion,
        template,
        list_template_com,
        list_template
    ) {
        
        return AbstractBackbornView.extend({

            render: function () {
                console.log("BookIndexView.render()");

                var indexes,
                    html;

                indexes = {questions: []};


                $.each(this.view.bookIndex, function (i, val) {

                    var childhtml;




                    if (val instanceof CombinationQuestion) {
                        // 複数問題の場合

                        childhtml = $.mustache(list_template_com, val.toDEEPJSON());
                        indexes.questions.push(childhtml);
                    } else {
                        childhtml = $.mustache(list_template, val.toJSON());
                        indexes.questions.push(childhtml);
                    }
                });

                html = $.mustache(template, indexes);

                this.$el.html(html);
                return this;
            },
            /**
             * 目次を更新する
             */
            updateStatus: function () {

                var scope = this;

                //目次の更新

                this.$('li').filter("[class!='combination']").each(function () {

                    console.log($(this).attr("ref"));

                    if (scope.model.get("questions")[Number($(this).attr("ref")) - 1].get("yourAnswer") === "") {
                        $("span.questionNumber", $(this)).removeClass("answerd");
                    } else {
                        $("span.questionNumber", $(this)).addClass("answerd");
                    }

                });

            }
        });


    }
);
