/**
 * BookCoverOptionView
 *
 * @param {Object} el
 * @param {Object} view
 */
/*global require: false, define: false, Class: false */
define('app/view/BookCoverOptionView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        'text!app/templates/view/BookCoverOptionViewS.html',
        'text!app/templates/view/BookCoverOptionViewM.html',
        'text!app/templates/view/BookCoverOptionViewS_SP.html',
        'text!app/templates/view/BookCoverOptionViewM_SP.html'
    ],
    function (
        $,
        AbstractBackbornView,
        templateS,
        templateM,
        templateS_SP,
        templateM_SP
    ) {

        

        return AbstractBackbornView.extend({

            render: function () {

                var optionView, template, html;

                optionView = {
                    mission: this.view.mission,
                    questionLangth: this.view.questionLangth,
                    modeTitle: "",
                    modeText: "",
                    isTestMode: false,
                    limitTimeText: ""
                };

                switch (this.view.mode) {
                case "drill":
                    optionView.modeTitle = "ドリルモード";
                    optionView.modeText = "問題終了後に、解答・解説が表示されます。";
                    break;
                case "review":
                    optionView.modeTitle = "レビューモード";
                    optionView.modeText = "ミッションを達成してください。";
                    break;
                case "test":
                    optionView.modeTitle = "テストモード";
                    optionView.modeText = "制限時間内に問題を解いてください。";
                    optionView.isTestMode = true;
                    optionView.limitTimeText = this.__getFormatTime(this.view.limitTime);

                    break;
                }


                template = "";


                if (this.view.visionary !== "vcet") {
                    if (this.view.previewType === "book") {

                        if (window.playerModel.get("isMobile")) {
                            template = templateS_SP;
                        } else {
                            template = templateS;
                        }


                    } else {

                        if (window.playerModel.get("isMobile")) {
                            template = templateM_SP;
                        } else {
                            template = templateM;
                        }

                    }
                }


                if (!window.playerModel.get("hideBookCoverOption")) {
                    html = $.mustache(template, optionView);
                    this.$el.html(html);
                }

                return this;
            },
            __getFormatTime: function (time) {
                time = Number(time);

                var formatTimeime = "",
                //分
                    s = Math.floor(time / 60),
                //秒
                    m = time - s * 60;

                formatTimeime += $.StringUtilPlugin.addZero(s) + "分";
                return formatTimeime;
            }


        });
    }
);


