define('app/view/StartPageView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        "app/view/BookIndexView",
        "app/view/BookCoverOptionView",
        'text!app/templates/view/StartPageView.html'
    ],
    function (
        $,
        AbstractBackbornView,
        BookIndexView,
        BookCoverOptionView,
        template
    ) {
        
        return AbstractBackbornView.extend({

            className: "startContainer",

            /**
             * コンストラクタ
             */
            initialize: function (options) {

                var view = {
                    previewType: window.playerModel.get("previewType"),
                    bookcoverImageURL: this.model.get("bookcoverImageURL"),
                    booktitle: this.model.get("booktitle"),
                    explanation: this.model.get("explanation"),
                    bookIndex: this.model.get("bookIndex"),
                    mode: this.model.get("mode"),
                    limitTime: this.model.get("limitTime"),
                    mission: this.model.get("mission"),
                    questionLangth: this.model.get("questions").length
                };

                if (window.playerModel.get("visionary")) {
                    view.visionary = window.playerModel.get("visionary");
                }


                view.showCoverImage = !(window.playerModel.get("isPreview") === true && window.playerModel.get("previewType") !== "assign");

                this.view = view;
            },
            render: function () {

                console.log("StartPageView.render()");

                var html,
                    bookCoverOptionView,
                    bookIndex;

                html = $.mustache(template, this.view);
                this.$el.html(html);

                bookCoverOptionView = new BookCoverOptionView({
                    view: this.view
                });

                bookCoverOptionView.render();

                this.$(".startBoxMain .bookOption").append(bookCoverOptionView.el);

                bookIndex = new BookIndexView({
                    view: this.view,
                    model: this.model
                });
                bookIndex.render();

                this.$(".startBoxMain .bookindex").append(bookIndex.el);

                return this;
            }


        });

    }
);


