/*global require: false, define: false, Class: false, Audio:false */
define('app/view/TestModeListeningCombinationQuestionView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        'text!app/templates/view/TestModeListeningCombinationQuestionView.html'
    ],
    function (
        $,
        AbstractBackbornView,
        template
    ) {
        
        /**
         * TestModeListeningCombinationQuestionView
         *
         * テストモードの音声再生
         *
         * @param {Object} el
         * @param {Object} view
         */
        return AbstractBackbornView.extend({
            tabName: "div",
            className: "combinationConterner",

            startButton : null,
            startButton2 : null,
            soundPlayerBox : null,

            /**
             *
             */
            render: function () {

                var html, scope;

                html = $.mustache(template, this.model.toJSON());

                this.$el.append(html);


                if (this.model.get("sound_plays") === 0) {


                    window.onWPPlayerReady = function () {
                        //フラッシュのPlayerの準備ができたイベント
                        console.log("onWPPlayerReady");
                        //AudioPlayer.open("audioplayer_combination_" + scope.view.no );
                    };


                    this.soundPlayerBox = $('<div id="soundPlayerBox"><p id="soundPlayerBoxComment">音声を再生します。音声は１回しか聞くことができません。</p></div>');
                    $("#popupBox", this.el).append(this.soundPlayerBox);


                    this.startButton = $('<a href="#" id="playAudioButton" class="button btn btn-block btn-vc2 fancyboxButton" >スタート</a>');
                    this.startButton.css("cursor", "pointer");
                    this.startButton.click($.proxy(this._onClickPlayButton, this));

                    $(this.soundPlayerBox).append(this.startButton);


                    $.logger.debug("■■■■■■■■■■■■");




                    setTimeout(function () {


                        $.fancybox($("#popupBox"), {

                            'type': 'inline',
                            'openEffect': 'none',
                            'closeEffect': 'none',

                            'closeBtn': false,


                            helpers: {
                                overlay: {
                                    closeClick: false,
                                    css: {
                                        'background': 'rgba(255, 255, 255, 0.9)'
                                    }
                                }
                            }

                        });


                    }, 100);


                } else {
                    setTimeout(function () {
                        $(".soundWraper").html("音声の再生が終わりました。");
                    }, 100);
                }

                return this;
            },
            _onClickJumpButton: function (e) {
                e.preventDefault();

                $.publish('/QuestionController/showJampButton', null);
            },
            /**
             * スタートボタンクリック
             * @param {Object} e
             */
            _onClickPlayButton: function (e) {
                e.preventDefault();

                //再生回数をカウントアップ
                this.model.set("sound_plays", this.model.get("sound_plays") + 1);

                this.startButton.unbind("click", $.proxy(this._onClickPlayButton, this));
                this.startButton.remove();

                var scope, audioObj;
                scope = this;

                if ($('.sound audio').length) {

                    audioObj = new Audio(this.model.get("sound"));
                    $(audioObj).bind("playing", function () {
                        $("#soundPlayerBoxComment", scope.soundPlayerBox).html("再生中・・・");
                    });
                    $(audioObj).bind("ended", function () {
                        scope._showPlayEndWindow();
                    });
                    audioObj.play();

                } else {
                    //

                    window.onWPPlayerPlay = function () {
                        //フラッシュのPlayerの再生開始イベント
                        console.log("onWPPlayerPlay");
                        $("#soundPlayerBoxComment", scope.soundPlayerBox).html("再生中・・・");

                    };
                    window.onWPPlayerStop = function () {
                        //フラッシュのPlayerの再生終了イベント
                        console.log("onWPPlayerStop");

                        scope._showPlayEndWindow();
                    };


                    $("#audioplayer_combination_" + this.model.get("no")).html("");


                    window.AudioPlayer.getPlayer("audioplayer_combination_" + this.model.get("no")).addListener("PLAY", "onWPPlayerPlay");
                    window.AudioPlayer.getPlayer("audioplayer_combination_" + this.model.get("no")).addListener("STOP", "onWPPlayerStop");


                    window.AudioPlayer.open("audioplayer_combination_" + this.model.get("no"));


                }

            },

            /**
             * 再生終了画面を表示する
             */
            _showPlayEndWindow: function () {

                $("#soundPlayerBoxComment", this.soundPlayerBox).html("再生終了。問題を開始します。");

                this.startButton2 = $('<a href="#" id="playAudioButton2" class="button  btn btn-block btn-vc2 fancyboxButton">スタート</a>');
                this.startButton2.css("cursor", "pointer");
                this.startButton2.click($.proxy(this._onClickPlayButton2, this));

                $(this.soundPlayerBox).append(this.startButton2);

                $(".soundWraper").html("音声の再生が終わりました。");
            },
            /**
             *
             */
            _onClickPlayButton2: function (e) {
                e.preventDefault();

                this.startButton2.unbind("click", $.proxy(this._onClickPlayButton2, this));
                this.startButton2.remove();


                $.fancybox.close();


            }

        });
    }
);


/*global require: false, define: false, Class: false */
define('app/view/CountDownTimerView',
    [
        "jQuery",
        "app/view/AbstractBackbornView"
    ],
    function (
        $,
        AbstractBackbornView
    ) {
        
        /**
         * CountDownTimerView
         *
         * @param {Object} el
         * @param {Object} view
         */
        return AbstractBackbornView.extend({


            initialize: function (options) {
                this.view = options.view;

                /*
                 * プロパティー
                 */


                /** 経過時間 */
                this._processTime = 0;
                /** 残り時間 */
                this._lastOfTime = 0;
                /** タイマーがスタートしているかどうか */
                this._isStartTimer = false;
                /** 制限時間用インターバルID */
                this._timerInterval = -1;


                this._startTime = 0;

                var defaults = {
                    //制限時間 ３分
                    'limitTime': 0.1 * 60,
                    //タイムアップイベント
                    'timeup': null,
                    'title': ""
                };


                //設定情報の構築
                this.settings = $.extend(defaults, this.view);

            },
            /**
             * 制限時間タイマーを開始する
             */
            startTimer: function () {

                this._isStartTimer = true;
                this._startTime = new Date().getTime();
                this._timerInterval = setInterval($.proxy(this.__countUpTime, this), 1000);
                $.logger.debug("startTimer");
                this.render();
            },


            /**
             *
             */
            stopTimer: function () {
                this._isStartTimer = false;

                $.logger.debug("stopTimer::::_timerInterval:" + this._timerInterval);

                clearInterval(this._timerInterval);
            },


            /**
             *
             */
            clearTimer: function () {
                this._lastOfTime = this.settings.limitTime;
                this.render();
            },
            /**
             *
             */
            __countUpTime: function () {

                var nowTime = new Date().getTime();
                this._processTime = Math.floor((nowTime - this._startTime) / 1000);

                //$.logger.debug("_processTime:" + this._processTime);


                this._lastOfTime = this.settings.limitTime - this._processTime;

                if (this._lastOfTime <= 0) {
                    this.__timeUp();
                }
                this.render();
            },
            /**
             *
             */
            __timeUp: function () {
                //$.logger.debug("__timeUp" );
                this.stopTimer();
                if (this.settings.timeup !== null) {
                    this.settings.timeup();
                }
                //dispatchEvent({type:TIME_UP_EVENT, target:this});
            },
            /**
             *
             */
            __getFormatTime: function () {

                var formatTimeime, s, m;

                formatTimeime = "";
                //分
                s = Math.floor(this._lastOfTime / 60);
                //秒
                m = this._lastOfTime - s * 60;
                formatTimeime += $.StringUtilPlugin.addZero(s) + ":" + $.StringUtilPlugin.addZero(m);
                return formatTimeime;
            },

            /**
             *
             */
            render: function () {

                var per = Math.floor(this._processTime/this.settings.limitTime*100 );

                this.$el.html(this.settings.title + this.__getFormatTime().toString());
                this.trigger("/CountDownTimerView/render", [per]);
                return this;
            }
        });
    }
);
define('text!app/templates/view/SpeedReadingCombinationQuestionView.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="combinationHeader">\n    {{questionNumber}} {{title}}<br/>\n    {{direction}}\n</div>\n<div class="combinationQuestion">\n    <div class="innerQuestionBox"></div>\n</div>\n<div class="combinationMain">\n    <!-- 何もしない  -->\n</div>\n<div id="speedreadingBox">\n    <p class="direction">次の英文を読み、問題に答えなさい。<br />（制限時間が過ぎると、またはスキップボタンをクリックすると問題が表示されます。）</p>\n    <div class="progressBox">\n        <table>\n            <tr>\n                <td><span class="icon-time"></span></td>\n                <td style="width: 100%;">\n                    <div class="progress" style="height: 12px;">\n                        <div class="bar bar-warning" style="width: 100%;"></div>\n                    </div>\n                </td>\n                <td>\n                    <div id="speedreadingtimer"></div>\n                </td>\n                <td>\n                    <a href="#" id="skipPassageButton" class="button btn btn-block  btn-mini btn-vc2" >スキップ</a>\n                </td>\n            </tr>\n        </table>\n\n    </div>\n\n\n\n    <div class="passageBox"><p>{{{passage}}}</p></div>\n</div>\n';});

/*global require: false, define: false, Class: false, Audio:false */
define('app/view/SpeedReadingCombinationQuestionView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        "app/view/CountDownTimerView",
        'text!app/templates/view/SpeedReadingCombinationQuestionView.html'
    ],
    function (
        $,
        AbstractBackbornView,
        CountDownTimerView,
        template
    ) {
        
        /**
         * TestModeListeningCombinationQuestionView
         *
         * テストモードの音声再生
         *
         * @param {Object} el
         * @param {Object} view
         */
        return AbstractBackbornView.extend({
            tabName: "div",
            className: "combinationConterner speedReadingCombinationQuestionView-combinationConterner",

            skipButton : null,
            timerViewer : null,
            speedreadingBox: null,
            /**
             * 単語数をカウントして返す
             *
             * @param targetString  カウント対象の文字列
             * @returns {*}
             * @private
             */
            _getWordCount: function (targetString) {
                //単語数
                var returnNumber = 0;
                //文字が空の場合
                if (targetString === "") {
                    return returnNumber;
                }
                //単語数をカウントする
                returnNumber = targetString.split(" ").length;

                return returnNumber;
            },

            _timeupQuestion: function () {


                $("#prevButton", "#header").show();
                $("#prevButton", "#header").show();
                $("#nextButton", "#header").show();
                $("#questionNumberView", "#header").show();

                this.$(".combinationHeader").show();
                this.$(".combinationQuestion").show();
                this.$(".combinationMain").show();

                this.speedreadingBox.hide();

                this.stopListening();

            },

            /**
             * タイマーをスタートする
             */
            _startTimer: function () {

                var limitTime, view;

                limitTime = Math.floor(this._getWordCount(this.model.get("passage")) * this.model.get("speed"));


                view = {
                    "limitTime": limitTime,
                    "timeup": $.proxy(this._timeupQuestion, this),
                    "title": ""
                };
                this.timerViewer = new CountDownTimerView({el: $("#speedreadingtimer"), view: view});
                this.listenTo(this.timerViewer, '/CountDownTimerView/render', this._countDown);
                this.timerViewer.startTimer();
            },


            _countDown: function (per) {
                this.$(".progress .bar").css({width:(100-per)+ "%"});
                console.log(per);
            },
            /**
             *
             */
            render: function () {

                var html;
                html = $.mustache(template, this.model.toJSON());

                this.$el.append(html);

                // TODO 別のところに写したい


                this.$(".combinationHeader").hide();
                this.$(".combinationQuestion").hide();
                this.$(".combinationMain").hide();



                var scope = this;

                setTimeout(function () {
                    scope.speedreadingBox =  $("#speedreadingBox");

                    scope.skipButton =  $("#skipPassageButton");
                    scope.skipButton.css("cursor", "pointer");
                    scope.skipButton.click($.proxy(scope._onClickSkipButton, scope));


                },100);
                setTimeout(function () {


                    $("#prevButton", "#header").fadeOut();
                    $("#prevButton", "#header").fadeOut();
                    $("#nextButton", "#header").fadeOut();
                    $("#questionNumberView", "#header").fadeOut();


                    scope._startTimer();

                },800);

                return this;
            },

            /**
             * スキップボタンクリック
             * @param {Object} e
             */
            _onClickSkipButton: function (e) {
                e.preventDefault();


                // TODO 別のところに写したい

                $("#prevButton", "#header").show();
                $("#prevButton", "#header").show();
                $("#nextButton", "#header").show();
                $("#questionNumberView", "#header").show();


                this.$(".combinationHeader").show();
                this.$(".combinationQuestion").show();
                this.$(".combinationMain").show();

                this.speedreadingBox.hide();
                this.stopListening();

            }
        });
    }
);


