/*global require: false, define: false, Class: false, Audio:false */
define('app/questionbuilder/QuestionView',
    [
        "jQuery",
        "Backbone",
        "Marionette",
        'text!app/templates/questionbuilder/QuestionTitle.html',
        'text!app/templates/questionbuilder/QuestionViewNormalSoundHTML.html',
        'text!app/templates/questionbuilder/QuestionViewNormalSoundHTMLMobile.html',
        'text!app/templates/questionbuilder/QuestionViewOnlyOnceSoundHTML.html',
        'text!app/templates/questionbuilder/QuestionViewOnlyOnceSoundPlayedHTML.html'
    ],
    function (
        $,
        Backbone,
        Marionette,
        questionTitle,
        questionViewNormalSoundHTML,
        questionViewNormalSoundHTMLMobile,
        questionViewOnlyOnceSoundHTML,
        questionViewOnlyOnceSoundPlayedHTML
    ) {
        


        var QuestionView;


        /**
         * QuestionView
         */
        QuestionView = Marionette.ItemView.extend({

            /**
             * コンストラクタ
             * @param {Object} option
             */
            initialize: function (option) {
                this.question = option.question;
                this.audioObj = null;
                this.isOnceSound = false;
            },
            render: function () {
                this._build();
                this._restoreAnswer();
                this.__onStartSuper();
                this._onStart();

                return this;
            },
            destroy: function () {
                this.undelegateEvents();



                if (this.question.get("questionType") === "typing" || this.question.get("questionType") === "dictationTyping") {
                    // タイピング問題はスキップ
                    return;
                }

                if (this.isOnceSound) {

                    $('.playSoundButton', this.el).unbind("click", $.proxy(this.__playSound, this));

                    if ($.browser.name !== "safari" && $.browser.name !== "chrome") {

                        var soundpath = this.question.get("sound");

                        try {
                            window.JsSoundPlayer.stop(soundpath);
                            window.JsSoundPlayer.removeListener(this);
                        } catch (e) {
                            //原因が分からないがIE8でエラーになる
                        }

                    } else {
                        if (this.audioObj !== null) {
                            this.audioObj.pause();
                            this.audioObj = null;
                        }
                    }
                } else {

                    if (this.question.get("sound") && window.playerModel.get("isMobile")) {
                        $(document).unbind("keydown", $.proxy(this.__playSoundMobileKeydown, this));
                        $('.playSoundButton', this.el).unbind($.proxy(this.__playSoundMobile, this));

                        if (this.audioObj !== null) {
                            this.audioObj.pause();
                            this.audioObj = null;
                        }
                    }
                }


                // TODO ここにリスナーの解除処理をいれること
                // this.close();

                //サブクラスが実装する 必ずスーパークラスを呼ぶこと
            },
            /**
             *
             */
            _build: function () {
                //サブクラスが実装する
            },

            /**
             *
             */
            _refresh: function () {
                //サブクラスが実装する
            },
            /**
             * 答えを復元する
             */
            _restoreAnswer: function () {
                //サブクラスが実装する
            },
            /**
             * 問題がスタートした(スーパークラス)
             */
            __onStartSuper: function () {

                if (this.question.get("questionType") === "typing" || this.question.get("questionType") === "dictationTyping") {
                    // タイピング問題はスキップ
                    return;
                }

                if (this.isOnceSound) {
                    $('.playSoundButton', this.el).click($.proxy(this.__playSound, this));
                } else {
                    if (this.question.get("sound") && window.playerModel.get("isMobile")) {
                        $(document).bind("keydown", $.proxy(this.__playSoundMobileKeydown, this));
                        $('.playSoundButton', this.el).click($.proxy(this.__playSoundMobile, this));
                    }
                }

            },
            /**
             * 問題がスタートした
             */
            _onStart: function () {
                //サブクラスが実装する
            },

            /**
             * タイトルを返す
             */
            getTitleHTML: function () {

                var template, html;


                template = questionTitle;

                html = $.mustache(template, this.question.toJSON());

                return html;
            },
            /**
             * Sound HTMLを返す
             */
            getSoundHTML: function () {


                var html = "";

                if (this.question.get("sound")) {

                    if (this.question.get("isTestMode")) {

                        html = this.getOnlyOnceSoundHTML();

                    } else {
                        if (window.playerModel.get("isMobile")) {
                            html = this.getNormalSoundHTMLMobile();
                        } else {
                            html = this.getNormalSoundHTML();
                        }
                    }

                }


                return html;
            },
            /**
             * 通常用のSound HTMLを返す
             */
            getNormalSoundHTML: function () {


                var template, html;

                template = questionViewNormalSoundHTML;


                html = $.mustache(template, this.question.toJSON());

                return html;
            },

            /**
             * 通常用のSound HTMLを返す(モバイル)
             */
            getNormalSoundHTMLMobile: function () {
                var html, template;

                template = questionViewNormalSoundHTMLMobile;

                html = $.mustache(template, this.question.toJSON());

                return html;
            },

            /**
             * テストモード用のSound HTMLを返す
             */
            getOnlyOnceSoundHTML: function () {


                var html = "",
                    template;

                if (this.question.get("isTestModeSoundPlayed")) {

                    /*
                     再生済みの場合
                     */
                    template = questionViewOnlyOnceSoundPlayedHTML;
                    html = $.mustache(template, null);

                } else {

                    this.isOnceSound = true;

                    if ($.browser.name !== "safari" && $.browser.name !== "chrome") {
                        window.JsSoundPlayer.addListener(this);
                    }

                    template = questionViewOnlyOnceSoundHTML;
                    html = $.mustache(template, this.question.toJSON());
                }
                return html;
            },
            /**
             * 音声再生終了（SWF版）
             */
            onPlayEndJsSoundPlayer: function () {
                $(".playSoundButton", this.el).html('<img src="images/headphone_icon_b.png" />音声の再生が終了しました。');
            },
            /**
             * テストモードの音声を再生する
             */
            __playSound: function () {


                if (!this.isOnceSound) {
                    return;
                }


                //再生済みにする
                this.question.set("isTestModeSoundPlayed", true);

                $('.playSoundButton', this.el).unbind("click", $.proxy(this.__playSound, this));


                var soundpath,
                    scope,
                    audioObj;

                soundpath = this.question.get("sound");

                scope = this;

                $(".playSoundButton").removeClass("btn");
                $(".playSoundButton").removeClass("btn-vc2");

                if ($('.sound audio', this.el).length) {

                    audioObj = new Audio(soundpath);
                    $(audioObj).bind("playing", function () {
                        $(".playSoundButton", scope.el).html('<img src="images/headphone_icon_b.png" />再生中・・・');
                    });
                    $(audioObj).bind("ended", function () {

                        $(".playSoundButton", scope.el).html('<img src="images/headphone_icon_b.png" />音声の再生が終了しました。');
                    });
                    audioObj.play();

                    this.audioObj = audioObj;

                } else {
                    $(".playSoundButton", scope.el).html('<img src="images/headphone_icon_b.png" />再生中・・・');
                    window.JsSoundPlayer.play(soundpath);
                }

            },
            /**
             * 音声を再生する（モバイル）
             */
            __playSoundMobile: function () {

                var soundpath, scope, audioObj;

                soundpath = this.question.get("sound");

                scope = this;

                if ($('.sound audio', this.el).length) {

                    audioObj = new Audio(soundpath);
                    $(audioObj).bind("playing", function () {
                        $(".playSoundButtonComment", this.el).html('再生中・・・');
                    });
                    $(audioObj).bind("ended", function () {
                        $(".playSoundButtonComment", scope.el).html('音声の再生が終了しました。');
                    });
                    audioObj.play();

                    this.audioObj = audioObj;

                }

            },
            __playSoundMobileKeydown: function (event) {

                if (event.keyCode === 13) {
                    this.__playSoundMobile();
                }

            }



        });

        return QuestionView;
    }
);
define('text!app/templates/questionbuilder/MultipleChoiceQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n\n    {{{sound_html}}}\n    <div class="question lang-{{lang}}" lang="{{lang}}">{{{question}}}</div>\n\n\n    {{#image}}\n    <div><img src="{{image}}"/></div>\n    {{/image}}\n    <div class="choices">\n        <ul>\n            {{#choices}}\n            <li>\n                <span class="choice lang-{{lang}}" lang="{{lang}}" ref="{{index}}"><span class="chackmarkicon"></span>{{text}}</span>\n            </li>\n            {{/choices}}\n        </ul>\n    </div>\n</div>\n';});

/*global require: false, define: false, Class: false */
define('app/questionbuilder/MultipleChoiceQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/MultipleChoiceQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
          * MultipleChoiceQuestion
         */
        return QuestionView.extend({

            events: {
                "click  .choices li span.choice": "doAnswer"
            },
            /**
             *
             */
            _build: function () {
                var title_html, sound_html, html;

                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();

                html = $.mustache(template,
                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())
                        );

                this.$el.append(html);


                // 言語設定をする
                $(".question span", this.el).each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });

                if (this.question.get("isHBox")) {
                    $(".questionBox .choices ul").addClass("hBox");
                }

                $(".questionBox .choices li span").hover(
                    function () {
                        $(this).addClass("over");
                    },
                    function () {
                        $(this).removeClass("over");
                    }
                );


                //選択できないようにする
                $(".questionBox div", this.el).disableTextSelect();

            },
            /**
             * 答えを保存する
             *
             * @param {Object} e
             */
            doAnswer: function (e) {

                var selectChoice, answers_str;
                selectChoice = $(e.currentTarget);
                selectChoice.addClass("select");

                $(".questionBox .choices li span").not(selectChoice).removeClass("select");

                answers_str = selectChoice.attr("ref");

                console.log("answers_str:" + answers_str);

                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }


            },
            _restoreAnswer: function () {
                var yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {
                    $(".questionBox .choices li span").filter("[ref='" + yourAnswer + "']").addClass("select");
                }
            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);

                this.undelegateEvents();

            }

        });


    }
);
define('text!app/templates/questionbuilder/UnderLineChoiceQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    <div class="questionTitle"><span class="questionNumber">{{questionNumber}}</span>: {{title}}{{#sound}}<span\n            class="headphone_icon"></span>{{/sound}}\n    </div>\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n    {{#sound}}\n    <div class="sound" id="audioplayer_{{no}}">\n        <audio controls autobuffer src="{{sound}}"></audio>\n    </div>\n    <script type="text/javascript">\n        AudioPlayer.embed("audioplayer_{{no}}", {\n            soundFile: "{{sound}}",\n            titles: "#1",\n            artists: "Track"\n        });\n    </script>\n    {{/sound}}\n    <div class="question lang-{{lang}}" lang="{{lang}}">{{{questionParsedString}}}</div>\n    {{#image}}\n    <div><img src="{{image}}"/></div>\n    {{/image}}\n</div>\n';});

