define('text!app/templates/questionbuilder/PopUpQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n    {{{sound_html}}}\n    <div style="display:none;">\n        <div id="popupBox">\n            <p>選択してください。</p>\n            <ul>\n                {{#choices}}\n                <li><span class="choice lang-{{lang}}" lang="{{lang}}" ref="{{index}}">{{text}}</span></li>\n                {{/choices}}\n            </ul>\n        </div>\n    </div>\n    <div class="question lang-{{lang}}" lang="{{lang}}">{{{popupQuestion}}}</div>\n\n    {{#image}}\n    <div><img src="{{image}}"/></div>\n    {{/image}}\n</div>\n';});

/*global require: false, define: false, Class: false */
define('app/questionbuilder/PopUpQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/PopUpQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * PopUpQuestion
         *
         * @param {Object} el
         * @param {Object} question
         */
        return QuestionView.extend({



            /**
             *
             */
            _build: function () {

                var title_html,
                    sound_html,
                    html,
                    insertionPosition,
                    scope;

                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();

                this.question.set("popupQuestion", this.question.get("question").replace(/\*/, '<span id="insertionPosition" class="insertionPosition" ref="">(　　　　　　　)</span>'));


                html = $.mustache(template,
                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())
                     );

                this.$el.append(html);


                // 言語設定をする
                $(".question span", this.el).each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });


                insertionPosition = $("#insertionPosition");


                insertionPosition.click(function () {



                    //フォーカスを解除する
                    $("#popupBox li span").removeClass("current");

                    //穴に段落番号が入っていたら、その段落にフォーカスする
                    if (insertionPosition.attr("ref") !== "") {
                        $("#popupBox li span").filter("[ref='" + insertionPosition.attr("ref") + "']").addClass("current");
                    }


                    $.fancybox($("#popupBox"), {
                        'hideOnOverlayClick': true,
                        'type': 'inline',
                        'openEffect': 'none',
                        'closeEffect': 'none'
                    });

                    return false;
                });


                scope = this;


                $("#popupBox li span").hover(
                    function () {
                        $(this).addClass("over");
                    },
                    function () {
                        $(this).removeClass("over");
                    }
                );

                $("#popupBox li span").click(
                    function (e) {
                        scope.doAnswer(e);
                    }
                );


                //選択できないようにする
                $(".questionBox div", this.el).disableTextSelect();

            },
            doAnswer: function (e) {


                var target, insertionPosition, isSameWord, removeSelected, answers_str;

                //新しく、選択した段落
                target = $(e.currentTarget);

                insertionPosition = $("#insertionPosition");

                isSameWord = (target.attr("ref") === insertionPosition.attr("ref"));


                //穴に段落番号が入っていたら、その段落の選択状態を解除する
                if (insertionPosition.attr("ref") !== "") {
                    //選択状態をクリアする

                    removeSelected = $("#popupBox li span").filter("[ref='" + insertionPosition.attr("ref") + "']");
                    removeSelected.removeClass("select");
                }


                if (!isSameWord) {

                    //選択状態にする
                    target.addClass("select");

                    //段落番号をセットする
                    insertionPosition.attr("ref", target.attr("ref"));

                    insertionPosition.html(target.html());

                } else {

                    //同じものを選択すると、削除される
                    //使っている穴をクリアする
                    insertionPosition.html("(　　　　　　　)");
                    insertionPosition.attr("ref", "");
                }


                $.fancybox.close();


                answers_str = insertionPosition.attr("ref");


                //答えは１から、リストは０から
                if (answers_str !== "") {
                    answers_str = Number(answers_str);
                }

                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }

            },
            _restoreAnswer: function () {
                var yourAnswer, word, insertionPosition;


                yourAnswer = this.question.get("yourAnswer");


                if (yourAnswer !== "") {

                    word = $("#popupBox li span").filter("[ref='" + Number(yourAnswer) + "']");
                    //選択状態にする
                    word.addClass("select");

                    insertionPosition = $("#insertionPosition");

                    //段落番号をセットする
                    insertionPosition.attr("ref", word.attr("ref"));
                    insertionPosition.html(word.html());


                }

            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.undelegateEvents();
            }

        });


    }
);
define('text!app/templates/questionbuilder/AnaumeFilInQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\r\n<div class="questionBox">\r\n    {{{title_html}}}\r\n    {{#direction}}\r\n    <div class="direction">{{{direction}}}</div>\r\n    {{/direction}}\r\n    {{{sound_html}}}\r\n    <div class="question">{{{questionParsedString}}}</div>\r\n\r\n    {{#image}}\r\n    <div><img src="{{image}}"/></div>\r\n    {{/image}}\r\n</div>\r\n';});

/*global _:false, require: false, define: false, Class: false */
define('app/questionbuilder/AnaumeFilInQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/AnaumeFilInQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * AnaumeFilInQuestion
         *
         * @param {Object} el
         * @param {Object} question
         */
        return QuestionView.extend({

            events: _.extend(
                {
                    "focusout .questionBox :text": "doAnswer",
                    "keyup .questionBox :text": "doAnswer"
                },
                QuestionView.prototype.events
            ),




            /**
             *
             */
            _build: function () {
                var title_html,
                    sound_html,
                    html,
                    answer1,
                    answer2;

                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();

                html = $.mustache(
                    template,
                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())
                );

                this.$el.append(html);


                if (this.question.get("initialLetterShown")) {
                    answer1 = this.question.get("answers")[0];
                    answer2 = answer1.split("/");
                    $(answer2).each(function (i, val) {
                        $(".questionBox :text").eq(i).val(val.charAt(0));
                    });
                }



                //選択できないようにする
                $(".question span", this.el).disableTextSelect();


            },
            doAnswer: function (e) {

                var answers_str;

                answers_str = $(".questionBox :text").map(function () {
                    return $.trim($(this).val());
                }).get().join("###");

                //解答はトリムして入れる
                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }

            },
            _restoreAnswer: function () {

                var yourAnswer,
                    answers;

                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {
                    answers = yourAnswer.split("###");

                    $(answers).each(function (i, val) {
                        $(".questionBox :text").eq(i).val(val);
                    });
                }
            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.undelegateEvents();
            }

        });

    }
);
define('text!app/templates/questionbuilder/SortingAQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox questionBox-SortingAQuestion">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n    {{{sound_html}}}\n    <div class="question lang-{{lang}}" lang="{{lang}}">{{{questionParsedString}}}</div>\n    <div class="choices">\n        <ul class="sortStringList">\n            {{#sortStringList}}\n            <li class="lang-{{lang}}" lang="{{lang}}">{{{.}}}</li>\n            {{/sortStringList}}\n        </ul>\n    </div>\n\n    {{#image}}\n    <div><img src="{{image}}"/></div>\n    {{/image}}\n</div>\n';});

/*global require: false, define: false, Class: false */
define('app/questionbuilder/SortingAQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/SortingAQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * SortingAQuestionBuilder
         */
        return QuestionView.extend({

            events : {
                "click .questionBox .choices li" : "onClickSortingAQuestion",
                "click .resetButton" : "_reset",
                "sortupdate .questionBox .sortingPoint li" : "_onSortUpdate"
            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.$el.undelegate(".questionBox .choices li", 'click');
                this.$el.undelegate(".sortingPoint", 'sortupdate');

                this.undelegateEvents();

            },
            _build: function () {
                var title_html, sound_html, html, bottons, resetButton;

                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();


                html = $.mustache(template,

                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())


                    );

                this.$el.append(html);

                // 言語設定をする
                $(".question span", this.el).each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });

                $(".questionBox .choices li").hover(
                    function () {
                        $(this).addClass("over");
                    },
                    function () {
                        $(this).removeClass("over");
                    }
                );

                $(".sortingPoint").sortable({
                    placeholder: 'sortingWord ui-state-highlight',
                    //,forcePlaceholderSize:true
                    //,connectWith: '.sortingPoint'
                    tolerance: 'pointer',
                    items: 'li',
                    scroll: false,
                    start: function (event, ui) {
                        // modify ui.placeholder however you like
                        ui.placeholder.html("<span>" + $("span", ui.helper).text() + "</span>");
                    }

                }).addTouch();

                $(".sortingPoint").on("sortupdate", $.proxy(this._onSortUpdate, this));
                $(".sortingPoint").disableSelection();





                bottons = $('<div class="buttons"></div>');

                resetButton = $('<a href="#" class="btn resetButton">' + $.global.culture.player.buttons.resetButton + '</a>');


                bottons.append(resetButton);


                $(".questionBox").append(bottons);

                //選択できないようにする
                $(".questionBox div", this.el).disableTextSelect();
            },
            /**
             *
             */
            _onSortUpdate: function (event) {
                $.logger.debug("_onSortUpdate");

                this.doAnswer();
            },

            /**
             *
             */
            onClickSortingAQuestion: function (event) {
                $.logger.debug("onClickSortingAQuestion");
                var target = $(event.currentTarget);
                this._pushSortiongArea(target);
                this.doAnswer();
            },
            /**
             *
             */
            _pushSortiongArea: function (target) {
                $.logger.debug("_pushSortiongArea");

                var sortingWord = $.mustache('<li class="sortingWord lang-{{lang}}" lang="lang" ref="{{text}}"><span>{{text}}</span></li>', {
                    text: target.text(),
                    lang: this.question.get("lang")
                });


                $(".sortingPoint").append(sortingWord);
                target.remove();
            },


            /**
             * 表示をリセットする
             * @param {Object} e
             */
            _reset: function (e) {
                e.preventDefault();

                this.destroy();

                this.$el.html("");
                this._build();
                // もう一度イベントを登録し直す。
                this.delegateEvents(this.events);
            },
            doAnswer: function (e) {

                var answers_str;
                answers_str = $(".sortingWord").map(function () {
                    return $(this).text();
                }).get().join("###");

                $.logger.debug("::::" + $(".sortingWord").length + ":" + answers_str);

                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }

            },
            _restoreAnswer: function () {


                var yourAnswer, answers, controll, targetText;

                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {

                    answers = yourAnswer.split("###");

                    controll = this;

                    $(answers).each(function (i, val) {

                        $(".questionBox .choices li").each(

                            function (i2, val2) {

                                targetText = $(val2).text();

                                if (val === targetText) {
                                    controll._pushSortiongArea($(this));
                                    return false;
                                }
                            }

                        );

                    });
                }
            }



        });


    }
);




define('text!app/templates/questionbuilder/MultipleCorrectQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n\n    {{{sound_html}}}\n    <div class="question lang-{{lang}}" lang="{{lang}}">{{{question}}}</div>\n\n    {{#image}}\n    <div><img src="{{image}}"/></div>\n    {{/image}}\n    <div class="choices">\n        <ul>\n            {{#choices}}\n            <li><span class="choice lang-{{lang}}" lang="{{lang}}" ref="{{index}}"><span class="chackmarkicon"></span>{{text}}</span>\n            </li>\n            {{/choices}}\n        </ul>\n    </div>\n</div>\n';});

/*global require: false, define: false, Class: false */
define('app/questionbuilder/MultipleCorrectQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/MultipleCorrectQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * MultipleCorrectQuestion
         *
         * @param {Object} el
         * @param {Object} question
         */
        return QuestionView.extend({

            events: {
                "click .questionBox .choices li span": "doAnswer"
            },
            /**
             *
             */
            _build: function () {
                var title_html,
                    sound_html,
                    html;
                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();

                html = $.mustache(template,
                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())
                    );
                console.log("-----------------------");
                console.log(this.question.toJSON());




                this.$el.append(html);

                // 言語設定をする
                $(".question span", this.el).each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });


                $(".questionBox .choices li span").hover(
                    function () {
                        $(this).addClass("over");
                    },
                    function () {
                        $(this).removeClass("over");
                    }
                );

                //選択できないようにする
                $(".questionBox div", this.el).disableTextSelect();

            },
            doAnswer: function (e) {


                var selectChoice, answers_str, answers_arr;

                selectChoice = $(e.currentTarget);
                if (selectChoice.hasClass("select")) {
                    selectChoice.removeClass("select");
                } else {
                    selectChoice.addClass("select");
                }




                answers_arr = $(".questionBox .choices li span.select").map(function () {
                    return Number($(this).attr("ref"));
                }).get();

                //昇順にソートする
                answers_arr.sort();

                answers_str = answers_arr.join(",");


                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }
            },

            _restoreAnswer: function () {
                var yourAnswer, answers;

                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {

                    answers = yourAnswer.split(",");

                    $(answers).each(function (i, val) {
                        $(".questionBox .choices li span").filter("[ref='" + val + "']").addClass("select");
                    });
                }
            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.undelegateEvents();
                this.$el.undelegate(".questionBox .choices li span", 'click');
            }
        });
    }
);
define('text!app/templates/questionbuilder/ClozeTestQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n    {{{sound_html}}}\n    <div class="clozeTestQuestion">{{{questionParsedString}}}</div>\n</div>\n\n\n\n\n\n';});

/*global　_:false, require: false, define: false, Class: false */
define('app/questionbuilder/ClozeTestQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/ClozeTestQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * ClozeTestQuestion
         */
        return QuestionView.extend({


            events: _.extend(
                {
                    "focusout .questionBox :text": "doAnswer"
                },
                QuestionView.prototype.events
            ),



            /**
             *
             */
            _build: function () {

                var title_html,
                    sound_html,
                    html;

                title_html = this.getTitleHTML();
                sound_html = this.getSoundHTML();


                html = $.mustache(
                    template,

                    $.extend({
                        title_html: title_html,
                        sound_html: sound_html
                    }, this.question.toJSON())

                );

                this.$el.append(html);


                //選択できないようにする
                $(".clozeTestQuestion span", this.el).disableTextSelect();


            },
            doAnswer: function (e) {
                var answers_str;

                answers_str = $(".questionBox :text").map(function () {
                    return $(this).val();
                }).get().join("###");

                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }

            },
            _restoreAnswer: function () {

                var yourAnswer,
                    answers;


                yourAnswer = this.question.get("yourAnswer");

                //TODO　複数入力の場合を考慮すること
                if (yourAnswer !== "") {

                    answers = yourAnswer.split("###");

                    $(answers).each(function (i, val) {
                        $(".questionBox :text").eq(i).val(val);
                    });

                }

            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.undelegateEvents();
            }
        });


    }
);
define('text!app/templates/questionbuilder/InsertionQuestionBuilder.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n    {{{title_html}}}\n    {{#direction}}\n    <div class="direction">{{{direction}}}</div>\n    {{/direction}}\n    <div class="insertionQuestionBox">\n        <div class="insertionQuestionBox_l">\n            <div class="clozeTestQuestion">{{{questionParsedString}}}</div>\n        </div>\n        <div class="insertionQuestionBox_r">\n            <div class="selectArea">\n                <div>\n                    <p>インサートする文</p>\n                    <ul>\n                        {{#sortStringList}}\n                        <li><span class="choice" ref="{{index}}">{{{text}}}</span></li>\n                        {{/sortStringList}}\n                    </ul>\n                </div>\n            </div>\n            <div style="display:none;">\n                <div id="insertionStringList">\n                    <p>インサートする文を選択してください。</p>\n                    <ul>\n                        {{#sortStringList}}\n                        <li><span class="choice" ref="{{index}}">{{{text}}}</span></li>\n                        {{/sortStringList}}\n                    </ul>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n';});

/*global require: false, define: false, Class: false */
define('app/questionbuilder/InsertionQuestionBuilder',
    [
        "jQuery",
        "app/questionbuilder/QuestionView",
        'text!app/templates/questionbuilder/InsertionQuestionBuilder.html'
    ],
    function (
        $,
        QuestionView,
        template
    ) {
        
        /**
         * InsertionQuestionBuilder
         *
         * @param {Object} el
         * @param {Object} question
         */
        return QuestionView.extend({

            selectedInsertionPostion: null,

            events: {
                "click .insertionQuestionBox_r .selectArea": "selectAreaClick",
                "click .insertionPosition": "insertionPositionClick"
            },
            /**
             *
             */
            _build: function () {

                var scope,
                    title_html,
                    html;

                scope = this;
                this.selectedInsertionPostion = null;

                title_html = this.getTitleHTML();


                html = $.mustache(
                    template,
                    $.extend({
                        title_html: title_html
                    }, this.question.toJSON())
                );

                this.$el.append(html);


                $("#insertionStringList li span").hover(
                    function () {
                        $(this).addClass("over");
                    },
                    function () {
                        $(this).removeClass("over");
                    }
                );

                $("#insertionStringList li span").click(function (e) {
                    scope.doAnswer(e);
                });

                //選択できないようにする
                this.$(".questionBox").disableTextSelect();

            },

            selectAreaClick : function (e) {
                e.stopPropagation();
            },
            insertionPositionClick : function (e) {
                this.selectedInsertionPostion = $(this);

                //フォーカスを解除する
                $("#insertionStringList li span").removeClass("current");
                //穴に段落番号が入っていたら、その段落にフォーカスする
                if (this.selectedInsertionPostion.attr("ref") !== "") {
                    $("#insertionStringList li span").filter("[ref='" + this.selectedInsertionPostion.attr("ref") + "']").addClass("current");
                }


                $.fancybox($("#insertionStringList"), {
                    'hideOnOverlayClick': true,
                    'type': 'inline',
                    'openEffect': 'none',
                    'closeEffect': 'none'
                });

                return false;
            },
            doAnswer: function (e) {


                var target,
                    isSameWord,
                    removeSelected,
                    target_insertionedPostion,
                    answers_str;

                //新しく、選択した段落
                target = $(e.currentTarget);

                isSameWord = (target.attr("ref") === this.selectedInsertionPostion.attr("ref"));


                //穴に段落番号が入っていたら、その段落の選択状態を解除する
                if (this.selectedInsertionPostion.attr("ref") !== "") {
                    //選択状態をクリアする
                    removeSelected = $("#insertionStringList li span").filter("[ref='" + this.selectedInsertionPostion.attr("ref") + "']");

                    removeSelected.removeClass("select");
                    //段落に使用中の穴を設定する
                    $.removeData(removeSelected.get(0), "InsertionQuestion_insertionPostion");
                }


                //使っている穴
                target_insertionedPostion = $.data(target.get(0), "InsertionQuestion_insertionPostion");

                if (target_insertionedPostion !== undefined) {

                    //使っている穴をクリアする
                    target_insertionedPostion.html("(　　　　　　　)");
                    target_insertionedPostion.attr("ref", "");


                }


                if (!isSameWord) {

                    //選択状態にする
                    target.addClass("select");

                    //段落番号をセットする
                    this.selectedInsertionPostion.attr("ref", target.attr("ref"));

                    this.selectedInsertionPostion.html(target.html());


                    //段落に使用中の穴を設定する
                    $.data(target.get(0), "InsertionQuestion_insertionPostion", this.selectedInsertionPostion);
                } else {

                    //同じものを選択すると、削除される
                    //使っている穴をクリアする
                    this.selectedInsertionPostion.html("(　　　　　　　)");
                    this.selectedInsertionPostion.attr("ref", "");
                }


                $.fancybox.close();



                answers_str = $(".insertionPosition").map(function () {
                    return $(this).attr("ref");
                }).get().join(",");

                if (this.question.get("yourAnswer") !== answers_str) {
                    this.question.setYourAnswer(answers_str);
                }

                this._fouceSelectArea();
            },
            _fouceSelectArea: function () {


                var yourAnswer,
                    answers;


                $(".selectArea li span").removeClass("select");

                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {

                    answers = yourAnswer.split(",");

                    $(answers).each(function (i, val) {
                        if (val === "") {
                            //空の場合はスキップ
                            return true;
                        }
                        $(".selectArea li span").filter("[ref='" + val + "']").addClass("select");

                    });
                }

            },
            _restoreAnswer: function () {

                var yourAnswer,
                    answers;

                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {

                    answers = yourAnswer.split(",");

                    $(answers).each(function (i, val) {

                        var word, postion;

                        if (val === "") {
                            //空の場合はスキップ
                            return true;
                        }


                        word = $("#insertionStringList li span").filter("[ref='" + val + "']");
                        //選択状態にする
                        word.addClass("select");

                        postion = $(".insertionPosition").eq(i);


                        //段落番号をセットする
                        postion.attr("ref", word.attr("ref"));
                        postion.html(word.html());


                        //段落に使用中の穴を設定する
                        $.data(word.get(0), "InsertionQuestion_insertionPostion", postion);


                    });
                }

                this._fouceSelectArea();
            },
            destroy: function () {
                QuestionView.prototype.destroy.apply(this, arguments);
                this.undelegateEvents();
                //this.el.undelegate("#insertionStringList li span", 'click');
            }


        });
    }
);
