/*global require: false, define: false, Class: false */
define('app/view/HeaderView',
    [
        "jQuery",
        "Backbone",
        "Marionette",
        'text!app/templates/header.html',
        'text!app/templates/header_sp.html'
    ],
    function (
        $,
        Backbone,
        Marionette,
        template,
        template_sp
    ) {
        
        return Marionette.ItemView.extend({

            events : {
                "click #nextButton" : "_onClickNextButton",
                "click #prevButton" : "_onClickPrevButton",
                "click #jampButton" : "_onClickJumpButton"
            },

            /** コントローラー */
            controller: null,

            ui: {
                closeWindowButton: "#closeWindowButton",
                startButton: "#startButton",
                quitButton: "#quitButton",
                jampButton: "#jampButton",
                prevButton: "#prevButton",
                nextButton: "#nextButton",
                confirmButton: "#confirmButton",
                reTryButton: "#reTryButton",
                //下書きボタン
                draftButton: "#draftButton"
            },

            /**
             * コンストラクタ
             */
            initialize: function (options) {



                this.controller = options.controller;
                this.controller.on("EVENT_SHOW_END_QUESTION", this.showEndQuestion, this);
                this.controller.on("EVENT_START_SHOW_END_PAGE", this.startShowEndPage, this);
                this.controller.on("EVENT_START_SEND_DATA", this.hideMenu, this);

            },
            render: function () {


                if (window.playerModel.get("isMobile")) {
                    template = template_sp;
                }

                this.$el.append($.mustache(template, {

                    startButton: $.global.culture.player.buttons.startButton,
                    jampButton: $.global.culture.player.buttons.jampButton,
                    quitButton: $.global.culture.player.buttons.quitButton,

                    prevButton: $.global.culture.player.buttons.prevButton,
                    nextButton: $.global.culture.player.buttons.nextButton,
                    reTryButton: $.global.culture.player.buttons.reTryButton,
                    confirmButton: $.global.culture.player.buttons.confirmButton

                }));

                /*
                    mobile以外はフルスクリーンモード機能を有効にする
                 */

                if (window.playerModel.get("isMobile") === false) {
                    this.initFullScreen();
                }

                this.bindUIElements();


                if (!(window.playerModel.get("previewType") === "combination" || window.playerModel.get("previewType") === "single")) {
                    this.setTitle(this.model.get("booktitle"));
                }

                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4 || window.playerModel.get("bookType") === 5) {
                    //アンケートモードの場合
                    //確認ボタンの文言を「採点」→「確認」に変更する
                    this.ui.confirmButton.text($.global.culture.player.buttons.confirmButton2);
                }

                this.ui.confirmButton.addClass("disabled");
                this.ui.confirmButton.click($.proxy(this._onClickConfirmButton, this));


                this.ui.prevButton.blur(function () {
                });
                this.ui.nextButton.blur(function () {
                });

                this.ui.prevButton.focus(function () {
                });
                this.ui.nextButton.focus(function () {
                });

                this.ui.prevButton.keypress(function (ev) {
                    return false;
                });
                this.ui.nextButton.keypress(function (ev) {
                    return false;
                });


                this.ui.draftButton.click($.proxy(this._onClickDraftButton, this));


                if (window.playerModel.get("visionary") === "ac2weeklydrill") {
                    this.ui.closeWindowButton.click(function (ev) {
                        ev.preventDefault();
                        window.location.href = window.playerModel.get("weeklyConfig").returnURL;
                    });
                }



                return this;
            },
            _onClickPrevButton: function (event) {
                event.preventDefault();
                if (!$(event.currentTarget).hasClass("disabled")) {
                    this.trigger("EVENT_CLICK_PREV_BUTTON");
                }
            },
            _onClickNextButton: function (event) {
                event.preventDefault();

                if (!$(event.currentTarget).hasClass("disabled")) {
                    this.trigger("EVENT_CLICK_NEXT_BUTTON");
                }
            },

            _onClickJumpButton: function (event) {
                event.preventDefault();


                if (!$(event.currentTarget).hasClass("disabled")) {
                    this.trigger("EVENT_CLICK_JUMP_BUTTON");
                }
            },


            _onClickConfirmButton: function (event) {
                event.preventDefault();

                if (!$(event.currentTarget).hasClass("disabled")) {
                    this.trigger("EVENT_CLICK_CONFIRM_BUTTON");
                }
            },

            _onClickDraftButton: function (event) {
                event.preventDefault();

                if (!$(event.currentTarget).hasClass("disabled")) {
                    this.trigger("EVENT_CLICK_DRAFT_BUTTON");
                }
            },
            /**
             * タイトルを設定する
             */
            setTitle: function (title) {

                var html, template;
                template = '{{title}}';

                html = $.mustache(template, {
                    title: title
                });

                this.$('.title').append(html);
            },
            /**
             *　現在の問題番号を表示する
             */
            setQuestionNumber: function (num) {

                var template, html;
                if (!(window.playerModel.get("previewType") === "combination" || window.playerModel.get("previewType") === "single")) {

                    template = ' {{now}} / {{total}}';
                    html = $.mustache(template, {
                        now: num,
                        total: this.model.get("questions").length
                    });

                    this.$("#questionNumberView").html(html);
                }

            },
            /**
             * 問題の表示が完了した。
             */
            showEndQuestion: function () {
                this.setQuestionNumber(this.model.get("currentQuestionNumber") + 1);



                if (window.playerModel.get("visionary") === "ac2weeklydrill") {

                    this.ui.closeWindowButton.show();
                }





                this.ui.prevButton.show();
                this.ui.nextButton.show();

                this.ui.confirmButton.show();


                if (!window.playerModel.get("isPreview") && (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4)) {
                    //プレビューではなく、アンケートモードの場合
                    this.ui.draftButton.show();
                }


                var scope = this;

                if (window.playerModel.get("bookType") === 5) {
                    //自己採点モードは、１問のみなのでボタンを隠す
                    this.ui.prevButton.hide();
                    this.ui.nextButton.hide();
                    this.ui.jampButton.hide();
                    this.ui.confirmButton.hide();
                    this.$("#questionNumberView").hide();

                    // TODO あとで修正すること
                    window.sendWritingAnswer  = function () {
                        scope.trigger("EVENT_CLICK_CONFIRM_BUTTON");
                    };

                } else {

                    if (this.model.get("currentQuestionNumber") === 0) {
                        this.ui.prevButton.addClass("disabled");
                    } else {
                        this.ui.prevButton.removeClass("disabled");
                    }

                    if (this.model.isLastQuestion()) {
                        this.ui.confirmButton.removeClass("disabled");

                        this.ui.nextButton.addClass("disabled");
                    } else {
                        this.ui.nextButton.removeClass("disabled");
                    }
                }




            },


            hideMenu: function () {

                this.$("#questionNumberView").hide();

                this.ui.jampButton.hide();

                this.ui.prevButton.hide();
                this.ui.nextButton.hide();
                this.ui.confirmButton.hide();
                this.ui.draftButton.hide();
            },

            /**
             * 最後の画面の表示が始まった
             */
            startShowEndPage: function () {


                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4 || window.playerModel.get("bookType") === 5) {
                    //TODO なぜか空白ができるので、一度表示して、非表示にする
                    this.ui.reTryButton.show();
                    this.ui.reTryButton.css("visibility", "hidden");
                } else {
                    this.ui.reTryButton.show();

                    if (window.playerModel.get("previewType") === "assign_vc" && window.playerModel.get("visionary") === "vcet") {
                        //vcetの場合はリトライボタンを非表示にする
                        this.ui.reTryButton.css("visibility", "hidden");
                    } else {
                        this.ui.reTryButton.click(function (e) {
                            e.preventDefault();
                            location.reload();
                        });
                    }
                }
            },

            initFullScreen: function () {


                this.ui.fullScreenButton = "#fullScreenButton";
                this.bindUIElements();

                this.inFullScreen = false; // flag to show when full screen

                this.ui.fullScreenButton.click($.proxy(this._onClickFullScreenButton, this));


            },
            _onClickFullScreenButton: function (event) {
                event.preventDefault();

                var $target = $("body");

                if (this.inFullScreen === false) {
                    this.makeFullScreen($target.get()[0]); // open to full screen
                } else {
                    this.resetFullScreen();
                }

            },
            makeFullScreen : function (divObj) {
                if (divObj.requestFullscreen) {
                    divObj.requestFullscreen();
                } else if (divObj.msRequestFullscreen) {
                    divObj.msRequestFullscreen();
                } else if (divObj.mozRequestFullScreen) {
                    divObj.mozRequestFullScreen();
                } else if (divObj.webkitRequestFullscreen) {
                    divObj.webkitRequestFullscreen();
                }
                this.inFullScreen = true;
                return;
            },

            resetFullScreen: function () {
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                } else if (document.msExitFullscreen) {
                    document.msExitFullscreen();
                } else if (document.mozCancelFullScreen) {
                    document.mozCancelFullScreen();
                } else if (document.webkitCancelFullScreen) {
                    document.webkitCancelFullScreen();
                }
                this.inFullScreen = false;
                return;
            }



        });
    }
);
