/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/MultipleChoiceDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/MultipleChoiceDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * MultipleChoiceDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {

                var html = $.mustache(template, this.question.toJSON());

                this.$el.append(html);

                // 言語設定をする
                this.$(".question span").each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });

            },
            _restoreAnswer: function () {

                var rightAnser,
                    yourAnswer,
                    youranswerClass;


                rightAnser = this.question.get("answers");
                yourAnswer = this.question.get("yourAnswer");

                console.log(this.question);
                console.log("正誤判定：：" + rightAnser + ":" + yourAnswer);

                this.$(".choices li").filter("[ref='" + rightAnser + "']").addClass("rightAnswer").append('<span class="lang-ja" lang="ja">(正解)</span>');



                if (yourAnswer !== "") {
                    youranswerClass = "";
                    // ここが配列なので、yourAnswerと===で比較すると、すべて不正解になる。
                    if (rightAnser.toString() === yourAnswer) {
                        youranswerClass = "yourAnswerOK";
                    } else {
                        youranswerClass = "yourAnswerNG";
                    }

                    this.$(".choices li").filter("[ref='" + yourAnswer + "']").addClass(youranswerClass).append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');

                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');
                }


            }


        });


    }
);

