/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/UnderLineChoiceDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/UnderLineChoiceDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * UnderLineChoiceDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {
                //[**]を[]に変換する
                this.question.set("questionParsedString", this.question.get("question").replace(/\[\*([\s\S]+?)\*\]/gm, '[$1]'));
                this.question.set("questionParsedString", this.question.get("questionParsedString").replace(/\[([\s\S]+?)\]/gm, '<span class="d_underLinePoint"><span>$1</span></span>'));

                var html = $.mustache(template, this.question.toJSON());
                this.$el.append(html);


                // 言語設定をする
                this.$(".question span").each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });

            },
            _restoreAnswer: function () {

                var yourAnswer,
                    yourAnswerText;

                yourAnswer = this.question.get("yourAnswer");


                yourAnswerText = "";
                if (this.question.get("answers") === yourAnswer) {
                    yourAnswerText = "(あなたの解答)";
                }

                this.$(".descriptionArea").append("<div>(正解)" + yourAnswerText + "</div>");

                this.$(".descriptionArea").append(
                    $.mustache('<div class="lang-{{lang}}" lang="{{lang}}">{{{questionParsedString}}}</div>', this.question)

                );

                this.$(".descriptionArea span.d_underLinePoint span").eq(this.question.get("answers") - 1).addClass("rightAnswer");

                if (this.question.get("answers") === yourAnswer) {
                    this.$(".descriptionArea span.d_underLinePoint span").eq(this.question.get("answers") - 1).addClass("yourAnswerOK");
                }

                //TODO　複数入力の場合を考慮すること
                if (yourAnswer !== "") {

                    if (this.question.checkAnswer().judges === false) {
                        this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');
                        this.$(".descriptionArea").append(

                            $.mustache('<div class="ya lang-{{lang}}" lang="{{lang}}">{{{questionParsedString}}}</div>', this.question)

                        );

                        this.$(".descriptionArea .ya span.d_underLinePoint span").eq(yourAnswer - 1).addClass("yourAnswerNG");
                    }

                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');

                }

                // 言語設定をする
                this.$("span").each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });


            }

        });
    }
);


