/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/AnaumeFilInDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/AnaumeFilInDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * AnaumeFilInDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            template: template,
            tagName: "div",
            className: "questionBox",
            _build: function () {
                this.question.set("questionParsedString",  this.question.get("question").replace(/\[[\s\S]+?\]/gm, '(<span class="inputArea">　　　　　　</span>)'));

                var html = $.mustache(this.template, this.question.toJSON());

                this.$el.append(html);

            },
            _restoreAnswer: function () {

                var scope,
                    answer1,
                    answer2,
                    yourAnswer,
                    yourAnswerWordList,
                    current_AnswerWord_count,
                    temp;

                scope = this;

                if (this.question.get("initialLetterShown")) {

                    answer1 = this.question.get("answers")[0];
                    answer2 = answer1.split("/");
                    $(answer2).each(function (i, val) {
                        scope.$(".inputArea").eq(i).html(val.charAt(0) + scope.$(".inputArea").eq(i).html());
                    });
                }


                yourAnswer = this.question.get("yourAnswer");
                yourAnswerWordList = yourAnswer.split("###");

                $(this.question.get("answers")).each(function (i, val) {

                    var yourAnswerText,
                        yourAnswerClass,
                        answerWords,
                        current_words_count,
                        temp;

                    //１つの正答の単語リスト
                    answerWords = val.split("/");

                    yourAnswerText = "";
                    yourAnswerClass = "";
                    //$.logger.debug(val.toUpperCase() +"::::"+ yourAnswerWordList.join("/").toUpperCase());
                    if (val.toUpperCase() === yourAnswerWordList.join("/").toUpperCase()) {
                        yourAnswerText = "(あなたの解答)";
                        yourAnswerClass = " yourAnswerOK";
                    }


                    scope.$(".descriptionArea").append("<div>(" + "正解" + (i + 1) + ")" + yourAnswerText + "</div>");

                    //現在の単語の位置
                    current_words_count = -1;
                    temp = scope.question.get("question").replace(/\[[\s\S]+?\]/gm, function (word, $1) {
                        current_words_count++;
                        return '<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + answerWords[current_words_count] + '</span>';
                    });

                    //var temp = scope.question.question.replace(/\[[\s\S]+?\]/gm, '<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + val + '</span>');


                    scope.$(".descriptionArea").append("<div>" + temp + "</div>");

                });


                //TODO　複数入力の場合を考慮すること
                if (yourAnswer !== "") {

                    if (this.question.checkAnswer().judges === false) {
                        this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');


                        //現在の単語の位置
                        current_AnswerWord_count = -1;
                        temp = this.question.get("question").replace(/\[[\s\S]+?\]/gm, function (word, $1) {
                            current_AnswerWord_count++;
                            return '<span class="inputAreaRightAnswer yourAnswerNG">' + yourAnswerWordList[current_AnswerWord_count] + '</span>';
                        });


                        //var temp = scope.question.question.replace(/\[[\s\S]+?\]/gm, '<span class="inputAreaRightAnswer yourAnswerNG">' + yourAnswer + '</span>');
                        this.$(".descriptionArea").append("<div>" + temp + "</div>");
                    }

                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');

                }


            }


        });


    }
);



define('text!app/templates/descriptionbuilder/SortingADescription.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n\n<div class="questionTitle"><span class="questionNumber">{{questionNumber}}</span>: {{title}}</div>\n{{#direction}}\n<div class="direction">{{{direction}}}</div>\n{{/direction}}\n<div class="question sorting_description_question lang-{{lang}}" lang="{{lang}}">{{{question}}}</div>\n{{#sound}}\n<div class="sound" id="audioplayer_{{questionNumber}}" ref="{{sound}}">\n    <audio controls autobuffer src="{{sound}}"></audio>\n</div>\n{{/sound}}\n{{#image}}\n<div><img src="{{image}}"/></div>\n{{/image}}\n<div class="descriptionArea"></div>\n';});

/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/SortingADescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/SortingADescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * SortingADescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {

                var html = $.mustache(template, this.question.toJSON());

                this.$el.append(html);

            },
            _restoreAnswer: function () {

                var yourAnswers,
                    yourAnswerText,
                    yourAnswerClass,
                    temp;

                yourAnswers = this.question.get("yourAnswer").split("###").join(" ");


                yourAnswerText = "";
                yourAnswerClass = "";
                if (this.question.get("answers") === yourAnswers) {
                    yourAnswerText = "(あなたの解答)";
                    yourAnswerClass = " yourAnswerOK";
                }

                this.$(".descriptionArea").append("<div>(正解)" + yourAnswerText + "</div>");
                temp = this.question.get("question").replace(/\[[\s\S]+\]/m, '<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers") + '</span>');

                this.$(".descriptionArea").append($.mustache('<div class="lang-{{lang}}" lang="{{lang}}">{{{temp}}}</div>', {
                    temp: temp,
                    lang: this.question.get("lang")
                }));


                //TODO　複数入力の場合を考慮すること
                if (yourAnswers !== "") {

                    if (this.question.checkAnswer().judges === false) {
                        this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');
                        temp = this.question.get("question").replace(/\[[\s\S]+\]/m, '<span class="inputAreaRightAnswer yourAnswerNG">' + yourAnswers + '</span>');

                        this.$(".descriptionArea").append($.mustache('<div class="lang-{{lang}}" lang="{{lang}}">{{{temp}}}</div>', {
                            temp: temp,
                            lang: this.lang
                        }));
                    }

                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');

                }


                // 言語設定をする
                this.$("span").each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });


            }


        });

    }
);


