/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/MultipleCorrectDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/MultipleCorrectDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * MultipleCorrectDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {

                var html = $.mustache(template, this.question.toJSON());

                this.$el.append(html);

                // 言語設定をする
                this.$(".question span").each(function (i, val) {
                    var lang = $(this).attr("lang");
                    if (lang) {
                        $(this).addClass("lang-" + lang);
                    }
                });

            },
            _restoreAnswer: function () {


                var scope,
                    yourAnswer,
                    yourAnswers,
                    youranswerClass;

                scope = this;

                $(this.question.get("answers")).each(function (i, val) {
                    scope.$(".choices li").filter("[ref='" + val + "']").addClass("rightAnswer").append('<span class="lang-ja" lang="ja">(正解)</span>');
                });


                yourAnswer = this.question.get("yourAnswer");

                if (yourAnswer !== "") {

                    yourAnswers = yourAnswer.split(",");


                    $(yourAnswers).each(function (i, val) {


                        youranswerClass = "yourAnswerNG";

                        $(scope.question.get("answers")).each(function (i2, val2) {

                            if (val === val2) {
                                youranswerClass = "yourAnswerOK";
                            }

                        });

                        scope.$(".choices li").filter("[ref='" + val + "']").addClass(youranswerClass).append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');

                    });

                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');
                }


            }

        });


    }
);

define('text!app/templates/descriptionbuilder/ClozeTestDescription.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n\n<div class="questionTitle"><span class="questionNumber">{{questionNumber}}</span>: {{title}}</div>\n{{#direction}}\n<div class="direction">{{{direction}}}</div>\n{{/direction}}\n{{#sound}}\n<div class="sound" id="description_audioplayer_{{questionNumber}}" ref="{{sound}}">\n    <audio controls autobuffer src="{{sound}}"></audio>\n</div>\n{{/sound}}\n{{#image}}\n<div><img src="{{image}}"/></div>\n{{/image}}\n<div class="descriptionArea"></div>\n\n';});

/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/ClozeTestDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/ClozeTestDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * ClozeTestDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {
                var html = $.mustache(template, this.question.toJSON());
                this.$el.append(html);
            },
            _restoreAnswer: function () {

                var yourAnswer,
                    temp,
                    temp2,
                    answers;

                yourAnswer = this.question.get("yourAnswer");

                this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(正答)</div>');

                temp = this.question.get("question").replace(/\[([\s\S]+?)\]/gm, function (word, $1) {
                    return '(<span class="inputAreaRightAnswer">' + $1 + '</span>)';
                });


                this.$(".descriptionArea").append('<div class="clozeTestQuestion">' + temp + "</div>");


                if (yourAnswer !== "") {

                    this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');


                    temp2 = this.question.get("question").replace(/\[([\s\S]+?)\]/gm, function (word, $1) {
                        return '(<span class="inputAreaRightAnswer yourAnswer"></span>)';
                    });


                    this.$(".descriptionArea").append('<div class="clozeTestQuestion">' + temp2 + "</div>");

                    answers = this.question.checkAnswer().resultData;

                    $.logger.debug(answers);



                    $(answers).each(function (i, val) {

                        var answerText = "";

                        if (val.yourAnswer === "") {
                            //未解答の場合
                            answerText = '<img src="images/batu_icon_s.png">' + "未解答" + '（<span class="yourAnswerNG">' + val.rightAnswer + '</span>）';
                        } else {

                            if (val.judge) {
                                //正解の場合
                                answerText = '<img src="images/maru_icon_s.png">' + val.yourAnswer;
                            } else {
                                //不正解の場合
                                answerText = '<img src="images/batu_icon_s.png">' + val.yourAnswer + '（<span class="yourAnswerNG">' + val.rightAnswer + '</span>）';
                            }


                        }

                        this.$(".yourAnswer").eq(i).html(answerText);

                    });


                } else {
                    this.$el.append('<div class="noAnswer">（未解答）</div>');
                }


            }

        });


    }
);

