define('app/descriptionbuilder/DictationTypingDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/DictationTypingDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * AnaumeFilInDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {
                this.question.set(
                    "questionParsedString",
                    this.question.get("question").replace(/\[[\s\S]+?\]/gm, '(<span class="inputArea">　　　　　　</span>)')
                );

                var html = $.mustache(template, this.question.toJSON());

                this.$el.append(html);

            },

            _restoreAnswer: function () {

                var yourAnswer,
                    yourAnswerWordList,
                    scope,
                    current_AnswerWord_count,
                    temp;

                scope = this;



                yourAnswer = this.question.get("yourAnswer");









                var yourAnswerText, yourAnswerClass, current_words_count, temp;





                //TODO　複数入力の場合を考慮すること
                if (yourAnswer !== "") {


                    if(this.question.checkAnswer().judges === true){

                        yourAnswerClass = " yourAnswerOK";
                        if(this.question.get("answers").length > 1){

                            scope.$(".descriptionArea").append("<div>(" + "正解" + ")" + "(あなたの解答)" + "</div>");
                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers").join("<br />") + '</span>';
                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");
                        }else{

                            scope.$(".descriptionArea").append("<div>(" + "正解" + ")" + "(あなたの解答)" + "</div>");
                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers") + '</span>';
                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");
                        }

                    }else{

                        yourAnswerClass = " yourAnswerNG";
                        if(this.question.get("answers").length > 1){

                            scope.$(".descriptionArea").append("<div>(" + "正解" + ")" + "</div>");
                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers").join("<br />") + '</span>';
                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");


                            scope.$(".descriptionArea").append("<div>(" + "あなたの解答" + ")" + "</div>");

                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">';

                            if(yourAnswer.split("###").length === 1){
                                temp += yourAnswer;
                            }else{
                                temp += yourAnswer.split("###")[0];
                                temp += "<br />";
                                temp += yourAnswer.split("###")[1];
                            }


                            temp +='</span>';

                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");

                        }else{

                            scope.$(".descriptionArea").append("<div>(" + "正解" + ")" + "</div>");
                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers") + '</span>';
                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");


                            scope.$(".descriptionArea").append("<div>(" + "あなたの解答" + ")" + "</div>");
                            temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + yourAnswer + '</span>';
                            scope.$(".descriptionArea").append("<div>" + temp + "</div>");


                        }







                    }











                } else {


                    yourAnswerClass = " yourAnswerNG";
                    if(this.question.get("answers").length > 1){

                        scope.$(".descriptionArea").append("<div>(" + "正解" + ")" + "</div>");
                        temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers").join("<br />") + '</span>';
                        scope.$(".descriptionArea").append("<div>" + temp + "</div>");
                    }else{

                        scope.$(".descriptionArea").append("<div>(" + "正解" + ")"  + "</div>");
                        temp ='<span class="inputAreaRightAnswer' + yourAnswerClass + '">' + this.question.get("answers") + '</span>';
                        scope.$(".descriptionArea").append("<div>" + temp + "</div>");
                    }



                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');

                }


            }


        });


    }
);



