/*global require: false, define: false, Class: false */
define('app/descriptionbuilder/MatchingWordDescription',
    [
        "jQuery",
        "app/descriptionbuilder/DescriptionBuilder",
        'text!app/templates/descriptionbuilder/MatchingWordDescription.html'
    ],
    function (
        $,
        DescriptionBuilder,
        template
    ) {
        
        /**
         * InsertionDescription
         *
         * @param {Object} question
         */
        return DescriptionBuilder.extend({
            tagName: "div",
            className: "questionBox",
            _build: function () {
                var html = $.mustache(template, this.question.toJSON());
                this.$el.append(html);
            },
            _restoreAnswer: function () {

                var yourAnswer,
                    table,
                    table2,
                    answers,
                    scorp;

                scorp = this;
                yourAnswer = this.question.get("yourAnswer");

                this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(正答)</div>');

                table = this._createRightAnswerTable();

                this.$(".descriptionArea").append(table);


                if (yourAnswer !== "") {
                    this.$(".descriptionArea").append('<div class="lang-ja" lang="ja">(あなたの解答)</div>');


                    table2 = this._createYourAnswerTable();

                    this.$(".descriptionArea").append(table2);

                    answers = this.question.checkAnswer().resultData;

                    $.logger.debug(answers);



                    $(answers).each(function (i, val) {

                        var answerText = "";

                        if (val.yourAnswer === "") {
                            //未解答の場合
                            answerText = '<img src="images/batu_icon_s.png">' + "未解答" + '（<span class="yourAnswerNG">' + scorp.question.get("noSortStringList")[val.rightAnswer] + '</span>）';
                        } else {

                            if (val.judge) {
                                //正解の場合
                                answerText = '<img src="images/maru_icon_s.png">' + scorp.question.get("noSortStringList")[val.yourAnswer];
                            } else {
                                //不正解の場合
                                answerText = '<img src="images/batu_icon_s.png">' + scorp.question.get("noSortStringList")[val.yourAnswer] + '（<span class="yourAnswerNG">' + scorp.question.get("noSortStringList")[val.rightAnswer] + '</span>）';
                            }


                        }

                        scorp.$(".yourAnswer").eq(i).html(answerText);


                    });


                } else {
                    this.$el.append('<div class="noAnswer lang-ja" lang="ja">（未解答）</div>');
                }


            },
            /**
             * （正答）を作る
             */
            _createRightAnswerTable: function () {


                var temp, scope;

                temp = $('<div class="clozeTestQuestion">' + this.question.get("questionParsedString") + "</div>");

                scope = this;

                $(".insertionPosition", temp).each(function (i, val) {
                    $(this).removeClass("insertionPosition").addClass("inputAreaRightAnswer");
                    $(this).html(scope.question.get("noSortStringList")[i]);
                });

                return temp;
            },
            _createYourAnswerTable: function () {

                var temp = $('<div class="clozeTestQuestion">' + this.question.get("questionParsedString") + "</div>");

                $(".insertionPosition", temp).each(function (i, val) {
                    $(this).removeClass("insertionPosition").addClass("inputAreaRightAnswer yourAnswer");
                });

                return temp;
            }
        });


    }
);

