/*global require: false, define: false, Class: false */
define('app/view/DescriptionBoxView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        "app/CombinationQuestion",
        "app/view/DescriptionIndexView",
        "app/view/DescriptionIndexViewMobile",
        "app/descriptionbuilder/DescriptionViewBuilder",
        'text!app/templates/descriptionBoxCombinationQuestion.html',
        'text!app/templates/descriptionBox.html',
        'text!app/templates/descriptionBoxRaw.html'
    ],
    function (
        $,
        AbstractBackbornView,
        CombinationQuestion,
        DescriptionIndexView,
        DescriptionIndexViewMobile,
        DescriptionViewBuilder,
        descriptionBoxCombinationQuestionTemplates,
        descriptionBoxHeaderTemplate,
        descriptionBoxRawTemplate
    ) {
        
        return AbstractBackbornView.extend({

            className: "descriptionBox",

            events : {
                "click .goDescriptionButton": "clickGoDescription"
            },

            render: function () {
                this.createDescriptionBox();
                return this;
            },
            clickGoDescription: function (e) {
                if (!window.playerModel.get("isMobile")) {
                    e.preventDefault();
                    var num = $(e.currentTarget).attr("ref");

                    this.trigger("clickGoDescriptionButton", [num]);
                }
            },
            /**
             * 解説を作成する
             */
            createDescriptionBox: function () {

                var scope,
                    answer,
                    descriptionIndexView,
                    descriptionsTableRows,
                    descriptionsTable;

                scope = this;

                answer = this.model.getAnswers();


                if (window.playerModel.get("isMobile")) {
                    descriptionIndexView = new DescriptionIndexViewMobile({el: this.$el, view: answer});
                } else {
                    descriptionIndexView = new DescriptionIndexView({el: this.$el, view: answer});
                }
                descriptionIndexView.render();

                descriptionsTableRows = "";

                $(this.model.get("bookIndex")).each(function (i, val) {


                    var childhtml;


                    if (val instanceof CombinationQuestion) {

                        childhtml = $.mustache(descriptionBoxCombinationQuestionTemplates, val.toJSON());

                        descriptionsTableRows += childhtml;

                        $(val.get("questions")).each(function (i2, val2) {

                            childhtml = scope.getDescriptionTableRowHtml(val2);
                            descriptionsTableRows += childhtml;

                        });

                    } else {

                        childhtml = scope.getDescriptionTableRowHtml(val);
                        descriptionsTableRows += childhtml;


                    }

                });

                descriptionsTable = $.mustache(descriptionBoxHeaderTemplate, {descriptionsTableRows: descriptionsTableRows});
                this.$el.append(descriptionsTable);

                //選択できないようにする
                this.$el.disableTextSelect();

            },
            getDescriptionTableRowHtml: function (question) {
                var view,
                    html;

                view = this.getDescriptionTableRowViewForQuestion(question);

                html = $.mustache(descriptionBoxRawTemplate, view);

                return html;
            },
            getDescriptionTableRowViewForQuestion: function (question) {


                var description = {
                    number: 0,
                    description: "",
                    judgeMark: "",
                    html: "",
                    descriptionView : null
                };

                description.number = question.get("questionNumber");
                description.description = question.get("description");


                if (question.checkAnswer().correct_flag === 1) {
                    description.judgeMark = '<span class="maru"><img src="images/maru_icon.png"/></span>';
                } else if (question.checkAnswer().correct_flag === 2) {
                    description.judgeMark = '<span class="sankaku"><img src="images/sankaku_icon.png"/></span>';
                } else {
                    description.judgeMark = '<span class="batu"><img src="images/batu_icon.png"/></span>';
                }

                description.descriptionView = DescriptionViewBuilder.build(question);
                description.html = description.descriptionView.$el.html();

                description.html = description.descriptionView.$el.get(0).outerHTML;




                return description;
            }

        });
    }
);
