/*global require: false, define: false, Class: false */
define('app/BuildDataObject',
    [
        "Backbone"
    ],
    function (
        Backbone
    ) {
        

        return Backbone.Model.extend({

            defaults: {
                /** 次の問題 */
                next: null,

                /** 前の問題 */
                old: null,

                /** 描画ターゲット */
                target: null
            },

            /**
             * コンストラクタ
             */
            initialize: function () {
                //

            },
            /**
             * 次の問題が複合問題かどうか？
             */
            isNextCombination: function () {


                var ret = false;

                if (this.get("next") === null) {
                    ret = false;
                } else {

                    ret = this.get("next").isCombinationQuestion();

                }

                return ret;
            },
            /**
             * 前の問題が複合問題かどうか？
             */
            isOldCombination: function () {

                var ret = false;

                if (this.get("old") === null) {
                    ret = false;
                } else {
                    ret = this.get("old").isCombinationQuestion();
                }

                return ret;
            },
            /**
             * 前の問題と、次の問題が同じかどうか？
             */
            isSameCombination: function () {

                return (this.get("old").get("combinationId") === this.get("next").get("combinationId"));
            }

        });
    }
);
/*global require: false, define: false, Class: false */
define('app/QuestionController',[
    "jQuery",
    "Backbone",
    "Marionette",
    "app/PageLayout",
    "app/PageManager",
    "app/view/StartPageView",
    "app/view/SimpleStartPageView",
    "app/view/BookIndexView",
    "app/view/ScoreView",
    "app/view/JudgementView",
    "app/view/SendingAnswerView",
    "app/view/SendingWritingAnswerView",
    "app/view/BookPreviewScoreView",
    "app/view/CombinationQuestionView",
    "app/view/TestModeListeningCombinationQuestionView",
    "app/view/SpeedReadingCombinationQuestionView",
    "app/view/CountDownTimerView",
    "app/CombinationQuestion",
    "app/questionbuilder/QuestionViewBuilder",
    "app/view/MainView",
    "app/view/HeaderView",
    "app/view/FooterView",
    "app/view/FooterMenuView",
    "app/view/DescriptionBoxView",
    "app/BuildDataObject"
],
    function (
        $,
        Backbone,
        Marionette,
        PageLayout,
        PageManager,
        StartPageView,
        SimpleStartPageView,
        BookIndexView,
        ScoreView,
        JudgementView,
        SendingAnswerView,
        SendingWritingAnswerView,
        BookPreviewScoreView,
        CombinationQuestionView,
        TestModeListeningCombinationQuestionView,
        SpeedReadingCombinationQuestionView,
        CountDownTimerView,
        CombinationQuestion,
        QuestionViewBuilder,
        MainView,
        HeaderView,
        FooterView,
        FooterMenuView,
        DescriptionBoxView,
        BuildDataObject
    ) {
        
        /**
         * QuestionController
         */
        return Marionette.ItemView.extend({

            pageLayout: null,

            pageManager: null,
            /** スタートページ */
            startPage : null,

            /** iscroll用 */
            bookIndexScroll : null,
            iScrollBar: null,
            timerViewer : null,

            //次の問題作成に必要なデータ
            nextBuildQuestionData: null,

            __lockControllFlag: false,

            /** ヘッダービュー */
            headerArea: null,

            /** フッタービュー */
            footerArea: null,

            /** メインエリア */
            mainArea: null,

            /** 目次 */
            bookIndex: null,

            isStart: false,

            ui: {
                startButton: "#startButton",
                quitButton : "#quitButton"
            },

            /*
             EVENT
             */

            events: {
                "click #startButton": "_onClickStartButton",
                "click #quitButton": "_onClickQuitButton"
            },

            /**
             * コンストラクタ
             *
             * @param options
             */
            initialize : function (options) {

                this.listenTo(this.model, '/Question/doAnswered', this.doAnswered);

                this.listenTo(this.model, '/QuestionModel/sendStart', this._onSendStart);
                this.listenTo(this.model, '/QuestionModel/changeQuestion', this._onChangeQuestion);
                this.listenTo(this.model, '/QuestionModel/endQuestion', this._onSendEndQuestion);


                this.pageManager = new PageManager();
            },

            render: function () {

                this.pageLayout = new PageLayout();

                // 空のView
                this.mainArea = new MainView({
                    el: this.$("#main"),
                    model: this.model
                });

                this.headerArea = new HeaderView({
                    el: this.$("#header"),
                    controller: this,
                    model: this.model
                });

                if (window.playerModel.get("isShowFooterMenu")) {

                    this.$("#footer").addClass("showFooterMenu");

                    this.footerArea = new FooterMenuView({
                        el: this.$("#footer"),
                        controller: this,
                        model: this.model
                    });
                } else {
                    this.footerArea = new FooterView({
                        el: this.$("#footer")
                    });
                }

                this.pageLayout.mainArea.show(this.mainArea);
                this.pageLayout.headerArea.show(this.headerArea);
                this.pageLayout.footerArea.show(this.footerArea);

                this.bindUIElements();

                if (window.playerModel.isViewStartPage()) {
                    this._buildStartBox();
                } else {
                    this._buildNoStartBox();
                }

                return this;
            },



            /**
             * 画面の高さを設定する
             */
            _setStageHeight: function () {

                var headerH,
                    footerH,
                    wrapperH,
                    combinationHeaderH;

                headerH = this.headerArea.$el.height();
                footerH = this.footerArea.$el.height();

                wrapperH = $(window).height() - headerH - footerH;
                this.mainArea.$el.css("height", wrapperH + 'px');

                console.log("setStageHeight:" + wrapperH);

                //複数問題の場合
                if (this.$('.combinationHeader').length > 0) {
                    //ボーダー分たす
                    combinationHeaderH = this.$el.find('.combinationHeader').innerHeight() + 1;
                    this.$('.passageWraper').css("height", (wrapperH - combinationHeaderH) + 'px');
                }

                if (this.startPage !== null) {
                    if (window.playerModel.get("isMobile")) {
                        //パディング分引く
                        $('.startBoxMain .bookindex .wrapper').css("height", wrapperH - 10 * 2 + 'px');
                    } else {
                        //パディング分引く
                        $('.startBoxMain .bookindex .wrapper').css("height", wrapperH - 30 * 2 - 100 * 2 + 'px');
                    }
                }

            },

            /**
             * windowのリサイズ時のイベントを設定する
             */
            setResizeWindowEvent: function () {
                $(window).bind(window.onorientationchange ? 'orientationchange' : 'resize', $.proxy(this._refreseWindow, this));
            },

            /**
             * スタート画面無しでスタートする
             */
            _buildNoStartBox: function () {

                this._refreseWindow();
                this.setResizeWindowEvent();

                this._buildQuestionContainaer();

            },

            /**
             * スタート画面を表示する
             */
            _buildStartBox: function () {

                if (window.playerModel.get("coverview") === "cover") {
                    // 通常のスタート画面
                    this.startPage = new StartPageView({model: this.model});
                    this.startPage.render();
                    this.mainArea.$el.append(this.startPage.el);
                    this.ui.startButton.show();
                } else {
                    //画像用のスタート画面
                    this.startPage = new SimpleStartPageView({model: this.model});
                    this.startPage.render();
                    this.$el.append(this.startPage.el);
                }



                this.show();

                this._refreseWindow();
                this.setResizeWindowEvent();

                /*
                 * Ipad　の場合はiScrollをセットする
                 */
                if (window.playerModel.get("isUseIScroll")) {
                    var myScroll, myScroll2;

                    myScroll = new window.iScroll('startBox');
                    myScroll2 = new window.iScroll('scroller');
                }
            },
            _refreseWindow : function () {

                if (!window.playerModel.get("isUseIScroll") && window.playerModel.get("isMobile")) {
                    $.logger.debug("何もしない");
                } else {
                    this._setStageHeight();
                }
            },
            /**
             * スタートボタンをクリックしたら
             * @param {Object} e
             */
            _onClickStartButton: function (event) {
                event.preventDefault();

                if (this.isStart) {
                    return;
                }
                this.isStart = true;
                this.unbind('.delegateEvents');
                if (!window.playerModel.get("isPreview")) {
                    //スタートを送信
                    this.model.sendStart();
                } else {
                    this._onSendStart();
                }
            },

            /**
             * スタート送信完了
             */
            _onSendStart: function (model, value) {

                if (!window.playerModel.get("isPreview")) {
                    //回答を保存した場合等、親Windowを更新するフラグをセットする（テストの場合）
                    this.model.set("isStart", true);


                    if (window.parent !== null && window.parent.customizedTrainingOnStart) {
                        window.parent.customizedTrainingOnStart();
                    }


                } else {
                    /*
                     * プレビューの場合
                     */
                    this.model.set("isStart", true);
                    this.model.set("isEndDril", true);
                }


                this.$el.fadeOut("slow", $.proxy(this._buildQuestionContainaer, this));




            },

            /**
             * 問題画面を作る
             */
            _buildQuestionContainaer: function () {

                if (this.startPage !== null) {
                    this.startPage.remove();
                    this.startPage = null;
                }

                this.mainArea.clear();

                if (
                    window.playerModel.get("previewType") !== "combination"
                         && window.playerModel.get("previewType") !== "single"
                ) {
                    this._buildJumpMenuBar();
                }

                this._buildControllButtons();

                this.startQuestion();

                this.show();

            },

            show: function () {
                this.$el.fadeIn("slow");
            },

            _buildControllButtons: function () {

                this.ui.startButton.hide();

                this._buildHeaderControllButtons();

                if (window.playerModel.get("isShowFooterMenu")) {
                    this._buildFooterControllButtons();
                }

            },
            _buildHeaderControllButtons: function () {

                this.headerArea.on("EVENT_CLICK_PREV_BUTTON", this.prevQuestion, this);
                this.headerArea.on("EVENT_CLICK_NEXT_BUTTON", this.nextQuestion, this);
                this.headerArea.on("EVENT_CLICK_DRAFT_BUTTON", this.draftQuestion, this);

                this.headerArea.on("EVENT_CLICK_JUMP_BUTTON", this._showJumpButton, this);


                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4) {
                    //アンケートモードの場合
                    this.headerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._showConfirm, this);

                } else if (window.playerModel.get("bookType") === 5) {
                    //自己採点モードの場合
                    this.headerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._showWritinfShowConfirm, this);

                } else {
                    this.headerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._onClickConfirmButton, this);
                }
            },
            _buildFooterControllButtons: function () {


                this.footerArea.on("EVENT_CLICK_PREV_BUTTON", this.prevQuestion, this);
                this.footerArea.on("EVENT_CLICK_NEXT_BUTTON", this.nextQuestion, this);
                this.footerArea.on("EVENT_CLICK_JUMP_BUTTON", this._showJumpButton, this);

                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4) {
                    //アンケートモードの場合
                    this.footerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._showConfirm, this);

                } else if (window.playerModel.get("bookType") === 5) {
                    //自己採点モードの場合
                    this.footerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._showWritinfShowConfirm, this);

                } else {
                    this.footerArea.on("EVENT_CLICK_CONFIRM_BUTTON", this._onClickConfirmButton, this);
                }
            },
            /**
             * 確認画面を表示する
             */
            _showConfirm: function () {
                if (confirm("管理者に回答を送信します。\n送信後は回答内容を変更することができません。\n送信してよろしいですか？")) {
                    this._endQuestion();
                }
            },

            /**
             * セルフチェック確認画面を表示する
             */
            _showWritinfShowConfirm: function () {
                this._endQuestion();
            },

            /**
             *
             * 削除ボタンをクリックした。
             */
            _onClickQuitButton: function (event) {
                event.preventDefault();

                /*
                 * TODO ここに確認画面を追加すること
                 */

                if ('function' === typeof window.player_custom_close) {
                    window.player_custom_close();
                } else {
                    window.close();
                }

            },
            _onClickPrevButton: function () {
                this.prevQuestion();
            },
            _onClickNextButton: function () {
                this.nextQuestion();
            },
            _onClickConfirmButton: function () {
                this._endQuestion();
            },

            /**
             * 目次を作る
             *
             */
            _buildJumpMenuBar: function () {

                var view, scope;

                view = {
                    bookIndex: this.model.get("bookIndex")
                };

                this.$el.append('<div style="display:none;"><div id="bookIndexView" class="bookindex" ></div></div>');

                this.bookIndex = new BookIndexView({
                    view: view,
                    model: this.model
                });
                this.bookIndex.render();

                $('#bookIndexView').append(this.bookIndex.el);

                scope = this;

                $('li', $('#bookIndexView')).filter("[class!='combination']").click(function () {
                    scope.jampQuestion(Number($(this).attr("ref")) - 1);
                }).css("cursor", "pointer");

                $.subscribe('/QuestionController/showJampButton', $.proxy(this._showJumpButton, this));



                if (window.playerModel.get("visionary") !== "ac2weeklydrill") {
                    this.headerArea.ui.jampButton.show();
                }

                if (window.playerModel.get("isShowFooterMenu")) {
                    this.footerArea.ui.jampButton.show();
                }



            },
            _showJumpButton: function () {

                var scope = this;

                $.fancybox($("#bookIndexView"), {
                    hideOnOverlayClick: true,
                    type: 'inline',
                    openEffect: 'none',
                    closeEffect: 'none',

                    afterShow: function () {

                        if (window.playerModel.get("isUseIScroll")) {

                            if (scope.bookIndexScroll === null) {
                                setTimeout(function () {

                                    scope.bookIndexScroll = new window.iScroll('bookIndexView');

                                }, 1000);
                            }
                        }
                    }
                });
            },


            /**
             * 問題が変わった
             * @param {Object} e
             */
            _onChangeQuestion: function (model, value) {
                this._buildQuestion();
            },
            /**
             * 問題を開始する
             */
            startQuestion: function () {
                this.nextQuestion();

                if (this.model.get("limitTime") > 0) {
                    this.startTimer();
                }
            },
            /**
             * タイマーをスタートする
             */
            startTimer: function () {
                var view = {
                    "limitTime": this.model.get("limitTime"),
                    "timeup": $.proxy(this._timeupQuestion, this),
                    "title": "制限時間："
                };

                if (window.playerModel.isMobile()) {
                    view.title = '<span class="icon-time"></span> 残り ';
                }

                this.timerViewer = new CountDownTimerView({el: $("#timer"), view: view});
                this.timerViewer.startTimer();
            },

            /**
             * 次の問題へ
             */
            nextQuestion: function () {
                if (!this.isLockControll()) {
                    this.lockControll();
                    this.model.nextQuestion();
                }
            },

            /**
             *前の問題へ
             */
            prevQuestion: function () {
                if (!this.isLockControll()) {
                    this.lockControll();
                    this.model.prevQuestion();
                }
            },
            /**
             * 一時保存を行う
             */
            draftQuestion: function () {
                if (!this.isLockControll()) {
                    this.lockControll();
                    this.model.draftQuestion();
                }
            },
            _timeupQuestion: function () {

                if (this.model.get("ended")) {
                    return;
                }

                this.model.set("ended", true);


                $.fancybox.close();

                this.model.set("timeoutFlag", true);


                this.trigger("EVENT_START_SEND_DATA");

                var scope = this;

                this.$el.fadeOut("slow", function () {
                    scope.mainArea.clear();
                    $(".timeUpContainer").fadeIn("slow")
                        .delay(1000)
                        .fadeOut("slow", function () {
                            scope.$el.fadeIn("slow", function () {
                                scope._showJudgment();
                            });
                        });
                });

            },

            /**
             * 問題番号を指定して表示
             * @param {Object} index　0から始まる問題番号
             */
            jampQuestion: function (index) {
                if (!this.isLockControll()) {
                    //ロック
                    this.lockControll();
                    this.model.jampQuestion(Number(index));
                }
            },
            /**
             * 解答した
             */
            doAnswered: function (model, value) {

                if (this.bookIndex !== null) {
                    this.bookIndex.updateStatus();
                }

            },

            /**
             * ロックしているかどうか
             */
            isLockControll: function () {
                return this.__lockControllFlag;
            },

            /**
             * ロックする
             */
            lockControll: function () {
                this.__lockControllFlag = true;
            },

            /**
             * ロックを解除する
             */
            unLockControll: function () {
                this.__lockControllFlag = false;
            },
            /**
             * 複合問題の入れものを作る
             */
            _createCombinationQuestionConterner: function (combinationQuestion) {

                var questionConterner;
                switch (combinationQuestion.get("questionType")) {

                case "listeningComprehension":

                    if (this.model.get("mode") === "test") {
                        questionConterner = new TestModeListeningCombinationQuestionView({ model: combinationQuestion});
                    } else {
                        questionConterner = new CombinationQuestionView({model: combinationQuestion});
                    }

                    break;

                case "speedReadingCombination":
                    questionConterner = new SpeedReadingCombinationQuestionView({model: combinationQuestion});
                    break;
                default:
                    questionConterner = new CombinationQuestionView({ model: combinationQuestion});

                    break;
                }


                questionConterner.render();
                this.mainArea.$el.append(questionConterner.el);

            },
            _buildQuestion: function () {


                var question, buildData, combinationQuestion, target;

                question = this.model.getCurrentQuestion();

                buildData = null;

                if (this.nextBuildQuestionData === null) {

                    /*
                     *
                     * データを新しく作る
                     */

                    buildData = new BuildDataObject();

                    buildData.set({
                        target: this.mainArea.$el,
                        next: question
                    });

                    if (this.pageManager.currentPage !== null) {

                        buildData.set({
                            old: this.pageManager.currentPage.question
                        });

                    }

                    this.nextBuildQuestionData = buildData;

                } else {
                    buildData = this.nextBuildQuestionData;
                }


                if (this.pageManager.currentPage === null) {

                    if (
                        buildData.isOldCombination()
                            && buildData.isNextCombination()
                            && buildData.isSameCombination()
                    ) {
                        //前のコンテンツも同じ複合問題
                        buildData.set({
                            target: $("#main .innerQuestionBox")
                        });

                    } else if (buildData.isNextCombination()) {

                        /*
                         次の問題が複合問題
                         */

                        /*
                         * 複合問題の入れものを作る
                         */

                        combinationQuestion = this.model.getCombinationQuestionDataForQuestion(buildData.get("next"));
                        this._createCombinationQuestionConterner(combinationQuestion);
                        this.mainArea.$el.show();

                        buildData.set({
                            target: $("#main .innerQuestionBox")
                        });


                    } else {

                        buildData.set({
                            target: this.mainArea.$el
                        });

                    }

                } else {

                    if (
                        buildData.isOldCombination()
                            && buildData.isNextCombination()
                            && buildData.isSameCombination()
                    ) {

                        buildData.set({
                            target: $("#main .innerQuestionBox")
                        });

                    } else {

                        buildData.set({
                            target: this.mainArea.$el
                        });

                    }


                }


                target = null;

                if (this.pageManager.currentPage === null) {
                    /*
                     *  表示する
                     */

                    target = buildData.get("target");
                    target.hide();
                    this.pageManager.currentPage = QuestionViewBuilder.build(target, question);
                    this.pageManager.currentPage.render();

                    target.fadeIn("slow", $.proxy(this._onSlowQuestion, this));

                } else {
                    /*
                     * 隠す
                     */
                    target = buildData.get("target");
                    //中身を空にする。
                    target.fadeOut("slow", $.proxy(this._onClearQuestion, this));

                }
            },
            /**
             *　問題の表示が終了した
             */
            _onSlowQuestion: function () {

                var myScroll,
                    myScroll2;


                this.trigger("EVENT_SHOW_END_QUESTION");

                if (window.playerModel.get("isUseIScroll")) {
                    myScroll = new window.iScroll($(".questionBox").get()[0]);

                    if (this.nextBuildQuestionData.isNextCombination() && !this.nextBuildQuestionData.isOldCombination()) {
                        if ($('.combinationCombinationPassage').length !== 0) {
                            myScroll2 = new window.iScroll($('.combinationCombinationPassage').get()[0]);
                        }
                    }

                    this.pageManager.currentPage._refresh();
                }
                this._refreseWindow();
                this.nextBuildQuestionData = null;

                //ロック解除
                this.unLockControll();
            },
            _onClearQuestion: function (index) {

                var target = this.nextBuildQuestionData.get("target");
                console.log("0000000000000000000000000000");
                console.log(this.pageManager.currentPage);

                target.html("");
                this.pageManager.currentPage.destroy();

                this.pageManager.currentPage = null;

                this._buildQuestion();

            },

            /**
             *
             */
            _endQuestion: function () {

                if (this.model.get("ended")) {
                    return;
                }
                this.model.set("ended", true);


                this.trigger("EVENT_START_SEND_DATA");

                if (this.model.get("limitTime") > 0) {
                    this.timerViewer.stopTimer();
                }

                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4) {
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._showSendingAnswer, this));
                } else if (window.playerModel.get("bookType") === 5) {
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._showSendingWritingAnswer, this));
                } else {
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._showJudgment, this));
                }

            },
            /**
             * 「結果を送信中」表示画面を表示する
             */
            _showSendingWritingAnswer: function () {

                this.mainArea.clear();

                var view = new SendingWritingAnswerView({view: null});
                view.render();
                this.mainArea.$el.append(view.el);

                this.mainArea.$el.fadeIn("slow");

                if (!window.playerModel.get("isPreview")) {
                    this.model.endQuestion();
                } else {
                    this.mainArea.$el.delay(1000);
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._buildEndQuestion, this));
                }
            },
            /**
             * 「回答を送信中」表示画面を表示する
             */
            _showSendingAnswer: function () {

                this.mainArea.clear();

                var view = new SendingAnswerView({view: null});
                view.render();
                this.mainArea.$el.append(view.el);

                this.mainArea.$el.fadeIn("slow");

                if (!window.playerModel.get("isPreview")) {
                    this.model.endQuestion();
                } else {
                    this.mainArea.$el.delay(1000);
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._buildEndQuestion, this));
                }
            },

            /**
             * 採点中表示画面を表示する
             */
            _showJudgment: function () {

                this.mainArea.clear();

                var judgementView = new JudgementView({view: null});
                judgementView.render();
                this.mainArea.$el.append(judgementView.el);

                this.mainArea.$el.fadeIn("slow");

                if (!window.playerModel.get("isPreview")) {
                    this.model.endQuestion();
                } else {
                    this.mainArea.$el.delay(1000);
                    this.mainArea.$el.fadeOut("slow", $.proxy(this._buildEndQuestion, this));
                }
            },
            _onSendEndQuestion: function (model, value) {
                if (!window.playerModel.get("isPreview")) {
                    //回答を保存した場合等、親Windowを更新するフラグをセットする（テストの場合）
                    this.model.set("isEndDril", true);
                }

                this.mainArea.$el.delay(1000);
                this.mainArea.$el.fadeOut("slow", $.proxy(this._buildEndQuestion, this));
            },
            _buildEndQuestion: function () {

                this.mainArea.clear();

                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4) {
                    this._buildEndQuestionSendingAnswer();

                } else if (window.playerModel.get("bookType") === 5) {
                    this._buildEndQuestionSendingWritingAnswer();
                } else {
                    this._buildEndQuestionJudgement();
                }
            },

            /**
             * セルフチェックの場合の最後の画面
             */
            _buildEndQuestionSendingWritingAnswer: function () {
                this.trigger("EVENT_START_SHOW_END_PAGE");

                this.mainArea.$el.append('<div class="questionBox"><div class="questionnairesComment">結果を送信しました。</div>');
                this.mainArea.$el.fadeIn("slow", $.proxy(this._onShowEndQuestion, this));
            },

            /**
             * アンケートの場合の最後の画面
             */
            _buildEndQuestionSendingAnswer: function () {
                this.trigger("EVENT_START_SHOW_END_PAGE");
                this.mainArea.$el.append('<div class="questionBox"><div class="questionnairesComment">回答を送信しました。<br />ありがとうございました。</div></div>');
                this.mainArea.$el.fadeIn("slow", $.proxy(this._onShowEndQuestion, this));
            },
            /**
             * 判定する場合の最後の画面
             */
            _buildEndQuestionJudgement: function () {

                this.trigger("EVENT_START_SHOW_END_PAGE");


                var answer, scope, descriptionBox, scoreView;


                if (window.playerModel.get("previewType") === "book") {
                    answer = this.model.getAnswers();
                    scoreView = new BookPreviewScoreView({el: this.mainArea.el, view: answer});
                    scoreView.render();

                } else if (window.playerModel.get("previewType") === "combination" || window.playerModel.get("previewType") === "single") {
                    this.mainArea.$el.append('<div class="questionBox"></div>');

                } else {
                    answer = this.model.getAnswers();
                    scoreView = new ScoreView({el: this.mainArea.el, view: answer});
                    scoreView.render();
                }

                scope = this;

                if (this.model.get("mode") === "" || this.model.get("mode") === "drill" || this.model.get("explainDisplay")) {

                    descriptionBox = new DescriptionBoxView({model: this.model});

                    descriptionBox.render();

                    $(".questionBox").append(descriptionBox.el);


                    descriptionBox.on("clickGoDescriptionButton", function (num) {


                        var $scrollTarget, nowScrollY;



                        $scrollTarget  = $(".questionBox:not( :has(>.combinationHeader) )", descriptionBox.$el).eq(num - 1);


                        console.log(num);
                        console.log($scrollTarget);

                        if (window.playerModel.get("isUseIScroll")) {
                            nowScrollY = scope.iScrollBar.y;
                            scope.iScrollBar.scrollTo(0, -$scrollTarget.position().top + nowScrollY, "800ms");
                        } else {



                            scope.mainArea.$el.stop().scrollTo($scrollTarget, 800);
                        }
                    });


                    $("div.sound", $(".questionBox")).each(function () {
                        if ($.browser.name !== 'safari' && $.browser.name !== 'chrome') {
                            window.AudioPlayer.embed($(this).attr("id"), {
                                soundFile: $(this).attr("ref"),
                                titles: "#1",
                                artists: "Track"
                            });
                        }
                    });

                }

                this.mainArea.$el.fadeIn("slow", $.proxy(this._onShowEndQuestion, this));
            },
            _showIFrame: function (el, text) {

                var $div, _text, $ifm, $idoc, $ibody;



                $div = el;

                _text = text;
                $ifm = $div.append('<iframe class="trans_iframe" style="background-color: #dbff9f;" frameborder="0" height="10px" width="500px" />').find('> :last-child');
                $idoc = $ifm.contents();

                $idoc[0].open();
                $idoc[0].close();
                $ibody = $idoc.find('body');
                $ibody.html(_text);


                //TODO なぜかIE7では１回では高さが変更されないので、２回やっている

                $ifm.height($ibody[0].scrollHeight);
                $ifm.height($ibody[0].scrollHeight);
            },
            _onShowEndQuestion: function () {

                if (!window.playerModel.get("isPreview")) {
                    if (window.parent !== null && window.parent.customizedTrainingOnEnd) {
                        window.parent.customizedTrainingOnEnd();
                    }
                }

                if (window.playerModel.get("bookType") === 3 || window.playerModel.get("bookType") === 4) {
                    //レポート、アンケートは、送信中を表示する
                    this._onShowEndQuestionSendingAnswer();
                } else {
                    //判定、採点中の画面を表示しする
                    this._onShowEndQuestionJudgement();
                }

            },
            /**
             *
             * @private
             */
            _onShowEndQuestionSendingAnswer: function () {
                if (window.playerModel.get("isUseIScroll")) {
                    this.iScrollBar = new window.iScroll($(".questionBox").get()[0]);
                    this.pageManager.currentPage._refresh();
                }
            },
            /**
             *
             * @private
             */
            _onShowEndQuestionJudgement: function () {

                if (this.model.get("mode") === "" || this.model.get("mode") === "drill") {

                    if (window.playerModel.get("isDescriptionIFrame")) {

                        //iFrameで表示する
                        var scope = this;
                        $(".description", $(".questionBox")).each(function () {

                            var html = $(this).html();
                            //空にする
                            $(this).html("");

                            if (html) {
                                scope._showIFrame($(this), html);
                            }
                        });
                    }

                }

                if (window.playerModel.get("isUseIScroll")) {

                    this.iScrollBar = new window.iScroll($(".questionBox").get()[0]);
                    this.pageManager.currentPage._refresh();
                }
            }
        });
    });
