define('app/view/systemcheck/SystemCheckFlash',
    [
        "Backbone"
    ],
    function (
        Backbone
    ) {
        
        return Backbone.View.extend({
            player: null,
            listeners: [],
            /**
             * コンストラクタ
             */
            initialize: function (options) {
                var player_id = options.player_id;
                this.player = (navigator.appName.indexOf("Microsoft") !== -1) ? window[player_id] : document[player_id];
                this.listeners = [];
            },
            render: function () {
                return this;
            },
            play: function (soundpath) {
                this.player.playFile(soundpath);
            },
            stop: function (soundpath) {
                this.player.stopFile(soundpath);
            },
            getInfo: function () {
                return this.player.getCapabilities();
            },
            onloadPlayer: function () {
                var o;
                for (o in this.listeners) {
                    if (this.listeners.hasOwnProperty(o)) {
                        this.listeners[o].onLoadJsSoundPlayer();
                    }
                }
            },
            onEndPlay: function () {
                var o;
                for (o in this.listeners) {
                    if (this.listeners.hasOwnProperty(o)) {
                        this.listeners[o].onPlayEndJsSoundPlayer();
                    }
                }
            },
            addListener: function (listener) {
                this.listeners.push(listener);
                // alert("JsSoundPlayer.addListener:"+JsSoundPlayer.listeners.length);
            },
            removeListener: function (listener) {
                // alert("JsSoundPlayer.removeListener_s:"+JsSoundPlayer.listeners.length);
                var i;
                for (i = 0; i < this.listeners.length; i++) {
                    if (this.listeners[i] === listener) {
                        // alert("JsSoundPlayer.removeListener_e:xxxxx");
                        this.listeners.splice(i, 1);
                    }
                }

                // alert("JsSoundPlayer.removeListener_e:"+JsSoundPlayer.listeners.length);

            }


        });

    }
);

define('text!app/templates/view/SystemCheckView.html',[],function () { return '<div id="systemCheckView">\n    <h2>システムチェック</h2>\n\n    <p class="nowChecking">テスト受験の前に動作環境を確認しています...。</p>\n\n    <div id="SystemCheckTable"></div>\n    <div id="audioCheckBox"></div>\n    <div id="SystemCheckController" style="display: none;">\n        <p class="hanteiMessage"></p>\n        <div class="row-fluid">\n            <div class="span6">\n                <a href="#" id="ngCloseButton" class="btn btn-block btn-large ">終了</a>\n            </div>\n            <div class="span6">\n\n                <a href="#" id="okStartButton" class="byn btn-block btn-large btn-vc2">OK</a>\n            </div>\n        </div>\n    </div>\n</div>\n';});

