define('text!app/templates/SystemCheck.html',[],function () { return '<h3>動作環境の確認</h3>\n<div class="havError_{{havError}}">\n    <p class="havError">動作環境に問題が見つかりました。</p>\n    <p class="noError">問題ありません。</p>\n</div>\n<table class="havError_{{havError}}">\n    <thead>\n        <tr>\n            <th>動作環境</th>\n            <th>判定</th>\n            <th>調査結果</th>\n            <th>対処方法</th>\n        </tr>\n    </thead>\n    <tbody>\n        {{#koumoku}}\n        <tr class="hantei_{{ok}}">\n            <th>{{label}}</th>\n            <td nowrap>\n            {{hantei}}\n            </td>\n            <td nowrap>\n            {{{result}}}\n            </td>\n            <td>\n            {{{comment}}}\n            </td>\n        </tr>\n        {{/koumoku}}\n    </tbody>\n</table>';});

/*global require: false, define: false, Class: false, Audio:true */
define('app/view/SystemCheckView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        "app/view/systemcheck/SystemCheckFlash",
        'text!app/templates/view/SystemCheckView.html',
        'text!app/templates/view/systemcheck/audioCheckBox.html',
        'text!app/templates/view/systemcheck/getflashplayer.html',
        'text!app/templates/SystemCheck.html'
    ],
    function (
        $,
        AbstractBackbornView,
        SystemCheckFlash,
        systemCheckViewTemplates,
        audioCheckBoxTemplates,
        getflashplayerTemplates,
        template
    ) {
        
        /**
         * SystemCheckView
         *
         * システムチェックを行う画面
         *
         * @param {Object} el
         * @param {Object} view
         */
        return AbstractBackbornView.extend({

            /**  システムチェック用のFlashのパス */
            SWF_PATH: "js/libs/systemCheck/SystemCheck.swf",
            /** システムチェック用のFlashのID */
            PLAYER_ID: "SystemCheckSWFexternal",
            /** 必須ウィンドウサイズ 幅　*/
            SCREEN_MIN_WIDTH: 1000,
            /** 必須ウィンドウサイズ　高さ */
            SCREEN_MIN_HEIGHT: 640,
            /** 音声再生確認用の音声パス */
            SOUND_PATH: "sounds/audioCheck.mp3",

            initialize: function (option) {
                //
            },
            events: {
                "click #ngCloseButton": "_onClickNgCloseButton",
                "click #okStartButton": "_onClickOkStartButton"
            },

            /**
             * ウィンドウサイズが変更された
             *
             */
            _refreseWindow: function () {
                this._showResult();
            },

            /**
             * システムチェック後　OKだった場合の次へボタンの処理
             */
            _onClickOkStartButton: function (event) {
                event.preventDefault();

                $.fancybox.close();
                this.remove();
                $("#popupBox2").remove();


                this.trigger("clickStartButton", null);
            },


            /**
             * システムチェック後　NGだった場合のウィンドウを閉じるボタン
             */
            _onClickNgCloseButton: function (event) {
                event.preventDefault();

                $.fancybox.close();
                this.remove();
                $("#popupBox2").remove();


                this.trigger("clickCloseButton", null);
            },


            /**
             *
             */
            render: function () {


                this.$el.append(systemCheckViewTemplates);


                var scope = this;
                setTimeout(function () {
                    //Flash の読み込み　時間差を空ける
                    scope._builfFlash();
                }, 500);


                //TODO popupBoxの名前を変更すること
                $.fancybox(this.$el, {
                    'type': 'inline',
                    'openEffect': 'none',
                    'closeEffect': 'none',
                    'closeBtn': false,
                    helpers: {
                        overlay: {
                            closeClick: false,
                            css: {
                                'background': 'rgba(255, 255, 255, 0.9)'
                            }
                        }
                    }

                });


            },
            destroy: function () {
                $("#SystemCheckSWFexternal").remove();
                if (window.hasOwnProperty("onorientationchange")) {
                    $(window).unbind('orientationchange', $.proxy(this._refreseWindow, this));
                } else {
                    $(window).unbind('resize', $.proxy(this._refreseWindow, this));
                }
            },

            /**
             *
             */
            _builfFlash: function () {

                var html2, scope;

                html2 = [
                    '<div id="SystemCheckSWFexternal">',
                    '   <span id="systemCheckSWFNoFlash"></span>',
                    '</div>'
                ].join('');


                $("body").append(html2);

                window.swfobject.embedSWF(this.SWF_PATH, this.PLAYER_ID, "1", "1", "10", false);

                scope = this;
                setTimeout(function () {
                    scope._endChecking();
                }, 3000);

            },
            /**
             * Flashがインストールされているかどうか
             */
            _isInstallFlash: function () {

                return $("#systemCheckSWFNoFlash").length === 0;

            },
            /**
             * iPadかどうか
             */
            _isIpad: function () {
                return ($.os.name === 'ipad');
            },
            /**
             * 音声を再生する
             */
            _playSound: function () {
                var audioObj, systemCheckFlash;
                if (this._isIpad()) {
                    audioObj = new Audio(this.SOUND_PATH);
                    audioObj.play();
                } else {
                    systemCheckFlash = new SystemCheckFlash({player_id: this.PLAYER_ID});
                    systemCheckFlash.play(this.SOUND_PATH);
                }
            },
            /**
             * システムチェックが終了した
             */
            _endChecking: function () {

                $('.nowChecking', "#systemCheckView").remove();

                this._showResult();
                //TODO イベントの削除は？
                if (window.hasOwnProperty('onorientationchange')) {
                    $(window).bind('orientationchange', $.proxy(this._refreseWindow, this));
                } else {
                    $(window).bind('resize', $.proxy(this._refreseWindow, this));
                }

            },
            /**
             * システムチェック結果を表示する
             */
            _showResult: function () {

                var scope, koumoku_flash, koumoku_audio, koumoku_os, koumoku_browser, koumoku_screen,
                    systemCheckFlash, flashInfo, results, html;

                scope = this;

                koumoku_flash = {
                    label: 'Flash Player',
                    ok: false,
                    result: "",
                    comment: function () {
                        return this.ok ? "" : getflashplayerTemplates;
                    },
                    hantei: function () {
                        return this.ok ? "OK" : "NG";
                    }
                };

                koumoku_audio = {
                    label: '音声再生',
                    ok: false,
                    result: function () {
                        return this.ok ? '可能' : '不可';
                    },
                    comment: "ご使用の環境では、音声ができません。",
                    hantei: function () {
                        return this.ok ? "OK" : "NG";
                    }
                };

                koumoku_os = {
                    label: 'OS',
                    ok: false,
                    result: function () {
                        var osname = "";
                        switch ($.os.name) {
                        case "win":
                            osname = "Windows";
                            break;
                        case "mac":
                            osname = "Mac";
                            break;
                        default:
                            osname = $.os.name;
                        }
                        return osname;
                    },

                    comment: function () {

                        var c = "";

                        if (!this.ok) {

                            c = [
                                'スーパー英語のご利用には、下記いずれかのOSが必要になります。<br />',
                                'Microsoft Windows XP,Vista,7,Mac OX X(10.5.X)以上'
                            ].join('');

                        }

                        return c;

                    },

                    hantei: function () {
                        return this.ok ? "OK" : "NG";
                    }
                };

                koumoku_browser = {
                    label: 'ブラウザー',
                    ok: false,
                    result: $.browser.name + " " + $.browser.versionNumber,
                    comment: function () {
                        if (!this.ok) {

                            var c = ['',
                                'スーパー英語のご利用には、下記いずれかのブラウザーが必要になります。',
                                'ブラウザーをアップデートしていただくか、別のブラウザをご利用ください。<br />',
                                'Internet Explorer 8以上、Firefox 3.5以上、Google chrome 12以上、Safari 4以上'
                                ].join('');

                            return c;
                        }

                        return "";

                    },
                    hantei: function () {
                        return this.ok ? "OK" : "NG";
                    }
                };

                koumoku_screen = {
                    label: '画面サイズ',
                    ok: false,
                    result: function () {
                        var w, h;

                        w = $(window).width();
                        h = $(window).height();
                        return "幅：" + w + "px" + "<br />" + "高さ：" + h + "px";
                    },
                    comment: function () {
                        if (!this.ok) {

                            if (scope._isIpad()) {
                                return "iPadを横に向けてください。";
                            }
                            return "ウィンドウを調節して、" + "幅：" + scope.SCREEN_MIN_WIDTH + "px" + " " + "高さ：" + scope.SCREEN_MIN_HEIGHT + "以上に設定してください。";


                        }
                        return "";
                    },
                    hantei: function () {
                        return this.ok ? "OK" : "NG";
                    }
                };


                if (this._isInstallFlash()) {



                    systemCheckFlash = new SystemCheckFlash({player_id: this.PLAYER_ID});
                    flashInfo = systemCheckFlash.getInfo();

                    /*
                     hasAudio
                     screenResolutionX
                     playerType
                     screenResolutionY
                     hasMP3
                     version
                     os
                     */


                    koumoku_flash.result = flashInfo.version;
                    koumoku_os.result = flashInfo.os;

                    /*
                     ここから判定
                     */
                    koumoku_flash.ok = true;

                    koumoku_audio.ok = flashInfo.hasAudio && flashInfo.hasMP3;


                } else if (this._isIpad()) {

                    koumoku_flash.ok = false;
                    koumoku_audio.ok = true;
                } else {


                    koumoku_flash.ok = false;
                    koumoku_audio.ok = false;

                }


                /*
                 ここから判定
                 */
                koumoku_os.ok = this._check_os(koumoku_os);


                koumoku_screen.ok = this._check_screen();
                koumoku_browser.ok = this._check_browser();


                results = null;

                if (this._isInstallFlash()) {
                    results = {

                        koumoku: [
                            koumoku_flash,
                            koumoku_audio,
                            koumoku_os,
                            koumoku_browser,
                            koumoku_screen
                        ]

                    };
                } else if (this._isIpad()) {
                    results = {

                        koumoku: [

                            koumoku_audio,
                            koumoku_os,
                            koumoku_browser,
                            koumoku_screen
                        ]

                    };
                } else {

                    results = {

                        koumoku: [
                            koumoku_flash,
                            koumoku_audio,
                            koumoku_os,
                            koumoku_browser,
                            koumoku_screen
                        ]

                    };

                }


                results.havError = this._havError(results.koumoku);

                html = $.mustache(template, results);

                $("#SystemCheckTable").html(html);


                $("#audioCheckBox").html(audioCheckBoxTemplates);


                $('.playSoundButton', this.el).click($.proxy(this._playSound, this));


                $("#SystemCheckController").show();
                if (results.havError) {

                    $("#okStartButton").hide();
                    $("#ngCloseButton").show();
                    $("#SystemCheckController").find(".hanteiMessage").html("動作環境に問題が見つかったため、受講できません。");


                } else {

                    $("#okStartButton").show();
                    $("#ngCloseButton").show();
                    $("#SystemCheckController").find(".hanteiMessage").html("音声の再生が確認できましたら、「OK」ボタンをクリックしてください。");


                }

                $.fancybox.update();
                $.fancybox.reposition();
            },
            /**
             * OS のチェックを行う
             *
             */
            _check_os: function (koumoku_os) {

                var hantei = false;
                switch ($.os.name) {

                case "win":

                    switch (koumoku_os.result) {

                    case "Windows 2000":
                    case "Windows NT":
                    case "Windows 98/ME":
                    case "Windows 95":
                    case "Windows CE":
                        hantei = false;
                        break;
                    default:
                        hantei = true;
                    }


                    break;
                case "mac":
                    hantei = true;
                    break;
                case "ipad":
                    hantei = true;
                    break;
                default:
                    hantei = false;

                }

                return hantei;
            },
            /**
             * ウィンドウサイズノチェックを行う
             */
            _check_screen: function () {

                var w, h;

                w = $(window).width();
                h = $(window).height();
                return w >= this.SCREEN_MIN_WIDTH && h >= this.SCREEN_MIN_HEIGHT;
            },
            /**
             * ブラウザチェック
             */
            _check_browser: function () {

                var hantei = false;

                switch ($.browser.name) {

                case "msie":

                    hantei = $.browser.versionNumber >= 8;

                    break;
                case "firefox":
                    hantei = $.browser.versionNumber >= 3;

                    break;
                case "chrome":
                    hantei = $.browser.versionNumber >= 12;
                    break;
                case "safari":
                    hantei = $.browser.versionNumber >= 4;
                    break;
                default:


                    if (window.navigator.userAgent.toLowerCase().indexOf('trident') >= 0) {
                        // ie11
                        hantei = true;
                    } else {
                        hantei = false;
                    }



                }

                return hantei;
            },
            /**
             *　動作環境にエラーがあるかどうか
             */
            _havError: function (koumoku) {
                var i;
                for (i = 0; i < koumoku.length; i++) {
                    if (!koumoku[i].ok) {

                        return true;
                    }

                }
                return false;
            }

        });

    }
);

define('text!app/templates/view/ReviewView.html',[],function () { return '{{%IMPLICIT-ITERATOR}}\n<div class="questionBox">\n  <div class="questionTitle"><span class="questionNumber">{{questionNumber}}</span>: {{title}}</div>\n  <div class="question lang-{{lang}}" lang="{{lang}}">{{{question}}}</div>\n{{#haveYourAnswer}}\n  <div class="lang-ja" lang="ja">(あなたの解答)</div>\n  <div style="padding:10px;color:#0000FF;">{{{yourAnswer}}}</div>\n{{/haveYourAnswer}}\n{{#notHaveYourAnswer}}\n  <div class="noAnswer lang-ja" lang="ja">（未解答）</div>\n{{/notHaveYourAnswer}}\n  <div class="lang-ja" lang="ja">（レビュー）</div>\n  <div style="padding:10px;color:#FF0000;">{{review}}</div>\n\n</div>';});

define('text!app/templates/reviewBox.html',[],function () { return '<table>\n      <tr>\n            <th>No</th>\n            <th>レビュー</th>\n      </tr>\n    {{descriptionsTableRows}}\n</table>';});

define('text!app/templates/reviewBoxRaw.html',[],function () { return '<tr>\n    <td style="text-align:center">{{number}}</td>\n    <td>{{{html}}}<div class="description">{{{description}}}</div></td>\n</tr>';});

/*global require: false, define: false, Class: false */
define('app/view/ReviewView',
    [
        "jQuery",
        "app/view/AbstractBackbornView",
        'text!app/templates/view/ReviewView.html',
        'text!app/templates/reviewBox.html',
        'text!app/templates/reviewBoxRaw.html'
    ],
    function (
        $,
        AbstractBackbornView,
        childtemplate,
        reviewBoxTemplate,
        reviewBoxRawTemplate
    ) {
        
        return AbstractBackbornView.extend({
            el: "body",

            render: function () {

                this.$el.css("backgroundColor", "#FFFFFF");

                this.$el.append('<div id="main" style="display:none;"></div>');
                $("#main").append('<div class="questionBox"></div>');

                var descriptionBox = this.createReviewBox();
                $(".questionBox").append(descriptionBox);
                $("#main").fadeIn("slow");

                if (window.parent !== null) {
                    window.parent.resizeIFrame($(document).height());
                }
                return this;
            },

            /**
             * レビューを作成する
             */
            createReviewBox: function () {
                var scope,
                    descriptionBox,
                    descriptionsTableRows,
                    descriptionsTable;

                scope = this;
                descriptionBox = $('<div class="descriptionBox" style="padding:0;"></div>');

                descriptionsTableRows = "";

                $(this.model.get("bookIndex")).each(function (i, val) {
                    var view, childtemplate, childhtml;

                    view = scope.getDescriptionViewForReview(val);
                    console.log(view);


                    childtemplate = reviewBoxRawTemplate;


                    childhtml = $.mustache(childtemplate, view);
                    descriptionsTableRows += childhtml;


                });

                descriptionsTable = $.mustache(reviewBoxTemplate, {descriptionsTableRows: descriptionsTableRows});



                descriptionBox.append(descriptionsTable);

                //選択できないようにする
                descriptionBox.disableTextSelect();

                return descriptionBox;
            },

            /**
             * レビュー用の表示を取得する
             */
            getDescriptionViewForReview: function (question) {

                var description = {};

                description.number = question.questionNumber;
                description.review = question.review;

                if (question.yourAnswer !== "") {
                    question.haveYourAnswer = true;
                } else {
                    question.notHaveYourAnswer = true;
                }

                description.html = $.mustache(childtemplate, question);


                return description;
            }


        });
    }
);
define('text!app/templates/errorSessionTimeout.html',[],function () { return '<div style="display:none;">\n    <div id="popupBox">\n        <p>ログインが切れています。<br/>閉じるボタンを押して元の画面で再ログインしてください。</p>\n        <a href="#" id="errorCloseButton" class="button fancyboxButton">閉じる</a>\n    </div>\n</div>';});

define('text!app/templates/view/SystemCheckViewWrapper.html',[],function () { return '<div style="display:none;">\n    <div id="popupBox2" style="width:600px;"></div>\n</div>';});

/*global require: false, define: false, Class: false */

define('app/Player',
    [
        "jQuery",
        "Marionette",
        "app/QuestionModel",
        "app/QuestionController",
        "app/LoadingContainer",
        'text!app/templates/container.html',
        'text!app/templates/timeUpContainer.html',
        'text!app/templates/printContainer.html',
        "app/view/SystemCheckView",
        "app/view/ReviewView",
        'text!app/templates/errorSessionTimeout.html',
        'text!app/templates/view/SystemCheckViewWrapper.html'
    ],
    function (
        $,
        Marionette,
        QuestionModel,
        QuestionController,
        LoadingContainer,
        mainTemplate,
        timeUpContainerTemplate,
        printContainerTemplate,
        SystemCheckView,
        ReviewView,
        errorSessionTimeoutTemplates,
        wrapperTemplate
    ) {
        
        return Marionette.View.extend({


            el: 'body',
            /** モデル */
            questionModel: null,
            /** ローディングView */
            loadingContainer: null,
            /** システムチェックView */
            systemCheckView: null,
            /**
             * テンプレート
             */
            template: mainTemplate,
            /**
             * コンストラクタ
             */
            initialize: function (options) {
                window.console.log("Player.initialize()");
                this.initAudioPlayer();
                this.setCulture();
                this.setIscroll();
                this.questionModel = new QuestionModel();
                this.questionModel.on("/QuestionModel/load", this._onLoadModelData, this);
                this.questionModel.on('/QuestionModel/sendAnswerError', this._onSendAnswerError, this);
                /*
                 閉じた場合の処理
                 */

                $(window).bind('beforeunload', $.proxy(this.windowOnBeforeunload, this));
                $(window).bind('unload', $.proxy(this.windowOnUnload, this));

            },
            /**
             * 音声再生用のFlashをロードする
             * TODO: ここのロード完了処理、Flashが必要でない場合が実行しないように設定すること
             */
            initAudioPlayer: function () {

                window.AudioPlayer.setup("js/libs/audio-player/player.swf", {
                    width: 290,
                    animation: "no"
                });
                window.JsSoundPlayer.setup("js/libs/js-sound-player/JsSoundPlayer.swf");
            },

            /**
             * 言語を設定する
             */
            setCulture: function () {

                if (this.model.get("culture") === "cn") {

                    //TODO　本当は設定ファイルで行う
                    this.model.set("isDescriptionIFrame", true);

                    //TODO　本当は設定ファイルで行う
                    // s:シングルカラム　w:ダブルカラム
                    this.model.set("matchingQuestionLayout", "s");

                    $.global.culture = $.global.cultures["ja-Chinese"];

                } else if (this.model.get("culture") === "ja") {

                    //TODO　本当は設定ファイルで行う
                    this.model.set("isDescriptionIFrame", false);

                    //TODO　本当は設定ファイルで行う
                    // s:シングルカラム　w:ダブルカラム
                    this.model.set("matchingQuestionLayout", "w");

                    $.global.culture = $.global.cultures["ja-Japanese"];

                } else {


                    //TODO　本当は設定ファイルで行う
                    this.model.set("isDescriptionIFrame", false);

                    //TODO　本当は設定ファイルで行う
                    // s:シングルカラム　w:ダブルカラム
                    this.model.set("matchingQuestionLayout", "w");


                    if (this.model.get("isMobile")) {
                        $.global.culture = $.global.cultures["ja-Japanese"];
                    } else {
                        $.global.culture = $.global.cultures["ja-English"];
                    }

                }
            },
            /**
             * iscrollを使用するかどうか
             *
             * TODO iscrollを使わない方向で検討すること
             */
            setIscroll: function () {

                if (!this.model.isPC()) {

                    //TODO jQuery.support.fixedPosition の代わり　1.7にアップデートするタイミングで変更すること
                    if (navigator.userAgent.indexOf('OS 5') !== -1 || navigator.userAgent.indexOf('OS 6') !== -1 || navigator.userAgent.indexOf('OS 7') !== -1  || navigator.userAgent.indexOf('OS 8') !== -1 || ($.os.name === "linux" && $.browser.name === "safari")) {
                        //iOS 5　は、iScrollを使わない
                        this.model.set("isUseIScroll", false);
                        //TODO あとで最適化すること
                        $('<style />', {
                            type: 'text/css',
                            text: '#bookIndexView .wrapper{height:500px;}' +
                                '#bookIndexView .wrapper{padding-bottom:50px;}'
                        }).appendTo('head');

                    } else {
                        this.model.set("isUseIScroll", true);
                    }

                }
            },
            /**
             * Windowを閉じようとしたとき
             */
            windowOnBeforeunload: function (event) {
                if (this.questionModel.get("isStart") && !this.questionModel.get("isEndDril")) {
                    event = event || window.event;
                    // haoの場合
//                    return event.returnValue = '途中終了になります。終了しますか？';
                    event.returnValue = '途中終了になります。終了しますか？\n終了した場合は、途中までの結果が保存されます。 ';
                    return event.returnValue;
                }
            },
            /**
             * Windowを閉じるとき
             */
            windowOnUnload: function () {
                if (!this.model.get("isPreview") || this.model.get("isDemo")) {
                    if (window.opener !== null && window.opener !== undefined && this.questionModel.get("isStart")) {

                        if (this.model.get("lesson_no")) {

                            if ('function' === typeof window.opener.customizedTrainingLesson_reload) {
                                window.opener.customizedTrainingLesson_reload(this.model.get("lesson_no"));
                            }


                        } else {


                            if ('function' === typeof window.opener.customizedTraining_reload) {
                                window.opener.customizedTraining_reload();
                            }
                        }
                    }
                }
            },

            /**
             * playerを描画する
             */
            render: function () {

                this.$el.append(this.template);

                this.createTimeUpContainer();
                this.createPrintContainer();

                return this;
            },

            createPrintContainer: function () {
                console.log("Player.createPrintContainer()");
                var printContainer = $.mustache(printContainerTemplate, {
                    noPrint: $.global.culture.player.views.noPrint
                });
                this.$el.append(printContainer);
            },

            createTimeUpContainer: function () {
                console.log("Player.createTimeUpContainer()");
                var timeUpContainer = $.mustache(timeUpContainerTemplate, {
                    timeUp: $.global.culture.player.views.timeUp
                });
                this.$el.append(timeUpContainer);
            },
            /**
             * 学習データを読み込む
             */
            loadData: function () {
                this.showLoading();
                this.questionModel.loadQuestionData();
            },
            /**
             * ローディング画面を表示する
             */
            showLoading: function () {
                console.log("Player.loadingContainer()");
                this.loadingContainer = new LoadingContainer();
                this.loadingContainer.render();
                this.$el.append(this.loadingContainer.el);
            },
            /**
             * ローディング画面を隠す
             */
            hideLoading: function () {
                this.loadingContainer.$el.fadeOut("slow", $.proxy(this._onHideLoading, this));
            },

            /**
             * モデルのデータ（問題）読み込み完了
             */
            _onLoadModelData: function () {
                this.hideLoading();
            },
            /**
             * ローディング画面が隠れたイベント
             */
            _onHideLoading: function () {

                $("body").css("backgroundColor", "#FFFFFF");

                if (this.model.get("isReview")) {
                    //TODO とりあえず
                    this._viewReview();
                } else {
                    if (this.model.get("previewType") === "assign_vc" && this.model.get("visionary") === "vcet") {
                        this._showSystemCheckWindow();
                    } else {
                        this.startPlayer();
                    }
                }
            },
            /**
             * レビュー画面を表示する
             */
            _viewReview: function () {
                //ローディング画面を削除する
                this.loadingContainer.remove();

                var reviewView = new ReviewView({
                    model: this.questionModel
                });
                reviewView.render();
            },

            /**
             * 学習画面をスタートする
             */
            startPlayer: function () {
                //ローディング画面を削除する
                this.loadingContainer.remove();

                var controller = new QuestionController({
                    el : "#container",
                    model: this.questionModel
                });
                controller.render();
            },
            /**
             * システムチェック画面を表示する
             */
            _showSystemCheckWindow: function () {

                this.$el.append(wrapperTemplate);

                this.systemCheckView = new SystemCheckView({ el: $("#popupBox2") });

                this.systemCheckView.on("clickCloseButton", $.proxy(this._onClickNgCloseButtonButton, this));
                this.systemCheckView.on("clickStartButton", $.proxy(this._onClickOkStartButtonButton, this));

                this.systemCheckView.render();

            },
            /**
             * システムチェック後　OKだった場合の次へボタンの処理
             */
            _onClickOkStartButtonButton: function (event) {
                this.startPlayer();
            },

            /**
             * システムチェック後　NGだった場合のウィンドウを閉じるボタン
             */
            _onClickNgCloseButtonButton: function (event) {
                window.close();
            },

            /**
             * 答えを保存するときにセッションタイムした場合
             */
            _onSendAnswerError: function () {

                var template, html;


                template = errorSessionTimeoutTemplates;
                html = $.mustache(template, null);

                this.$el.append(html);

                $("#errorCloseButton").click(
                    $.proxy(this._onClickErrorCloseButtonButton, this)
                );

                $.fancybox(
                    $("#popupBox"),
                    {
                        'type': 'inline',
                        'openEffect': 'none',
                        'closeEffect': 'none',
                        'closeBtn': false,
                        'helpers': {
                            overlay: {
                                closeClick: false,
                                css: {
                                    'background': 'rgba(255, 255, 255, 0.9)'
                                }
                            }
                        }
                    }
                );

            },

            /**
             * セッションタイムした場合のクローズボタン処理
             */
            _onClickErrorCloseButtonButton: function (event) {

                event.preventDefault();

                if (window.opener !== null) {
                    window.opener.location.reload(true);
                }
                window.close();

            }


        });
    }
);
