var AudioPlayer = function () {
	var instances = [];
	var activePlayerID;
	var playerURL = "";
	var defaultOptions = {};
	var currentVolume = -1;
	var requiredFlashVersion = "9";
	
	function getPlayer(playerID) {

		if (document.all && !window[playerID]) {
			for (var i = 0; i < document.forms.length; i++) {
				if (document.forms[i][playerID]) {
					return document.forms[i][playerID];
					break;
				}
			}
		}
		return document.all ? window[playerID] : document[playerID];

	}
	
	function addListener (playerID, type, func) {
		getPlayer(playerID).addListener(type, func);
	}
	
	return {
		setup: function (url, options) {
			playerURL = url;
			defaultOptions = options;
			if (swfobject.hasFlashPlayerVersion(requiredFlashVersion)) {
				swfobject.switchOffAutoHideShow();
				swfobject.createCSS("p.audioplayer_container span", "visibility:hidden;height:24px;overflow:hidden;padding:0;border:none;");
			}
		},

		getPlayer: function (playerID) {
			return getPlayer(playerID);
		},
		
		addListener: function (playerID, type, func) {
			addListener(playerID, type, func);
		},
		
		embed: function (elementID, options) {
			
			var instanceOptions = {};
			var key;
			
			var flashParams = {};
			var flashVars = {};
			var flashAttributes = {};
	
			// Merge default options and instance options
			for (key in defaultOptions) {
				instanceOptions[key] = defaultOptions[key];
			}
			for (key in options) {
				instanceOptions[key] = options[key];
			}
			
			if (instanceOptions.transparentpagebg == "yes") {
				flashParams.bgcolor = "#FFFFFF";
				flashParams.wmode = "transparent";
			} else {
				if (instanceOptions.pagebg) {
					flashParams.bgcolor = "#" + instanceOptions.pagebg;
				}
				flashParams.wmode = "opaque";
			}
			
			flashParams.menu = "false";
			
			for (key in instanceOptions) {
				if (key == "pagebg" || key == "width" || key == "transparentpagebg") {
					continue;
				}
				flashVars[key] = instanceOptions[key];
			}
			
			flashAttributes.name = elementID;
			flashAttributes.style = "outline: none";
			
			flashVars.playerID = elementID;
			
			swfobject.embedSWF(playerURL, elementID, instanceOptions.width.toString(), "24", requiredFlashVersion, false, flashVars, flashParams, flashAttributes);
			instances.push(elementID);
		},
		
		syncVolumes: function (playerID, volume) {	
			currentVolume = volume;
			for (var i = 0; i < instances.length; i++) {
				if (instances[i] != playerID) {
					getPlayer(instances[i]).setVolume(currentVolume);
				}
			}
		},
		
		activate: function (playerID, info) {
			//alert("activate:"+playerID);
			if (activePlayerID && activePlayerID != playerID) {
				getPlayer(activePlayerID).close();
			}

			activePlayerID = playerID;
		},
		
		load: function (playerID, soundFile, titles, artists) {
			getPlayer(playerID).load(soundFile, titles, artists);
		},
		
		close: function (playerID) {
			getPlayer(playerID).close();
			if (playerID == activePlayerID) {
				activePlayerID = null;
			}
		},
		
		open: function (playerID, index) {
			if (index == undefined) {
				index = 1;
			}
			getPlayer(playerID).open(index == undefined ? 0 : index-1);
		},
		
		getVolume: function (playerID) {
			return currentVolume;
		}
		
	}
	
}();

define("audio-player", function(){});

//--------------------------------------------------------------------
// soundapi.js
// Unoh Inc. 2006/11/02
// version 1.000
//--------------------------------------------------------------------



var JsSoundPlayer = new Object();
JsSoundPlayer.swf_path= 'soundapi.swf';
JsSoundPlayer.player = null;

JsSoundPlayer.listeners = new Array();

JsSoundPlayer.setup = function(swf_path){

    JsSoundPlayer.swf_path = swf_path;

}
JsSoundPlayer.embed = function(player_id){

    swfobject.embedSWF(JsSoundPlayer.swf_path, player_id, "1", "1",  "8", false);

    JsSoundPlayer.player = (navigator.appName.indexOf("Microsoft") != -1) ? window[player_id] : document[player_id];

}

JsSoundPlayer.play = function(soundpath){
    JsSoundPlayer.player.playFile(soundpath);
}
JsSoundPlayer.stop = function(soundpath){
    JsSoundPlayer.player.stopFile(soundpath);
}
JsSoundPlayer.onloadPlayer = function(){

    for(var o in JsSoundPlayer.listeners){

        JsSoundPlayer.listeners[o].onLoadJsSoundPlayer();

    }

}
JsSoundPlayer.onEndPlay = function(){

    for(var o in JsSoundPlayer.listeners){

        JsSoundPlayer.listeners[o].onPlayEndJsSoundPlayer();

    }

}
JsSoundPlayer.addListener = function(listener){
    JsSoundPlayer.listeners.push(listener);
    // alert("JsSoundPlayer.addListener:"+JsSoundPlayer.listeners.length);
}
JsSoundPlayer.removeListener = function(listener){
   
    // alert("JsSoundPlayer.removeListener_s:"+JsSoundPlayer.listeners.length);
    
    for(i = 0; i < JsSoundPlayer.listeners.length; i++){
        if(JsSoundPlayer.listeners[i] == listener ){
            // alert("JsSoundPlayer.removeListener_e:xxxxx");
            JsSoundPlayer.listeners.splice(i,1);
        }
    }

    // alert("JsSoundPlayer.removeListener_e:"+JsSoundPlayer.listeners.length);
    
}

//--------------------------------------------------------------------



