/**
 * countDownTimerPlugin
 *
 * @param {Object} $
 */
(function ($) {
    
    //Plugin名
    var name_space = 'countDownTimerPlugin';
    $.fn[name_space] = function (options) {
        var elements, _processTime, _lastOfTime, _isStartTimer, _timerInterval, settings, scope;





        //いったん退避
        elements = this;
        /** 経過時間 */
        _processTime = 0;
        /** 残り時間 */
        _lastOfTime = 0;

        /** タイマーがスタートしているかどうか */
        _isStartTimer = false;

        /** 制限時間用インターバルID */
        _timerInterval = -1;

        //設定情報の構築
        settings = $.extend($.fn[name_space].defaults, options);

        scope = this;

        /**
         *
         */
        function __getFormatTime() {
            var formatTimeime, s, m;

            formatTimeime = "";
            //分
            s = Math.floor(_lastOfTime / 60);
            //秒
            m = _lastOfTime - s * 60;
            formatTimeime += $.StringUtilPlugin.addZero(s) + ":" + $.StringUtilPlugin.addZero(m);
            return formatTimeime;
        }

        function __draw() {
            elements.html(settings.title + __getFormatTime().toString);
        }
        /**
         *
         */
        function stopTimer() {
            _isStartTimer = false;

            //$.logger.debug("stopTimer::::_timerInterval:" + _timerInterval);

            clearInterval(_timerInterval);
        }


        /**
         *
         */
        function clearTimer() {
            _lastOfTime = settings.limitTime;
            __draw();
        }
        /**
         *
         */
        function __timeUp() {
            $.logger.debug("__timeUp");
            stopTimer();
            if (settings.timeup !== null) {
                settings.timeup();
            }
            //dispatchEvent({type:TIME_UP_EVENT, target:this});
        }
        /**
         *
         */
        function __countUpTime() {

            //$.logger.debug("_timerInterval:" + _timerInterval);

            _processTime++;
            _lastOfTime = settings.limitTime - _processTime;

            if (_lastOfTime === 0) {
                __timeUp();
            }
            __draw();
        }
        /**
         * 制限時間タイマーを開始する
         */
        function startTimer() {
            $.subscribe('/QuestionModel/end', $.proxy(scope.stopTimer, scope));

            _isStartTimer = true;
            _timerInterval = setInterval(__countUpTime, 1000);
            //$.logger.debug("startTimer");
            __draw();
        }

        //要素を一個ずつ処理
        elements.each(function () {
            startTimer();
        });

        //method chain
        return this;
    };

    $.fn[name_space].defaults = {
        //制限時間
        'limitTime': 0.1 * 60, /* ３分 */
        //タイムアップイベント
        timeup: null,
        title: ""
    };

}(jQuery));
